def detect_os():
    """
    Detects the operating system on which the code is running.

    Returns:
        str: The name of the operating system ('cygwin', 'mac', 'linux', 'wsl', 'windows', 'bsd', or 'unknown').
    """
    syst = system().lower()
    os = 'unknown'

    if 'cygwin' in syst:
        os = 'cygwin'
    elif 'darwin' in syst:
        os = 'mac'
    elif 'linux' in syst:
        os = 'linux'

    # Detect WSL
    try:
        with open('/proc/version', 'r') as f:
            if 'microsoft' in f.read().lower():
                os = 'wsl'
    except:
        pass

    if 'windows' in syst:
        os = 'windows'
    elif 'bsd' in syst:
        os = 'bsd'

    return os

