def legitimize(text, os=detect_os()):
    # Normalize text for different operating systems
    if os == 'windows' or os == 'cygwin' or os == 'wsl':
        # Replace characters reserved in Windows file systems
        text = text.translate({ord(c): '-' for c in ':*?\\\"+<>[]\t'})
    elif os == 'mac':
        # Replace colon reserved in Mac OS file systems
        text = text.translate({ord(':'): '-'})
    # Remove leading dot and trim to 80 Unicode characters
    if text.startswith('.'):
        text = text[1:]
    return text[:80]

