def _bind_parameters(operation, parameters):
    # This function binds parameters to an SQL operation string.
    # It iterates over the parameters dictionary, converting each value to the appropriate SQL format.
    # If the value is None, it converts it to 'NULL'.
    # If the value is a string, it escapes the string and encloses it in single quotes.
    # For other types, it converts the value to a string.
    # Finally, it returns the operation string with the parameters bound.
    string_parameters = {}
    for name, value in parameters.items():
        if value is None:
            string_parameters[name] = 'NULL'
        elif isinstance(value, str):
            string_parameters[name] = "'" + _escape(value) + "'"
        else:
            string_parameters[name] = str(value)
    return operation % string_parameters

