def run_table_upsert(self, dataset_id, table_resource, project_id=None):
    # Check if the table exists
    table_id = table_resource['tableReference']['tableId']
    project_id = project_id if project_id is not None else self.project_id
    tables_list_resp = self.service.tables().list(projectId=project_id, datasetId=dataset_id).execute(num_retries=self.num_retries)

    while True:
        for table in tables_list_resp.get('tables', []):
            if table['tableReference']['tableId'] == table_id:
                # Table exists, update it
                self.log.info('Table %s:%s.%s exists, updating.', project_id, dataset_id, table_id)
                return self.service.tables().update(projectId=project_id, datasetId=dataset_id, tableId=table_id, body=table_resource).execute(num_retries=self.num_retries)

        # Check for next page
        if 'nextPageToken' in tables_list_resp:
            tables_list_resp = self.service.tables().list(projectId=project_id, datasetId=dataset_id, pageToken=tables_list_resp['nextPageToken']).execute(num_retries=self.num_retries)
        else:
            # Table does not exist, insert it
            self.log.info('Table %s:%s.%s does not exist. creating.', project_id, dataset_id, table_id)
            return self.service.tables().insert(projectId=project_id, datasetId=dataset_id, body=table_resource).execute(num_retries=self.num_retries)

