def call(self, path, query=None, get_all_pages=True, side_loading=False):
    """
    Calls the Zendesk API to retrieve data from a specified path.

    Args:
        path (str): The API endpoint path.
        query (dict, optional): Query parameters for the API request. Defaults to None.
        get_all_pages (bool, optional): Whether to fetch all pages of results. Defaults to True.
        side_loading (bool, optional): Whether to include related resources in the response. Defaults to False.

    Returns:
        dict: The results from the API call.

    Raises:
        RateLimitError: If the API rate limit is exceeded.
        ZendeskError: If an error occurs during the API call.
    """
    zendesk = self.get_conn()
    first_request_successful = False
    while not first_request_successful:
        try:
            results = zendesk.call(path, query)
            first_request_successful = True
        except RateLimitError as rle:
            self.__handle_rate_limit_exception(rle)

    keys = [path.split("/")[-1].split(".json")[0]]
    next_page = results['next_page']
    if side_loading:
        keys += query['include'].split(',')

    results = {key: results[key] for key in keys}

    if get_all_pages:
        while next_page is not None:
            try:
                next_url = next_page.split(self.__url)[1]
                self.log.info("Calling %s", next_url)
                more_res = zendesk.call(next_url)
                for key in results:
                    results[key].extend(more_res[key])
                if next_page == more_res['next_page']:
                    break
                else:
                    next_page = more_res['next_page']
            except RateLimitError as rle:
                self.__handle_rate_limit_exception(rle)
            except ZendeskError as ze:
                if b"Use a start_time older than 5 minutes" in ze.msg:
                    break
                else:
                    raise ze

    return results

