    ).filter(models.TaskInstance.dag_id.in_(simple_dag_bag.dag_ids)).filter(models.TaskInstance.state.in_(old_states)).filter(
        or_(models.DagRun.state != State.RUNNING, models.DagRun.state.is_(None))
    )

    if self.using_sqlite:
        tis_to_change = query.with_for_update().all()
        for ti in tis_to_change:
            ti.set_state(new_state, session=session)
            tis_changed += 1
    else:
        subq = query.subquery()
        tis_changed = session.query(models.TaskInstance).filter(
            and_(models.TaskInstance.dag_id == subq.c.dag_id, models.TaskInstance.task_id == subq.c.task_id,
                 models.TaskInstance.execution_date == subq.c.execution_date)
        ).update({models.TaskInstance.state: new_state}, synchronize_session=False)
        session.commit()

    if tis_changed > 0:
        self.log.warning("Set %s task instances to state=%s as their associated DagRun was not in RUNNING state", tis_changed, new_state)

