def process_file(self, file_path, zombies, pickle_dags=False, session=None):
    self.log.info("Processing file %s for tasks to queue", file_path)
    simple_dags = []
    try:
        dagbag = models.DagBag(file_path, include_examples=False)
    except Exception:
        self.log.exception("Failed at reloading the DAG file %s", file_path)
        Stats.incr('dag_file_refresh_error', 1, 1)
        return []

    if len(dagbag.dags) > 0:
        self.log.info("DAG(s) %s retrieved from %s", dagbag.dags.keys(), file_path)
    else:
        self.log.warning("No viable dags retrieved from %s", file_path)

    self.update_import_errors(session, dagbag)
    if len(self.dag_ids) > 0:
        dags = [dag for dag in dagbag.dags.values() if dag.dag_id in self.dag_ids and dag.dag_id not in paused_dag_ids]
    else:
        dags = [dag for dag in dagbag.dags.values() if not dag.parent_dag and dag.dag_id not in paused_dag_ids]

    ti_keys_to_schedule = []
    self._process_dags(dagbag, dags, ti_keys_to_schedule)

    for ti_key in ti_keys_to_schedule:
        dag = dagbag.dags[ti_key[0]]
        task = dag.get_task(ti_key[1])
        ti = models.TaskInstance(task, ti_key[2])
        ti.refresh_from_db(session=session, lock_for_update=True)
        dep_context = DepContext(deps=QUEUE_DEPS, ignore_task_deps=True)
        if ti.are_dependencies_met(dep_context=dep_context, session=session, verbose=True):
            ti.state = State.SCHEDULED
            self.log.info("Creating / updating %s in ORM", ti)
            session.merge(ti)
            session.commit()

    try:
        self.update_import_errors(session, dagbag)
    except Exception:
        self.log.exception("Error logging import errors!")

    try:
        dagbag.kill_zombies(zombies)
    except Exception:
        self.log.exception("Error killing zombies!")

    return simple_dags

