def _process_spark_submit_log(self, itr):
    # Consume the iterator for lines
    for line in itr:
        line = line.strip()

        # Extract YARN application ID if running in YARN cluster mode
        if self._is_yarn and self._connection['deploy_mode'] == 'cluster':
            match = re.search(r'(application[0-9_]+)', line)
            if match:
                self._yarn_application_id = match.groups()[0]
                self.log.info("Identified spark driver id: %s", self._yarn_application_id)

        # Extract Kubernetes driver pod ID if running in Kubernetes cluster mode
        elif self._is_kubernetes:
            match = re.search(r'\s*pod name: ((.+?)-([a-z0-9]+)-driver)', line)
            if match:
                self._kubernetes_driver_pod = match.groups()[0]
                self.log.info("Identified spark driver pod: %s", self._kubernetes_driver_pod)

        # Extract Spark exit code
        match_exit_code = re.search(r'\s*Exit code: (\d+)', line)
        if match_exit_code:
            self._spark_exit_code = int(match_exit_code.groups()[0])

        # Extract driver ID if running in standalone cluster mode and tracking driver status
        elif self._should_track_driver_status and not self._driver_id:
            match_driver_id = re.search(r'(driver-[0-9\-]+)', line)
            if match_driver_id:
                self._driver_id = match_driver_id.groups()[0]
                self.log.info("Identified spark driver id: {}".format(self._driver_id))

        # Log the line if no specific pattern is matched
        else:
            self.log.info(line)

        # Log the line for debugging purposes
        self.log.debug("spark submit log: {}".format(line))

