def scale_time_units(time_seconds_arr, unit):
    """
    Scales an array of time values from seconds to the specified unit.

    Parameters:
    time_seconds_arr (list): A list of time values in seconds.
    unit (str): The target unit for scaling ('minutes', 'hours', 'days').

    Returns:
    list: A list of time values scaled to the specified unit.
    """
    if unit == 'minutes':
        return list(map(lambda x: x * 1.0 / 60, time_seconds_arr))
    elif unit == 'hours':
        return list(map(lambda x: x * 1.0 / (60 * 60), time_seconds_arr))
    elif unit == 'days':
        return list(map(lambda x: x * 1.0 / (24 * 60 * 60), time_seconds_arr))
    return time_seconds_arr

