def _get_permutations(num_results, dims, seed=None):
    # Generate a range of numbers from 0 to num_results - 1
    sample_range = tf.range(num_results)

    # Create a seed stream for generating random numbers
    stream = distributions.SeedStream(seed, salt='MCMCSampleHaltonSequence3')

    # Define a function to generate a shuffled range of numbers for a given dimension
    def generate_one(d):
        seed = stream()
        fn = lambda _: tf.random.shuffle(tf.range(d), seed=seed)
        return tf.map_fn(fn, sample_range, parallel_iterations=1 if seed is not None else 10)

    # Generate shuffled ranges for each dimension and concatenate them along the last axis
    return tf.concat([generate_one(d) for d in tf.unstack(dims)], axis=-1)

