                return shape, shape_tensor
            return (tf.broadcast_static_shape(event_shape, shape), tf.broadcast_dynamic_shape(event_shape_tensor, shape_tensor))

        for aff in endpoint_affine:
            if aff.shift is not None:
                batch_shape = tf.broadcast_static_shape(batch_shape, aff.shift.shape[:-1])
                batch_shape_tensor = tf.broadcast_dynamic_shape(batch_shape_tensor, tf.shape(input=aff.shift)[:-1])
                event_shape, event_shape_tensor = _set_event_shape(aff.shift.shape[-1:], tf.shape(input=aff.shift)[-1:])
            if aff.scale is not None:
                batch_shape = tf.broadcast_static_shape(batch_shape, aff.scale.batch_shape)
                batch_shape_tensor = tf.broadcast_dynamic_shape(batch_shape_tensor, aff.scale.batch_shape_tensor())
                event_shape, event_shape_tensor = _set_event_shape(tf.TensorShape([aff.scale.range_dimension]), aff.scale.range_dimension_tensor()[tf.newaxis])

