def linop_scale(w, op):
    """
    Scales a linear operator by a scalar value `w`.

    Args:
    w (float): The scalar value to scale the linear operator.
    op (tf.linalg.LinearOperator): The linear operator to be scaled.

    Returns:
    tf.linalg.LinearOperator: The scaled linear operator.

    Raises:
    NotImplementedError: If the type of the linear operator is not supported.
    """
    with tf.name_scope("linop_scale"):
        if isinstance(op, tf.linalg.LinearOperatorIdentity):
            return scaled_identity(w)
        elif isinstance(op, tf.linalg.LinearOperatorScaledIdentity):
            return scaled_identity(w * op.multiplier)
        elif isinstance(op, tf.linalg.LinearOperatorDiag):
            return tf.linalg.LinearOperatorDiag(
                diag=w[..., tf.newaxis] * op.diag_part(),
                is_non_singular=op.is_non_singular,
