def broadcast_batch_shape(distributions):
    # Initialize batch_shape with the batch_shape of the first distribution
    batch_shape = distributions[0].batch_shape

    # Iterate through each distribution to broadcast the batch_shape
    for distribution in distributions:
        batch_shape = tf.broadcast_static_shape(batch_shape, distribution.batch_shape)

    # If the batch_shape is fully defined, return it as a list
    if batch_shape.is_fully_defined():
        return batch_shape.as_list()

    # If not fully defined, use dynamic broadcasting
    batch_shape = distributions[0].batch_shape_tensor()
    for distribution in distributions:
        batch_shape = tf.broadcast_dynamic_shape(batch_shape, distribution.batch_shape_tensor())

    # Convert the final batch_shape to a tensor and return
    return tf.convert_to_tensor(value=batch_shape)

