def make_iaf_stack(total_event_size, num_hidden_layers=2, seed=None, dtype=tf.float32):
    """Create a stack of IAF (Inverse Autoregressive Flow) and swap bijectors."""
    seed = tfd.SeedStream(seed, 'make_iaf_stack')

    def make_iaf():
        """Create an IAF bijector."""
        initializer = tf.compat.v2.keras.initializers.VarianceScaling(2 * 0.01, seed=seed() % (2 ** 31 - 1))
        made = tfb.AutoregressiveLayer(params=2, event_shape=[total_event_size], hidden_units=[total_event_size] * num_hidden_layers, activation=tf.nn.elu, kernel_initializer=initializer, dtype=dtype)
        def shift_and_scale(x):
            x.set_shape(x.shape.merge_with([None] * (x.shape.ndims - 1) + [total_event_size]))
            return tf.unstack(made(x), num=2, axis=-1)
        return tfb.Invert(tfb.MaskedAutoregressiveFlow(shift_and_scale))

    def make_swap():
        """Create a swap bijector."""
        permutation = list(reversed(range(total_event_size)))
        return tfb.Permute(permutation)

    bijector = make_iaf()
    bijector = make_swap()(bijector)
    bijector = make_iaf()(bijector)
    bijector = make_swap()(bijector)
    bijector = make_iaf()(bijector)
    bijector = make_swap()(bijector)

    return bijector

