def make_mixture_prior(latent_size, mixture_components):
    if mixture_components == 1:
        return tfd.MultivariateNormalDiag(loc=tf.zeros([latent_size]), scale_identity_multiplier=1.0)
    else:
        loc = tf.compat.v1.get_variable(name="loc", shape=[mixture_components, latent_size])
        raw_scale_diag = tf.compat.v1.get_variable(name="raw_scale_diag", shape=[mixture_components, latent_size])
        mixture_logits = tf.compat.v1.get_variable(name="mixture_logits", shape=[mixture_components])
        return tfd.MixtureSameFamily(
            components_distribution=tfd.MultivariateNormalDiag(loc=loc, scale_diag=tf.nn.softplus(raw_scale_diag)),
            mixture_distribution=tfd.Categorical(logits=mixture_logits),
            name="prior"
        )


