def _call_and_reshape_output(self, fn, event_shape_list=None, static_event_shape_list=None, extra_kwargs=None):
    # Ensure event_shape_list and static_event_shape_list are provided
    if event_shape_list is None:
        event_shape_list = [self._event_shape_tensor()]
    if static_event_shape_list is None:
        static_event_shape_list = [self.event_shape]

    # Calculate the new shape by concatenating batch shape and event shape list
    new_shape = tf.concat([self._batch_shape_unexpanded] + event_shape_list, axis=0)

    # Apply the function and reshape the result
    if extra_kwargs:
        result = tf.reshape(fn(**extra_kwargs), new_shape)
    else:
        result = tf.reshape(fn(), new_shape)

    # Determine the static shape if ranks are known
    if tensorshape_util.rank(self.batch_shape) is not None and tensorshape_util.rank(self.event_shape) is not None:
        event_shape = tf.TensorShape([])
        for rss in static_event_shape_list:
            event_shape = tensorshape_util.concatenate(event_shape, rss)
        static_shape = tensorshape_util.concatenate(self.batch_shape, event_shape)
        tensorshape_util.set_shape(result, static_shape)

    return result

