def _assert_same_base_type(items, expected_type=None):
    """
    Asserts that all items in the list have the same base data type.

    Parameters:
    items (list): A list of items to check.
    expected_type (type, optional): The expected base data type. If not provided, it will be inferred from the first item.

    Returns:
    type: The base data type of the items.

    Raises:
    ValueError: If any item in the list does not have the same base data type as the expected type.
    """
    original_expected_type = expected_type
    mismatch = False

    for item in items:
        if item is not None:
            item_type = base_dtype(item.dtype)
            if not expected_type:
                expected_type = item_type
            elif expected_type != item_type:
                mismatch = True
                break

    if mismatch:
        expected_type = original_expected_type
        original_item_str = None
        get_name = lambda x: x.name if hasattr(x, 'name') else str(x)

        for item in items:
            if item is not None:
                item_type = base_dtype(item.dtype)
                if not expected_type:
                    expected_type = item_type
                original_item_str = get_name(item)
                if expected_type != item_type:
                    raise ValueError(
                        '{} (type={}, must be of the same type ({}){}.'.format(
                            get_name(item), item_type, expected_type,
                            (' as {}'.format(original_item_str)) if original_item_str else ''
                        )
                    )

    return expected_type  # Should be unreachable

