def _prefer_static(original_fn, static_fn):
    """
    Decorator to prefer a static function over an original function if the arguments match.

    Args:
        original_fn (function): The original function to be decorated.
        static_fn (function): The static function to be used if arguments match.

    Returns:
        function: A wrapped function that prefers the static function if arguments match.

    Raises:
        ValueError: If the argument specifications of the original and static functions do not match.
    """
    original_spec = tf_inspect.getfullargspec(original_fn)
    static_spec = tf_inspect.getfullargspec(static_fn)

    if original_spec != static_spec:
        raise ValueError('Arg specs do not match: original={}, static={}, fn={}'.format(original_spec, static_spec, original_fn))

    @decorator.decorator
    def wrap(wrapped_fn, *args, **kwargs):
        del wrapped_fn
        args_, kwargs_, all_static = _maybe_get_static_args([args, kwargs])

        if all_static:
            return static_fn(*args_, **kwargs_)
        else:
            return original_fn(*args, **kwargs)

    return wrap(original_fn)

