def make_diag_scale(loc=None, scale_diag=None, scale_identity_multiplier=None, shape_hint=None, validate_args=False, assert_positive=False, name=None, dtype=None):
    """
    Creates a diagonal scaling operator.

    Args:
        loc (Tensor): Location tensor.
        scale_diag (Tensor): Diagonal scaling tensor.
        scale_identity_multiplier (Tensor): Multiplier for the identity matrix.
        shape_hint (Tensor): Shape hint tensor.
        validate_args (bool): Whether to validate arguments.
        assert_positive (bool): Whether to assert that the diagonal part is positive.
        name (str): Name of the operation.
        dtype (DType): Data type of the tensors.

    Returns:
        LinearOperator: A diagonal scaling operator.
    """
    def _maybe_attach_assertion(x):
        if not validate_args:
            return x
        if assert_positive:
            return with_dependencies([assert_util.assert_positive(x, message="diagonal part must be positive")], x)
        return with_dependencies([assert_util.assert_none_equal(x, tf.zeros([], x.dtype), message="diagonal part must be non-zero")], x)

    with tf.name_scope(name or "make_diag_scale"):
        if dtype is None:
            dtype = dtype_util.common_dtype([loc, scale_diag, scale_identity_multiplier], preferred_dtype=tf.float32)
        loc = _convert_to_tensor(loc, name="loc", dtype=dtype)
        scale_diag = _convert_to_tensor(scale_diag, name="scale_diag", dtype=dtype)
        scale_identity_multiplier = _convert_to_tensor(scale_identity_multiplier, name="scale_identity_multiplier", dtype=dtype)

        if scale_diag is not None:
            if scale_identity_multiplier is not None:
                scale_diag += scale_identity_multiplier[..., tf.newaxis]
            return tf.linalg.LinearOperatorDiag(diag=_maybe_attach_assertion(scale_diag), is_non_singular=True, is_self_adjoint=True, is_positive_definite=assert_positive)

        if loc is None and shape_hint is None:
            raise ValueError("Cannot infer `event_shape` unless `loc` or `shape_hint` is specified.")

        num_rows = shape_hint
        del shape_hint
        if num_rows is None:
            num_rows = tf.compat.dimension_value(loc.shape[-1])
        if num_rows is None:
            num_rows = tf.shape(input=loc)[-1]

        if scale_identity_multiplier is None:
            return tf.linalg.LinearOperatorIdentity(num_rows=num_rows, dtype=dtype, is_self_adjoint

