def _largest_integer_by_dtype(dt):
    if not _is_known_dtype(dt):
        raise TypeError("Unrecognized dtype: {}".format(dt.name))
    if dt.is_floating:
        return int(2 ** (np.finfo(dt.as_numpy_dtype).nmant + 1))
    if dt.is_integer:
