def embed_check_categorical_event_shape(categorical_param, name="embed_check_categorical_event_shape"):
    with tf.name_scope(name):
        x = tf.convert_to_tensor(value=categorical_param, name="categorical_param")

        # Determine the maximum event size based on the data type
        x_dtype = dtype_util.base_dtype(x.dtype)
        max_event_size = _largest_integer_by_dtype(x_dtype) if dtype_util.is_floating(x_dtype) else 0

        if max_event_size == 0:
            raise TypeError("Unable to validate size of unrecognized dtype ({})".format(dtype_util.name(x_dtype)))

        try:
            x_shape_static = tensorshape_util.with_rank_at_least(x.shape, 1)
        except ValueError:
            raise ValueError("A categorical-distribution parameter must have at least 1 dimension.")

        event_size = tf.compat.dimension_value(x_shape_static[-1])

        if event_size is not None:
            if event_size < 2:
                raise ValueError("A categorical-distribution parameter must have at least 2 events.")
            if event_size > max_event_size:
                raise ValueError("Number of classes exceeds `dtype` precision, i.e., {} implies shape ({}) cannot exceed {}.".format(dtype_util.name(x_dtype), event_size, max_event_size))
        else:
            event_size = tf.shape(input=x, out_type=tf.int64, name="x_shape")[-1]
            with_dependencies([
                assert_util.assert_rank_at_least(x, 1, message="A categorical-distribution parameter must have at least 1 dimension."),
                assert_util.assert_greater_equal(tf.shape(input=x)[-1], 2, message="A categorical-distribution parameter must have at least 2 events."),
                assert_util.assert_less_equal(event_size, tf.convert_to_tensor(max_event_size, dtype=tf.int64), message="Number of classes exceeds `dtype` precision, i.e., {} dtype cannot exceed {} shape.".format(dtype_util.name(x_dtype), max_event_size)),
