def _secant2_inner_update(value_and_gradients_function, initial_args, val_0, val_c, f_lim, sufficient_decrease_param, curvature_param):
    # Check if `val_c` is no longer finite and update the `failed` and `active` flags accordingly.
    new_failed = initial_args.active & ~is_finite(val_c)
    active = initial_args.active & ~new_failed
    failed = initial_args.failed | new_failed

    # Check if the Wolfe conditions are satisfied and update `val_left` and `val_right` accordingly.
    found_wolfe = active & _satisfies_wolfe(val_0, val_c, f_lim, sufficient_decrease_param, curvature_param)
    val_left = val_where(found_wolfe, val_c, initial_args.left)
    val_right = val_where(found_wolfe, val_c, initial_args.right)
    converged = initial_args.converged | found_wolfe
    active = active & ~found_wolfe

    # If any active batch members remain, apply the `update` function to squeeze further their corresponding left/right bracketing interval.
    def _apply_update():
        update_result = update(value_and_gradients_function, val_left, val_right, val_c, f_lim, active=active)
        return _Secant2Result(active=tf.zeros_like(active), converged=converged, failed=failed | update_result.failed, num_evals=initial_args.num_evals + update_result.num_evals, left=update_result.left, right=update_result.right)

    # Otherwise, just return the current results.
    def _default():
        return _Secant2Result(active=active, converged=converged, failed=failed, num_evals=initial_args.num_evals, left=val_left, right=val_right)

    return prefer_static.cond(tf.reduce_any(input_tensor=active), _apply_update, _default)

