def _maybe_validate_distributions(distributions, dtype_override, validate_args):
    """
    Validates a list of distributions.

    Args:
        distributions (list): A list of distributions to validate.
        dtype_override (dtype, optional): An optional dtype to override the distributions' dtypes.
        validate_args (bool, optional): Whether to validate the arguments.

    Returns:
        list: A list of assertions if validation is enabled, otherwise an empty list.

    Raises:
        ValueError: If the distributions are not iterable or if they do not have the same dtype or event_ndims.
        TypeError: If the distributions do not have the same dtype.
    """
    if not _is_iterable(distributions) or not distributions:
        raise ValueError("`distributions` must be a list of one or more distributions.")

    if dtype_override is None:
        dts = [dtype_util.base_dtype(d.dtype) for d in distributions if d.dtype is not None]
        if dts[1:] != dts[:-1]:
            raise TypeError("Distributions must have the same dtype; found: {}.".format(set(dtype_util.name(dt) for dt in dts)))

    # Validate event_ndims.
    for d in distributions:
