def _update_inv_hessian(prev_state, next_state):
    # Determine if the inverse Hessian should be updated
    should_update = ~next_state.converged & ~next_state.failed

    # Compute the normalization term (y^T . s)
    gradient_delta = next_state.objective_gradient - prev_state.objective_gradient
    position_delta = next_state.position - prev_state.position
    normalization_factor = tf.reduce_sum(gradient_delta * position_delta, axis=-1)
    should_update = should_update & ~tf.equal(normalization_factor, 0)

    def _do_update_inv_hessian():
        next_inv_hessian = _bfgs_inv_hessian_update(gradient_delta, position_delta, normalization_factor, prev_state.inverse_hessian_estimate)
        return bfgs_utils.update_fields(next_state, inverse_hessian_estimate=tf.where(should_update, next_inv_hessian, prev_state.inverse_hessian_estimate))

    return prefer_static.cond(tf.reduce_any(should_update), _do_update_inv_hessian, lambda: next_state)

