def build_is_last_day_of_season(num_steps_per_season):
    # Calculate the total number of steps per season
    num_steps_per_cycle = np.sum(num_steps_per_season)
    # Calculate the changepoints where each season ends
    changepoints = np.cumsum(np.ravel(num_steps_per_season)) - 1

    def is_last_day_of_season(t):
        # Get the static value of t if available
        t_ = dist_util.maybe_get_static_value(t)
        if t_ is not None:
            # Static case: calculate the step within the cycle
            step_in_cycle = t_ % num_steps_per_cycle
            # Check if the step is at any changepoint
            return any(step_in_cycle == changepoints)
        else:
            # Dynamic case: calculate the step within the cycle using TensorFlow
            step_in_cycle = tf.math.floormod(t, num_steps_per_cycle)
            # Check if the step is at any changepoint using TensorFlow
            return tf.reduce_any(input_tensor=tf.equal(step_in_cycle, changepoints))

    return is_last_day_of_season

