def build_constrained_seasonal_transition_noise(drift_scale, num_seasons, is_last_day_of_season):
    # Constructs a lower-triangular scale factor for the seasonal transition noise.
    drift_scale_tril_nonzeros = tf.concat([
        tf.ones([num_seasons - 1, 1], dtype=drift_scale.dtype),
        tf.zeros([num_seasons - 1, num_seasons - 2], dtype=drift_scale.dtype)
    ], axis=-1)
    drift_scale_tril = (drift_scale_tril_nonzeros * drift_scale[..., tf.newaxis, tf.newaxis] / num_seasons)

    # Returns a MultivariateNormalTriL distribution for the seasonal transition noise.
    def seasonal_transition_noise(t):
        noise_scale_tril = dist_util.pick_scalar_condition(
            is_last_day_of_season(t), drift_scale_tril, tf.zeros_like(drift_scale_tril)
        )
        return tfd.MultivariateNormalTriL(
            loc=tf.zeros(num_seasons - 1, dtype=drift_scale.dtype),
            scale_tril=noise_scale_tril
        )

    return seasonal_transition_noise

