def summary_gradient_updates(grads, opt, lr):
    # Initialize a dictionary to store variable names and their corresponding variables, gradients, and AdaGrad slots
    vars_grads = {v.name: [v, None, None] for v in tf.trainable_variables()}

    # Populate the dictionary with gradients and AdaGrad slots
    for g, v in grads:
        vars_grads[v.name][1] = g
        vars_grads[v.name][2] = opt.get_slot(v, 'accumulator')

    # Create summaries for each variable
    ret = []
    for vname, (v, g, a) in vars_grads.items():
        if g is None:
            continue

        if isinstance(g, tf.IndexedSlices):
            # Handle sparse gradients
            updates = lr * g.values
            if a is not None:
                updates /= tf.sqrt(tf.gather(a, g.indices))
        else:
            updates = lr * g
            if a is not None:
                updates /= tf.sqrt(a)

        values_norm = tf.sqrt(tf.reduce_sum(v * v)) + 1.0e-7
        updates_norm = tf.sqrt(tf.reduce_sum(updates * updates))

        ret.append(tf.summary.scalar('UPDATE/' + vname.replace(":", "_"), updates_norm / values_norm))

    return ret

