    else:
        # Raise an exception if no dataset configuration is provided
        raise Exception("No dataset configuration provided in the JSON config.")

    try:
        # Extract reader configuration from the main config
        reader_config = dict(config['dataset_reader'])
    except KeyError:
        # Raise an exception if no dataset reader is provided
