def labels2onehot(labels: Union[List[str], List[List[str]], np.ndarray], classes: Union[List[str], np.ndarray]) -> np.ndarray:
    n_classes = len(classes)
    y = []
    for sample in labels:
        curr = np.zeros(n_classes)
        if isinstance(sample, list):
            for intent in sample:
                if intent not in classes:
                    log.warning(f'Unknown intent {intent} detected. Assigning no class')
                else:
                    curr[np.where(np.array(classes) == intent)[0]] = 1
        else:
            curr[np.where(np.array(classes) == sample)[0]] = 1
        y.append(curr)
    y = np.asarray(y)
    return y

