def stacked_highway_cnn(units: tf.Tensor, n_hidden_list: List, filter_width=3, use_batch_norm=False, use_dilation=False, training_ph=None):
    for n_layer, n_hidden in enumerate(n_hidden_list):
        input_units = units
        if input_units.get_shape().as_list()[-1] != n_hidden:
            input_units = tf.layers.dense(input_units, n_hidden)

        if use_dilation:
            dilation_rate = 2 ** n_layer
        else:
            dilation_rate = 1

        units = tf.layers.conv1d(units, n_hidden, filter_width, padding='same', dilation_rate=dilation_rate, kernel_initializer=INITIALIZER())

        if use_batch_norm:
            units = tf.layers.batch_normalization(units, training=training_ph)

        sigmoid_gate = tf.layers.dense(input_units, 1, activation=tf.sigmoid, kernel_initializer=INITIALIZER())
        input_units = sigmoid_gate * input_units + (1 - sigmoid_gate) * units
        input_units = tf.nn.relu(input_units)
        units = input_units

    return units


**Summary:**
The `stacked_highway_cnn` function processes a 1D input tensor through a series of highway layers. Each layer includes a convolutional operation, optional batch normalization, and a highway gate mechanism. The highway gate combines the current input and the output of the convolutional layer based on a sigmoid gate, allowing the network to selectively pass information. The function supports dilation in convolutional layers to capture long-range dependencies and can be configured to use batch normalization for improved training stability.

