def _make_default_operation_costs(self, allow_spaces=False):
    # Initialize the operation costs dictionary
    self.operation_costs = {""}
    # Set default costs for each character and space
    for c in list(self.alphabet) + [' ']:
        self.operation_costs[""][c] = 1.0
    # Set costs for each character
    for a in self.alphabet:
        current_costs = {c: 1.0 for c in self.alphabet}
        current_costs[a] = 0.0
        current_costs[""] = 1.0
        if allow_spaces:
            current_costs[" "] = 1.0
        self.operation_costs[a] = current_costs
    # Set costs for transpositions
    for a, b in itertools.permutations(self.alphabet, 2):
        self.operation_costs[a + b] = {b + a: 1.0}
    # Set costs for spaces if allowed
    if allow_spaces:
        self.operation_costs[" "] = {c: 1.0 for c in self.alphabet}
        self.operation_costs[" "][""] = 1.0

