def _get_method_full_name(func):
    # Check if the function has a __qualname__ attribute (available in Python 3.3+)
    if hasattr(func, "__qualname__"):
        return func.__qualname__

    # Get the module where the function is defined
    module = inspect.getmodule(func)
    if module is None:
        return "?.%s" % getattr(func, "__name__", "?")

    # Iterate through all attributes in the module
    for cls_name in dir(module):
        cls = getattr(module, cls_name)
        if not inspect.isclass(cls):
            continue

        # Iterate through all attributes in the class
        for method_name in dir(cls):
            cls_method = getattr(cls, method_name)
            if cls_method == func:
                return "%s.%s" % (cls_name, method_name)

    # If the function is not found in any class, return the module and function name
    if hasattr(func, "__name__"):
        return "%s.%s" % (module.__name__, func.__name__)

    # If all else fails, return "<unknown>"
    return "<unknown>"

