def _get_type_name(vtype, dump=None):
    """
    Returns a string representation of the type of the given value.

    Args:
        vtype: The value whose type is to be determined.
        dump: An optional argument that may be used for additional processing.

    Returns:
        A string representing the type of the value.

    Raises:
        RuntimeError: If the type of the value is unexpected.
    """
    if vtype is None:
        return "None"
    elif vtype is str:
        return "string"
    elif vtype is int:
        return "integer"
    elif vtype is numeric:
        return "numeric"
    elif is_type(vtype, str):
        return '"%s"' % repr(vtype)[1:-1]
    elif is_type(vtype, int):
        return str(vtype)
    elif isinstance(vtype, MagicType):
        return vtype.name(dump)
    elif isinstance(vtype, type):
        return vtype.__name__
    elif isinstance(vtype, list):
        return "list(%s)" % _get_type_name(U(*vtype), dump)
    elif isinstance(vtype, set):
        return "set(%s)" % _get_type_name(U(*vtype), dump)
    elif isinstance(vtype, tuple):
        return "(%s)" % ", ".join(_get_type_name(item, dump) for item in vtype)
    elif isinstance(vtype, dict):
        return "dict(%s)" % ", ".join("%s: %s" % (_get_type_name(tk, dump), _get_type_name(tv, dump)) for tk, tv in viewitems(vtype))
    elif isinstance(vtype, (FunctionType, BuiltinFunctionType)):
        if vtype.__name__ == "<lambda>":
            return _get_lambda_source_code(vtype, dump)
        else:
            return vtype.__name__
    else:
        raise RuntimeError("Unexpected `vtype`: %r" % vtype)

