def quantile(self, prob=None, combine_method="interpolate", weights_column=None):
    """
    Calculates the quantiles of a dataset.

    Parameters:
    - prob (list, optional): A list of probabilities at which to calculate the quantiles. Default is [0.01, 0.1, 0.25, 0.333, 0.5, 0.667, 0.75, 0.9, 0.99].
    - combine_method (str, optional): The method to combine the quantiles. Default is "interpolate".
    - weights_column (str or H2OFrame, optional): The column or frame containing the weights for the quantile calculation. Default is None.

    Returns:
    - H2OFrame: A frame containing the calculated quantiles.
    """
    if len(self) == 0:
        return self

    if prob is None:
        prob = [0.01, 0.1, 0.25, 0.333, 0.5, 0.667, 0.75, 0.9, 0.99]

    if weights_column is None:
        weights_column = "_"
    else:
        assert_is_type(weights_column, str, I(H2OFrame, lambda wc: wc.ncol == 1 and wc.nrow == self.nrow))

    if isinstance(weights_column, H2OFrame):
        merged = self.cbind(weights_column)
        weights_column = merged.names[-1]

    return H2OFrame._expr(expr=ExprNode("quantile", merged if isinstance(weights_column, H2OFrame) else self, prob, combine_method, weights_column))

