def get_human_readable_bytes(size):
    """
    Converts a byte size into a human-readable format (e.g., KB, MB, GB).

    Parameters:
    size (int): The size in bytes to be converted.

    Returns:
    str: The human-readable representation of the size.

    Raises:
    AssertionError: If the size is negative or not an integer.
    """
    if size == 0:
        return "0"
    if size is None:
        return ""
    assert isinstance(size, int), "`size` must be an integer"
    assert size >= 0, "`size` cannot be negative, got %d" % size

    suffixes = "PTGMk"
    maxl = len(suffixes)

    for i in range(maxl + 1):
        shift = (maxl - i) * 10
        if size >> shift == 0:
            continue
        ndigits = 0
        for nd in [3, 2, 1]:
            if size >> (shift + 12 - nd * 3) == 0:
                ndigits = nd
                break
        if ndigits == 0 or size == (size >> shift) << shift:
            rounded_val = str(size >> shift)
        else:
            rounded_val = "%.*f" % (ndigits, size / (1 << shift))
        return "%s %sb" % (rounded_val, suffixes[i] if i < maxl else "")

