def _get_readable_id(id_name, id_prefix_to_skip):
    # Extracts the readable part of an ID by removing the namespace and prefix.
    # id_name is expected to be in the form 'https://namespace.host.suffix/name'.
    # If id_prefix_to_skip is provided, it removes that prefix as well.
    pos = id_name.find('//')
    if pos != -1:
        pos += 2
        if id_prefix_to_skip:
            pos = id_name.find(id_prefix_to_skip, pos)
            if pos != -1:
                pos += len(id_prefix_to_skip)
        pos = id_name.find('/', pos)
        if pos != -1:
            return id_name[pos + 1:]
    return id_name

