async def send(self, messages, message_timeout=0, session=None, **kwargs):
    async with self.get_sender(message_timeout=message_timeout, session=session, **kwargs) as sender:
        if isinstance(messages, Message):
            sender.queue_message(messages)
        else:
            try:
                messages = list(messages)
            except TypeError:
                raise TypeError("Value of messages must be a 'Message' object or a synchronous iterable of 'Message' objects.")
            for m in messages:
                if not isinstance(m, Message):
                    raise TypeError("Item in iterator is not of type 'Message'.")
                sender.queue_message(m)
    return await sender.send_pending_messages()


**Summary:**
This asynchronous method `send` is designed to send messages using a sender object. It accepts a single message or an iterable of messages, along with optional parameters for message timeout and session. The method ensures that all messages are instances of the `Message` class and queues them for sending. Finally, it sends all pending messages and returns the result.

