def _update_management_header(self, request, x_ms_version):
    """
    Updates the headers of the given request based on the HTTP method and other parameters.

    Args:
        request (Request): The request object to update.
        x_ms_version (str): The version of the service to use.

    Returns:
        list: The updated headers of the request.
    """
    if request.method in ['PUT', 'POST', 'MERGE', 'DELETE']:
        request.headers.append(('Content-Length', str(len(request.body))))

    request.headers.append(('x-ms-version', x_ms_version or self.x_ms_version))

    if request.method not in ['GET', 'HEAD']:
        for name, _ in request.headers:
            if 'content-type' == name.lower():
                break
        else:
            request.headers.append(('Content-Type', self.content_type))

    return request.headers

