def _update_request_uri_query(self, request):
    # Check if the request path contains a query string
    if '?' in request.path:
        request.path, _, query_string = request.path.partition('?')
        if query_string:
            # Split the query string into individual query parameters
            query_params = query_string.split('&')
            for query in query_params:
                if '=' in query:
                    # Split each query parameter into name and value
                    name, _, value = query.partition('=')
                    request.query.append((name, value))

    # Encode the request path and query parameters
    request.path = url_quote(request.path, '/()$=\',')
    if request.query:
        request.path += '?'
        for name, value in request.query:
            if value is not None:
                request.path += name + '=' + url_quote(value, '/()$=\',') + '&'
        request.path = request.path[:-1]

    return request.path, request.query

