def as_batch_body(self):
    # Check if the Python version is 3 and the body is of type bytes
    if sys.version_info >= (3,) and isinstance(self.body, bytes):
        # Decode the body from bytes to UTF-8 string
        body = self.body.decode('utf-8')
    else:
        # For Python 2.7, the body is handled manually
        body = self.body

    # Create a dictionary with the body
    result = {'Body': body}

    # Add custom properties if they exist
    if self.custom_properties:
        result['UserProperties'] = {name: self._serialize_basic_properties_value(value) for name, value in self.custom_properties.items()}

    # Add broker properties if they exist
    if self.broker_properties:
        result['BrokerProperties'] = {name: self._serialize_basic_properties_value(value) for name, value in self.broker_properties.items()}

