def task_collection_thread_handler(self, results_queue):
    # Continuously add tasks to the queue until either there are no more tasks to add or an unexpected error occurs.
    while self.tasks_to_add and not self.errors:
        max_tasks = self._max_tasks_per_request  # Maximum number of tasks to add in one batch
        chunk_tasks_to_add = []  # List to hold the current batch of tasks to add

        with self._pending_queue_lock:
            # Pop tasks from the main tasks list and add them to the current batch until the maximum is reached
            while len(chunk_tasks_to_add) < max_tasks and self.tasks_to_add:
                chunk_tasks_to_add.append(self.tasks_to_add.pop())

        # If there are tasks in the current batch, add them to the results queue
        if chunk_tasks_to_add:
            self._bulk_add_tasks(results_queue, chunk_tasks_to_add)

