def resolve_stream_name(streams, stream_name):
    # Check if the stream_name is a synonym and exists in the streams dictionary
    if stream_name in STREAM_SYNONYMS and stream_name in streams:
        # Iterate through the streams dictionary
        for name, stream in streams.items():
            # Check if the current stream matches the stream_name and the name is not a synonym
            if stream is streams[stream_name] and name not in STREAM_SYNONYMS:
                return name
    # If no matching name is found, return the original stream_name
    return stream_name

