    available_plugins.sort(key=lambda x: x.priority(url), reverse=True)

    # If there are available plugins, use the highest priority one to handle the URL
    if available_plugins:
        return available_plugins[0](url)

    # If follow_redirect is True, attempt to handle a redirect URL
    if follow_redirect:
        try:
            # Send a HEAD request to the URL
            res = self.http.head(url, allow_redirects=True, acceptable_status=[501])

            # If the server doesn't handle HEAD, send a GET request
            if res.status_code == 501:
                res = self.http.get(url, stream=True)

            # If the URL has changed, recursively call resolve_url with the new URL
            if res.url != url:
                return self.resolve_url(res.url, follow_redirect=follow_redirect)
        except PluginError:
            pass

    # If no plugin can handle the URL, raise a NoPluginError
    raise NoPluginError

