def mnemonic(self, index, verbose=False):
    if index < 16:
        return ['last', '2last', '3last', '4last', 'last-1', 'last+1', 'last-2', 'last+2', 'last-3', 'last+3', '2last-1', '2last+1', '2last-2', '2last+2', '2last-3', '2last+3'][index]
    if index < 16 + self.NDIRECT:
        return str(index - 16)
    index -= self.NDIRECT + 16
    hcode = index >> self.NPOSTFIX
    lcode = index & (1 << self.NPOSTFIX) - 1
    if self.NPOSTFIX:
        formatString = '1{0}{1}{2:0{3}b}{4:+d}'
    else:
        formatString = '1{0}{1}{4:+d}'
    return formatString.format(hcode & 1, 'x' * (2 + hcode >> 1) if hcode < 13 or verbose else '[{}*x]'.format(2 + hcode >> 1), lcode, self.NPOSTFIX, self.NDIRECT + 1 - (4 << self.NPOSTFIX))

