def delayed(f):
    def wrapped(*args, **kwargs):
        # Promisify all arguments and keyword arguments
        arg_promises = [promisify(value) for value in args]
        kwarg_promises = [(key, promisify(value)) for key, value in kwargs.items()]
        promises = arg_promises + [promise for key, promise in kwarg_promises]

        # Define error and echo functions for promise callbacks
        def echo_error(exc, promise=promise):
            print("error with", promise, "exception is", exc)
            raise exc

        def echo(value, promise=promise):
            print("done with", repr(promise), "value is", value)

        # Create a list of promises and handle them
        allarguments = aplus.listPromise(*promises)
        def call(_):
            kwargs_real = {key: promise.get() for key, promise in kwarg_promises}
            args_real = [promise.get() for promise in arg_promises]
            return f(*args_real, **kwargs_real)
        def error(exc):
            print("error", exc)
            raise exc
        return allarguments.then(call, error)
    return wrapped

