def _root_nodes(self):
    # Initialize lists to keep track of leaf nodes and root nodes
    root_nodes = []
    leafes = []

    def walk(node):
        # Recursively walk through the expression graph
        if isinstance(node, six.string_types):
            # If the node is a leaf, add it to the leafes list
            leafes.append(node)
            if node in root_nodes:
                # If the node is also a root node, remove it from the root_nodes list
                root_nodes.remove(node)
        else:
            node_repr, fname, fobj, deps = node
            if node_repr in self.virtual_columns:
                # If the node is a virtual column, add it to the leafes list
                leafes.append(node_repr)
                if node_repr in root_nodes:
                    # If the node is also a root node, remove it from the root_nodes list
                    root_nodes.remove(node_repr)
            # Recursively walk through the dependencies
            for dep in deps:
                walk(dep)

    # Iterate through virtual columns
    for column in self.virtual_columns.keys():
        if column not in leafes:
            # If the column is not a leaf, add it to the root_nodes list
            root_nodes.append(column)
        node = self[column]._graph()
        # Walk through the dependencies of the node
        node_repr, fname, fobj, deps = node
        for dep in deps:
            walk(dep)

    return root_nodes

