def estimate_tuning(y=None, sr=22050, S=None, n_fft=2048, resolution=0.01, bins_per_octave=12, **kwargs):
    # Extract pitch and magnitude using piptrack
    pitch, mag = piptrack(y=y, sr=sr, S=S, n_fft=n_fft, **kwargs)

    # Create a mask for pitch values greater than 0
    pitch_mask = pitch > 0

    # Calculate the threshold for magnitude if there are any valid pitch values
    if pitch_mask.any():
        threshold = np.median(mag[pitch_mask])
    else:
        threshold = 0.0

    # Estimate tuning by filtering pitch values based on the threshold and pitch mask
    return pitch_tuning(pitch[(mag >= threshold) & pitch_mask], resolution=resolution, bins_per_octave=bins_per_octave)

