def clicks(times=None, frames=None, sr=22050, hop_length=512, click_freq=1000.0, click_duration=0.1, click=None, length=None):
    """
    Generates a click signal based on the provided parameters.

    Parameters:
    - times: List of times at which clicks should occur.
    - frames: List of frames at which clicks should occur.
    - sr: Sample rate of the audio signal.
    - hop_length: Number of samples between frames.
    - click_freq: Frequency of the click sound.
    - click_duration: Duration of the click sound.
    - click: Audio buffer for the click sound.
    - length: Length of the output click signal.

    Returns:
    - click_signal: Generated click signal as a numpy array.
    """
    if times is None and frames is None:
        raise ValueError('either "times" or "frames" must be provided')

    if times is not None:
        positions = time_to_samples(times, sr=sr)
    else:
        positions = frames_to_samples(frames, hop_length=hop_length)

    if click is not None:
        if not util.valid_audio(click, mono=True):
            raise ValueError('click must be a valid audio buffer')
    else:
        if click_duration <= 0:
            raise ValueError('click_duration must be strictly positive')
        if click_freq <= 0:
            raise ValueError('click_freq must be strictly positive')
        angular_freq = 2 * np.pi * click_freq / float(sr)
        click = np.logspace(0, -10, num=int(np.round(sr * click_duration)), base=2.0)
        click *= np.sin(angular_freq * np.arange(len(click)))

    if length is None:
        length = positions.max() + click.shape[0]
    else:
        if length < 1:
            raise ValueError('length must be a positive integer')

    positions = positions[positions < length]
    click_signal = np.zeros(length, dtype=np.float32)

    for start in positions:
        end = start + click.shape[0]
        if end >= length:
            click_signal[start:] += click[:length - start]
        else:
            click_signal[start:end] += click

    return click_signal

