def beat_track(y=None, sr=22050, onset_envelope=None, hop_length=512, start_bpm=120.0, tightness=100, trim=True, bpm=None, units='frames'):
    # If no onset envelope is provided, compute it from the audio signal
    if onset_envelope is None:
        if y is None:
            raise ParameterError('y or onset_envelope must be provided')
        onset_envelope = onset.onset_strength(y=y, sr=sr, hop_length=hop_length, aggregate=np.median)

    # Check if there are any onsets
    if not onset_envelope.any():
        return (0, np.array([], dtype=int))

    # Estimate BPM if not provided
    if bpm is None:
        bpm = tempo(onset_envelope=onset_envelope, sr=sr, hop_length=hop_length, start_bpm=start_bpm)[0]

    # Run the beat tracker
    beats = __beat_tracker(onset_envelope, bpm, float(sr) / hop_length, tightness, trim)

    # Convert beat positions to the desired units
    if units == 'frames':
        pass
    elif units == 'samples':
        beats = core.frames_to_samples(beats, hop_length=hop_length)
    elif units == 'time':
        beats = core.frames_to_time(beats, hop_length=hop_length, sr=sr)
    else:
        raise ParameterError('Invalid unit type: {}'.format(units))

    return (bpm, beats)

