def get_frame(self, frame_id):
    # Check if the frame_id is within the valid range
    if frame_id < 0 or frame_id >= self._frame_cnt:
        raise IndexError('"frame_id" must be between 0 and {}'.format(self._frame_cnt - 1))

    # If the requested frame is the current position, read and return it
    if frame_id == self._position:
        return self.read()

    # If caching is enabled, try to retrieve the frame from the cache
    if self._cache:
        img = self._cache.get(frame_id)
        if img is not None:
            self._position = frame_id + 1
            return img

    # Set the real position to the requested frame_id
    self._set_real_position(frame_id)

    # Read the frame from the video capture object
    ret, img = self._vcap.read()
    if ret:
        # If caching is enabled, store the read frame in the cache
        if self._cache:
            self._cache.put(self._position, img)
        self._position += 1
        return img

