def load_checkpoint(model, filename, map_location=None, strict=False, logger=None):
    # Load a checkpoint from a model zoo, file, or URL.
    if filename.startswith('modelzoo://'):
        # Load from torchvision model zoo.
        model_urls = {}
        for _, name, ispkg in pkgutil.walk_packages(torchvision.models.__path__):
            if not ispkg:
                _zoo = import_module(f'torchvision.models.{name}')
                _urls = getattr(_zoo, 'model_urls')
                model_urls.update(_urls)
        model_name = filename[11:]
        checkpoint = model_zoo.load_url(model_urls[model_name])
    elif filename.startswith('open-mmlab://'):
        # Load from open-mmlab model zoo.
        model_name = filename[13:]
        checkpoint = model_zoo.load_url(open_mmlab_model_urls[model_name])
    elif filename.startswith(('http://', 'https://')):
        # Load from a URL.
        checkpoint = model_zoo.load_url(filename)
    else:
        # Load from a local file.
        if not osp.isfile(filename):
            raise IOError(f'{filename} is not a checkpoint file')
        checkpoint = torch.load(filename, map_location=map_location)

    # Extract state_dict from checkpoint.
    if isinstance(checkpoint, OrderedDict):
        state_dict = checkpoint
    elif isinstance(checkpoint, dict) and 'state_dict' in checkpoint:
        state_dict = checkpoint['state_dict']
    else:
        raise RuntimeError(f'No state_dict found in checkpoint file {filename}')

    # Strip 'module.' prefix from state_dict keys if present.
    if list(state_dict.keys())[0].startswith('module.'):
        state_dict = {k[7:]: v for k, v in state_dict.items()}

    # Load state_dict into the model.
    if hasattr(model, 'module'):
        load_state_dict(model.module, state_dict, strict, logger)
    else:
        load_state_dict(model, state_dict, strict, logger)

    return checkpoint

