def _automatic_dims(cls, dims, size):
    """
    Determines the dimensions of a quantum system based on the given size and dimensions.

    Args:
        cls (class): The class that the method belongs to.
        dims (int or tuple of int or None): The dimensions of the quantum system. If None, it is set to the size.
        size (int): The total number of qubits or elements in the quantum system.

    Returns:
        tuple of int: The dimensions of the quantum system.

    Raises:
        QiskitError: If the product of the dimensions does not match the size.
    """
    if dims is None:
        dims = size
    elif np.product(dims) != size:
        raise QiskitError("dimensions do not match size.")

    if isinstance(dims, (int, np.integer)):
        num_qubits = int(np.log2(dims))
        if 2 ** num_qubits == size:
            return num_qubits * (2,)
        return (dims,)

    return tuple(dims)

