def to_instruction(self):
    from qiskit.circuit.instruction import Instruction

    # Check if the input is an N-qubit CPTP channel
    n_qubits = int(np.log2(self._input_dim))
    if self._input_dim != self._output_dim or 2 ** n_qubits != self._input_dim:
        raise QiskitError('Cannot convert QuantumChannel to Instruction: channel is not an N-qubit channel.')
    if not self.is_cptp():
        raise QiskitError('Cannot convert QuantumChannel to Instruction: channel is not CPTP.')

    # Convert to the Kraus representation
    kraus, _ = _to_kraus(self.rep, self._data, *self.dim)

    # If there is only one Kraus operator, the channel is unitary and can be converted to a UnitaryGate
    if len(kraus) == 1:
        return Operator(kraus[0]).to_instruction()

    # Otherwise, return a Kraus instruction
    return Instruction('kraus', n_qubits, 0, kraus)

