def translate(self, date_string, keep_formatting=False, settings=None):
    # Translate numerals in the date string
    date_string = self._translate_numerals(date_string)

    # Normalize unicode if settings require
    if settings.NORMALIZE:
        date_string = normalize_unicode(date_string)

    # Simplify the date string using provided settings
    date_string = self._simplify(date_string, settings=settings)

    # Get the translation dictionary based on settings
    dictionary = self._get_dictionary(settings)

    # Split the date string into tokens using the dictionary
    date_string_tokens = dictionary.split(date_string, keep_formatting)

    # Get relative translations based on settings
    relative_translations = self._get_relative_translations(settings=settings)

    # Iterate over each token, convert to lowercase, and apply relative translations
    for i, word in enumerate(date_string_tokens):
        word = word.lower()
        for pattern, replacement in relative_translations.items():
            if pattern.match(word):
                date_string_tokens[i] = pattern.sub(replacement, word)
            else:
                if word in dictionary:
                    date_string_tokens[i] = dictionary[word] or ''

    # Clear future words if "in" is present in the tokens
    if "in" in date_string_tokens:
        date_string_tokens = self._clear_future_words(date_string_tokens)

    # Join the filtered tokens into a single string with appropriate separator
    return self._join(list(filter(bool, date_string_tokens)), separator="" if keep_formatting else " ", settings=settings)

