def expand_time(str_time, default_unit='s', multiplier=1):
    """
    Converts a time string with units (e.g., '1h30m') into total seconds, with optional default unit and multiplier.

    Parameters:
    str_time (str): The time string to convert.
    default_unit (str): The default unit to use if no unit is specified in the string. Default is 's' (seconds).
    multiplier (int): A multiplier to apply to the final result. Default is 1.

    Returns:
    int: The total time in seconds, multiplied by the given multiplier.

    Raises:
    ValueError: If the string contains an unsupported unit.
    """
    parser = re.compile(r'(\d+)([a-zA-Z]*)')
    parts = parser.findall(str_time)
    result = 0.0

    for value, unit in parts:
        value = int(value)
        unit = unit.lower()

        if unit == '':
            unit = default_unit

        if unit == 'ms':
            result += value * 0.001
        elif unit == 's':
            result += value
        elif unit == 'm':
            result += value * 60
        elif unit == 'h':
            result += value * 60 * 60
        elif unit == 'd':
            result += value * 60 * 60 * 24
        elif unit == 'w':
            result += value * 60 * 60 * 24 * 7
        else:
            raise ValueError(f"String contains unsupported unit {unit}: {str_time}")

    return int(result * multiplier)

