def _feed(self):
    # Initialize the plan using StpdReader
    self.plan = StpdReader(self.stpd_filename)
    # If cached_stpd is True, convert the plan to a list
    if self.cached_stpd:
        self.plan = list(self.plan)

    # Iterate over each task in the plan
    for task in self.plan:
        # Check if the quit flag is set
        if self.quit.is_set():
            logger.info("Stop feeding: gonna quit")
            return

        # Try to put the task into the task_queue
        while True:
            try:
                self.task_queue.put(task, timeout=1)
                break
            except Full:
                # If the queue is full, check if the quit flag is set or all workers have exited
                if self.quit.is_set() or self.workers_finished:
                    return
                else:
                    continue

    # Log the number of workers and publish killer tasks
    workers_count = self.instances
    logger.info("Feeded all data. Publishing %d killer tasks" % (workers_count))
    retry_delay = 1
    for _ in range(5):
        try:
            for _ in range(workers_count):
                self.task_queue.put(None, timeout=1)
            break
        except Full:
            logger.debug("Couldn't post killer tasks because queue is full. Retrying in %ss", retry_delay)
            time.sleep(retry_delay)
            retry_delay *= 2

    # Wait for all workers to exit
    try:
        logger.info("Waiting for workers")
        map(lambda x: x.join(), self.pool)
        logger.info("All workers exited.")
        self.workers_finished = True
    except (KeyboardInterrupt, SystemExit):
        self.task_queue.close()
        self.results.close()
        self.quit.set()
        logger.info("Going to quit. Waiting for workers")
        map(lambda x: x.join(), self.pool)
        self.workers_finished = True

