def parse_duration(duration):
    # Define a regular expression to tokenize the duration string
    _re_token = re.compile("([0-9.]+)([dhms]?)")

    # Define a dictionary to map time units to their respective multipliers in milliseconds
    multipliers = {
        'd': 86400,  # 1 day in seconds
        'h': 3600,   # 1 hour in seconds
        'm': 60,     # 1 minute in seconds
        's': 1       # 1 second in seconds
    }

    # Function to parse a single token and convert it to milliseconds
    def parse_token(time, multiplier):
        if multiplier:
            if multiplier in multipliers:
                return int(float(time) * multipliers[multiplier] * 1000)
            else:
                raise StepperConfigurationError(f'Failed to parse duration: {duration}')
        else:
            return int(float(time) * 1000)

    # Sum up the parsed values of all tokens
    return sum(parse_token(*token) for token in _re_token.findall(duration))

