def get_terminal_size():
    """
    Returns the terminal size as a tuple (width, height).
    If the size cannot be determined, it returns a default size of (30, 120).
    """
    default_size = (30, 120)
    env = os.environ

    def ioctl_gwinsz(file_d):
        """
        Helper function to get the console size using ioctl.
        """
        try:
            sizes = struct.unpack('hh', fcntl.ioctl(file_d, termios.TIOCGWINSZ, '1234'))
        except Exception:
            sizes = default_size
        return sizes

    sizes = ioctl_gwinsz(0) or ioctl_gwinsz(1) or ioctl_gwinsz(2)
    if not sizes:
        try:
            file_d = os.open(os.ctermid(), os.O_RDONLY)
            sizes = ioctl_gwinsz(file_d)
            os.close(file_d.fileno())
        except Exception:
            pass
    if not sizes:
        try:
            sizes = (env['LINES'], env['COLUMNS'])
        except Exception:
            sizes = default_size
    return int(sizes[1]), int(sizes[0])

