def build(self, pipeline_def, artifacts_persisted):
    # Initialize a dependency dictionary where each step key maps to an empty set
    deps = {step.key: set() for step in self.steps}

    # Populate the dependency dictionary with step inputs and their previous output handles
    for step in self.steps:
        for step_input in step.step_inputs:
            deps[step.key].add(step_input.prev_output_handle.step_key)

    # Create a dictionary mapping step keys to step objects
    step_dict = {step.key: step for step in self.steps}

    # Return an ExecutionPlan object with the pipeline definition, step dictionary, dependency dictionary, and artifacts persisted
    return ExecutionPlan(pipeline_def, step_dict, deps, artifacts_persisted)

