def annotate(self, **annotations):
    # Create a dictionary of fields from the model
    fields = {field.name: field for field in self.model._meta.get_fields()}

    # Initialize dictionaries for new annotations and renames
    new_annotations = {}
    renames = {}

    # Iterate over the provided annotations
    for name, value in annotations.items():
        if name in fields:
            # If the annotation name conflicts with a field name, rename it
            new_name = f'{name}_new'
            new_annotations[new_name] = value
            renames[new_name] = name
        else:
            # Otherwise, keep the annotation name as is
            new_annotations[name] = value

    # Call the base class's annotate function with the new annotations
    result = super().annotate(**new_annotations)

    # Rename the annotations back to their original names
    result.rename_annotations(**renames)

    return result

