def _build_conflict_target(self):
    # Initialize conflict_target list
    conflict_target = []

    # Check if conflict_target is a list
    if not isinstance(self.query.conflict_target, list):
        raise SuspiciousOperation(f"{self.query.conflict_target} is not a valid conflict target. Specify a list of column names or tuples with column names and hstore keys.")

    # Define a helper function to assert valid field names
    def _assert_valid_field(field_name):
        field_name = self._normalize_field_name(field_name)
        if self._get_model_field(field_name):
            return
        raise SuspiciousOperation(f"{field_name} is not a valid conflict target. Specify a list of column names or tuples with column names and hstore keys.")

    # Validate each field name in conflict_target
    for field_name in self.query.conflict_target:
        _assert_valid_field(field_name)

    # Special handling for hstore keys
    for field_name in self.query.conflict_target:
        if isinstance(field_name, tuple):
            conflict_target.append(f"({self._format_field_name(field_name)}->'{field_name[1]}')")
        else:
            conflict_target.append(self._format_field_name(field_name))

    # Join conflict_target elements and return
    return '(%s)' % ','.join(conflict_target)

