def __execute_from_remote(self, cmd):
    result = None
    retries = 0
    while retries < self.MAX_RETRIES:
        try:
            result = subprocess.check_output(cmd, shell=True)
            break
        except subprocess.CalledProcessError as ex:
            logger.error("gerrit cmd %s failed: %s", cmd, ex)
            time.sleep(self.RETRY_WAIT * retries)
            retries += 1
    if result is None:
        result = RuntimeError(cmd + " failed " + str(self.MAX_RETRIES) + " times. Giving up!")
    if self.archive:
        cmd = self.sanitize_for_archive(cmd)
        self.archive.store(cmd, None, None, result)
    if isinstance(result, RuntimeError):
        raise result
    return result


**Summary:**
This method executes a command remotely using `subprocess.check_output`. It retries the command up to `MAX_RETRIES` times if it fails. If all retries fail, it raises a `RuntimeError`. If logging and archiving are enabled, it logs the error and stores the command and result in an archive. Finally, it returns the result or re-raises the error if it's a `RuntimeError`.

