def normalize(s, nonorm=False, preserve_case=False):
    # Bypass NIST-style pre-processing if nonorm is True
    if nonorm:
        return s.split()

    # Handle cases where s is not a string
    try:
        s.split()
    except:
        s = " ".join(s)

    # Language-independent normalization
    for pattern, replace in normalize1:
        s = re.sub(pattern, replace, s)
    s = xml.sax.saxutils.unescape(s, {'&quot;': '"'})

    # Language-dependent normalization for Western languages
    s = " %s " % s
    if not preserve_case:
        s = s.lower()

    # Split the string into tokens and return
    return [tok for tok in normalize3.split(s) if tok and tok != ' ']

