def cook_refs(refs, n=4):
    # Normalize each reference in the list
    refs = [normalize(ref) for ref in refs]

    # Initialize a dictionary to store the maximum counts of n-grams
    maxcounts = {}

    # Iterate over each reference
    for ref in refs:
        # Count the n-grams in the reference
        counts = count_ngrams(ref, n)

        # Update the maximum counts for each n-gram
        for ngram, count in counts.items():
            maxcounts[ngram] = max(maxcounts.get(ngram, 0), count)

    # Return a tuple containing the lengths of the references and the maximum counts of n-grams
    return ([len(ref) for ref in refs], maxcounts)

