def match_delta(self, value):
    # Search for a delta pattern in the input value using a regular expression.
    m = self.REGEX_DELTA.search(value)
    delta = datetime.timedelta(days=0)

    # If a match is found, extract the number and unit from the match.
    if m:
        d = int(m.group(1))
        if m.group(3) == 'ago' or m.group(3) == 'before':
            d = -d

        # Convert the extracted number and unit into a timedelta object.
        if m.group(2) == 'minute':
            delta = datetime.timedelta(minutes=d)
        elif m.group(2) == 'hour':
            delta = datetime.timedelta(hours=d)
        elif m.group(2) == 'day':
            delta = datetime.timedelta(days=d)
        elif m.group(2) == 'week':
            delta = datetime.timedelta(weeks=d)

    # Remove the matched delta pattern from the input value.
    value = self.REGEX_DELTA.sub('', value)

    # Return the timedelta object and the modified input value.
    return (delta, value)

