def _emit_no_member(node, owner, owner_name, ignored_mixins=True, ignored_none=True):
    # Check if the node ignores exceptions
    if node_ignores_exception(node, AttributeError):
        return False

    # Check if the owner is None and if ignoring None is enabled
    if ignored_none and isinstance(owner, astroid.Const) and owner.value is None:
        return False

    # Check if the owner is a super class or a metaclass
    if is_super(owner) or getattr(owner, "type", None) == "metaclass":
        return False

    # Check if the owner is a mixin and if ignoring mixins is enabled
    if ignored_mixins and owner_name[-5:].lower() == "mixin":
        return False

    # Check if the owner is a function with decorators
    if isinstance(owner, astroid.FunctionDef) and owner.decorators:
        return False

    # Check if the owner is an instance or class with dynamic getattr
    if isinstance(owner, (astroid.Instance, astroid.ClassDef)):
        if owner.has_dynamic_getattr():
            try:
                metaclass = owner.metaclass()
            except exceptions.MroError:
                return False
            if metaclass:
                return metaclass.qname() == "enum.EnumMeta"
            if not has_known_bases(owner):
                return False

    # Check if the owner is a Super object with invalid MRO
    if isinstance(owner, objects.Super):
        try:
            owner.super_mro()
        except (exceptions.MroError, exceptions.SuperError):
            return False
        if not all(map(has_known_bases, owner.type.mro())):
            return False

    # Check if the owner is a module and has __getattr__
    if isinstance(owner, astroid.Module):
        try:
            owner.getattr("__getattr__")
            return False
        except astroid.NotFoundError:
            pass

    # Check if the attribute is mangled
    if node.attrname.startswith("_" + owner_name):
        unmangled_name = node.attrname.split("_" + owner_name)[-1]
        try:
            if owner.getattr(unmangled_name, context=None) is not None:
                return False
        except astroid.NotFoundError:
            return True

    return True

