def visit_attribute(self, node):
    # Check if the attribute is marked as generated based on patterns
    for pattern in self.config.generated_members:
        if re.match(pattern, node.attrname) or re.match(pattern, node.as_string()):
            return

    # Attempt to infer the attribute's value
    try:
        inferred = list(node.expr.infer())
    except exceptions.InferenceError:
        return

    # Identify missing attributes
    missingattr = set()
    non_opaque_inference_results = [owner for owner in inferred if owner is not astroid.Uninferable and not isinstance(owner, astroid.nodes.Unknown)]

    # Handle ambiguity in inference
    if len(non_opaque_inference_results) != len(inferred) and self.config.ignore_on_opaque_inference:
        return

    # Check each inferred owner for the attribute
    for owner in non_opaque_inference_results:
        name = getattr(owner, "name", None)
        if _is_owner_ignored(owner, name, self.config.ignored_classes, self.config.ignored_modules):
            continue

        try:
            if not [n for n in owner.getattr(node.attrname) if not isinstance(n.statement(), astroid.AugAssign)]:
                missingattr.add((owner, name))
                continue
        except AttributeError:
            continue
        except exceptions.NotFoundError:
            if not _emit_no_member(node, owner, name, ignored_mixins=self.config.ignore_mixin_members, ignored_none=self.config.ignore_none):
                continue
            missingattr.add((owner, name))
            continue

    # Display messages for missing attributes
    done = set()
    for owner, name in missingattr:
        actual = owner._proxied if isinstance(owner, astroid.Instance) else owner
        if actual in done:
            continue
        done.add(actual)
        msg, hint = self._get_nomember_msgid_hint(node, owner)
        self.add_message(msg, node=node, args=(owner.display_type(), name, node.attrname, hint), confidence=INFERENCE)

