def visit_assignname(self, node):
    # Avoid double parsing by checking if the node has already been handled
    if hasattr(node, "_handled"):
        return node._handled = True

    # Determine the frame where the name is defined
    if node.name in node.frame():
        frame = node.frame()
    else:
        frame = node.root()

    # Visit the frame if it hasn't been visited yet
    if not hasattr(frame, "locals_type"):
        if isinstance(frame, astroid.ClassDef):
            self.visit_classdef(frame)
        elif isinstance(frame, astroid.FunctionDef):
            self.visit_functiondef(frame)
        else:
            self.visit_module(frame)

    # Update the local type of the node's name
    current = frame.locals_type[node.name]
    values = set(node.infer())
    frame.locals_type[node.name] = list(set(current) | values)

    # Handle inference errors gracefully
    except astroid.InferenceError:
