def _detect_global_scope(node, frame, defframe):
    # Initialize scope variables
    scope = def_scope = None
    if frame and frame.parent:
        scope = frame.parent.scope()
    if defframe and defframe.parent:
        def_scope = defframe.parent.scope()

    # Check if the current node is within a function definition
    if isinstance(frame, astroid.FunctionDef):
        # If the node is not within the function definition or its arguments, return False
        if not isinstance(node.parent, (astroid.FunctionDef, astroid.Arguments)):
            return False
        # If either frame is not a class or module, return False
        if any(not isinstance(f, (astroid.ClassDef, astroid.Module)) for f in (frame, defframe)):
            return False

    # List to store different scopes
    break_scopes = []
    for s in (scope, def_scope):
        # Traverse parent scopes
        parent_scope = s
        while parent_scope:
            if not isinstance(parent_scope, (astroid.ClassDef, astroid.Module)):
                break_scopes.append(parent_scope)
                break
            if parent_scope.parent:
                parent_scope = parent_scope.parent.scope()
            else:
                break

    # Check if all stored scopes are the same
    if break_scopes and len(set(break_scopes)) != 1:
        return False

    # If scopes are the same, compare line numbers
    return frame.lineno < defframe.lineno

