def visit_functiondef(self, node):
    # Ignore actual functions if not a method
    if not node.is_method():
        return self._check_useless_super_delegation(node)

    klass = node.parent.frame()
    self._meth_could_be_func = True

    # Check if the first argument is 'self' if this is a method
    self._check_first_arg_for_type(node, klass.type == "metaclass")

    if node.name == "__init__":
        self._check_init(node)
        return

    # Check if the method overloads an inherited method
    for overridden in klass.local_attr_ancestors(node.name):
        try:
            meth_node = overridden[node.name]
        except KeyError:
            continue
        if not isinstance(meth_node, astroid.FunctionDef):
            continue
        self._check_signature(node, meth_node, "overridden", klass)
        break

    # Check decorators
    if node.decorators:
        for decorator in node.decorators.nodes:
            if isinstance(decorator, astroid.Attribute) and decorator.attrname in ("getter", "setter", "deleter"):
                return
            if isinstance(decorator, astroid.Name) and decorator.name == "property":
                return
            inferred = safe_infer(decorator)
            if not inferred:
                return
            if isinstance(inferred, astroid.FunctionDef):
                try:
                    inferred = next(inferred.infer_call_result(inferred))
                except astroid.InferenceError:
                    return
                try:
                    if (isinstance(inferred, (astroid.Instance, astroid.ClassDef)) and
                            inferred.getattr("__get__") and inferred.getattr("__set__")):
                        return
                except astroid.AttributeInferenceError:
                    pass

    # Check if the method is hidden by an attribute
    try:
        overridden = klass.instance_attr(node.name)[0]
        if isinstance(overridden_frame := overridden.frame(), astroid.FunctionDef) and overridden_frame.type == "method":
            overridden_frame = overridden_frame.parent.frame()
        if isinstance(overridden_frame, astroid.ClassDef) and klass.is_subtype_of(overridden_frame.qname()):
            args = (overridden.root().name, overridden.fromlineno)
            self.add_message("method-hidden", args=args, node=node)
    except astroid.NotFoundError:
