def _is_enum_class(node: astroid.ClassDef) -> bool:
    """
    Checks if the given class node is a subclass of the 'Enum' class from the 'enum' module.

    Args:
        node (astroid.ClassDef): The class node to check.

    Returns:
        bool: True if the class is a subclass of 'Enum', False otherwise.
    """
    for base in node.bases:
        try:
            inferred_bases = base.inferred()
        except astroid.InferenceError:
            continue
        for ancestor in inferred_bases:
            if not isinstance(ancestor, astroid.ClassDef):
                continue
            if ancestor.name == "Enum" and ancestor.root().name == "enum":
                return True
    return False

