    if token.exact_type != tokenize.COMMA:
        return False

    # Check if there are remaining tokens on the same line
    left_tokens = itertools.islice(tokens, index + 1, None)
    same_line_remaining_tokens = list(itertools.takewhile(
        lambda other_token: other_token.start[0] == token.start[0], left_tokens
    ))

    # Check if the last element is a newline or comment
    is_last_element = all(other_token.type in (tokenize.NEWLINE, tokenize.COMMENT) for other_token in same_line_remaining_tokens)

    if not same_line_remaining_tokens or not is_last_element:
        return False

    return True

