def _get_cycles(graph_dict, path, visited, result, vertice):
    # Check if the current vertex is already in the path, indicating a cycle
    if vertice in path:
        cycle = [vertice]
        for node in path[::-1]:
            if node == vertice:
                break
            cycle.insert(0, node)
        # Create a canonical representation of the cycle
        start_from = min(cycle)
        index = cycle.index(start_from)
        cycle = cycle[index:] + cycle[:index]
        # Add the cycle to the result if it's not already present
        if cycle not in result:
            result.append(cycle)
    # Append the current vertex to the path
    path.append(vertice)
    try:
        # Recursively explore each neighbor of the current vertex
        for node in graph_dict[vertice]:
            if node not in visited:
                _get_cycles(graph_dict, path, visited, result, node)
            visited.add(node)
    except KeyError:
        pass
    # Backtrack by removing the current vertex from the path
    path.pop()

