def generate(self, outputfile=None, dotfile=None, mapfile=None):
    # Determine the dotfile name and path
    if not dotfile:
        if outputfile and outputfile.endswith(".dot"):
            dotfile = outputfile
        else:
            dotfile = f"{self.graphname}.dot"

    # Determine the target format and create temporary files if necessary
    if outputfile is not None:
        storedir, _, target = target_info_from_filename(outputfile)
        if target != "dot":
            pdot, dot_sourcepath = tempfile.mkstemp(".dot", self.graphname)
            os.close(pdot)
        else:
            dot_sourcepath = osp.join(storedir, dotfile)
    else:
        target = "png"
        pdot, dot_sourcepath = tempfile.mkstemp(".dot", self.graphname)
        ppng, outputfile = tempfile.mkstemp(".png", self.graphname)
        os.close(pdot)
        os.close(ppng)

    # Write the graph source to the dot file
    pdot = codecs.open(dot_sourcepath, "w", encoding="utf8")
    pdot.write(self.source)
    pdot.close()

    # Render the graph using the specified renderer
    use_shell = sys.platform == "win32"
    if mapfile:
        subprocess.call([self.renderer, "-Tcmapx", "-o", mapfile, "-T", target, dot_sourcepath, "-o", outputfile], shell=use_shell)
    else:
        subprocess.call([self.renderer, "-T", target, dot_sourcepath, "-o", outputfile], shell=use_shell)

    # Clean up temporary files if created
    if target != "dot":
        os.unlink(dot_sourcepath)

    return outputfile

