def find_pylintrc():
    # Check for a pylint rc file in the current directory or its parent directories
    if os.path.exists("pylintrc"):
        return os.path.abspath("pylintrc")
    if os.path.exists(".pylintrc"):
        return os.path.abspath(".pylintrc")
    curdir = os.path.abspath(os.getcwd())
    while os.path.isfile(os.path.join(curdir, "__init__.py")):
        curdir = os.path.abspath(os.path.join(curdir, ".."))
    if os.path.isfile(os.path.join(curdir, "pylintrc")):
        return os.path.join(curdir, "pylintrc")
    if os.path.isfile(os.path.join(curdir, ".pylintrc")):
        return os.path.join(curdir, ".pylintrc")

    # Check for a pylint rc file in the environment variable
    if "PYLINTRC" in os.environ and os.path.exists(os.environ["PYLINTRC"]):
        return os.environ["PYLINTRC"]

    # Check for a pylint rc file in the user's home directory or its subdirectories
    user_home = os.path.expanduser("~")
    if user_home in ("~", "/root"):
        pylintrc = ".pylintrc"
    else:
        pylintrc = os.path.join(user_home, ".pylintrc")
    if not os.path.isfile(pylintrc):
        pylintrc = os.path.join(user_home, ".config", "pylintrc")
    if not os.path.isfile(pylintrc):
        # Check for a pylint rc file in the system-wide directory
        if os.path.isfile("/etc/pylintrc"):
            pylintrc = "/etc/pylintrc"
        else:
            pylintrc = None

    return pylintrc

