            # Append options to the corresponding section in the dictionary
            alloptions = options_by_section.setdefault(section, [])
            alloptions += options

    # Set the output stream, defaulting to sys.stdout if not provided
    stream = stream or sys.stdout
    printed = False

    # Print each section and its options
    for section in sections:
        if printed:
            print("\n", file=stream)
