def options_by_section(self):
    # Initialize a dictionary to store options by section
    sections = {}

    # Iterate over each option and its dictionary
    for optname, optdict in self.options:
        # Get the group from the option dictionary, default to an empty string if not present
        group = optdict.get("group", "")
        # Append the option to the corresponding section in the dictionary
        sections.setdefault(group, []).append((optname, optdict, self.option_value(optname)))

    # Yield None and the options in the 'None' group if it exists
