def request(self, url, data=None, headers=None, format='urlencoded', method='GET', content_type=None, token=None):
    # Initialize headers and token
    headers = dict(headers or {})
    if token is None:
        token = self.get_request_token()

    # Create client and expand URL
    client = self.make_client(token)
    url = self.expand_url(url)

    # Handle GET request
    if method == 'GET':
        assert format == 'urlencoded'
        if data:
            url = add_params_to_uri(url, data)
            data = None

    # Handle POST request
    else:
        if content_type is None:
            data, content_type = encode_request_data(data, format)
        if content_type is not None:
            headers['Content-Type'] = content_type

    # Sign or add token based on request type
    if self.request_token_url:
        headers, body = client.sign(url, http_method=method, body=data, headers=headers)
    else:
        headers, body = client.add_token(url, http_method=method, body=data, headers=headers)

    # Allow pre-request modifications
    if hasattr(self, 'pre_request'):
        url, headers, body = self.pre_request(url, headers, body)

    # Send HTTP request and return response
    if body:
        data = to_bytes(body, self.encoding)
    else:
        data = None
    resp, content = self.http_request(url, headers, data=data, method=method)
    return OAuthResponse(resp, content, self.content_type)

