def parse_genesets(self):
    # Retrieve the libraries
    enrichr_library = self.get_libraries()

    # Initialize the list to store gene sets
    gss_exist = []

    # Check the type of gene_sets and process accordingly
    if isinstance(self.gene_sets, list):
        gss = self.gene_sets
    elif isinstance(self.gene_sets, str):
        gss = [g.strip() for g in self.gene_sets.strip().split(",")]
    elif isinstance(self.gene_sets, dict):
        gss = [self.gene_sets]
    else:
        raise Exception("Error parsing enrichr libraries, please provide a corrected one")

    # Convert .gmt files to dictionaries and add to gss_exist
    for g in gss:
        if isinstance(g, dict):
            gss_exist.append(g)
        elif isinstance(g, str):
            if g in enrichr_library:
                gss_exist.append(g)
            elif g.lower().endswith(".gmt") and os.path.exists(g):
                self._logger.info("User Defined gene sets is given: %s" % g)
                with open(g) as genesets:
                    g_dict = {line.strip().split("\t")[0]: line.strip().split("\t")[2:] for line in genesets.readlines()}
                gss_exist.append(g_dict)

    return gss_exist

