def fit(self, Z):
    """Create vocabulary from input data Z.

    Parameters:
    Z (DictRDD or array-like): Input data.

    Returns:
    self: The fitted object with created vocabulary.
    """
    if isinstance(Z, DictRDD):
        X = Z[:, 'X']
    else:
        X = Z

    class SetAccum(AccumulatorParam):
        def zero(self, initialValue):
            return set(initialValue)

        def addInPlace(self, v1, v2):
            v1 |= v2
            return v1

    accum = X.context.accumulator(set(), SetAccum())

    def mapper(X, separator=self.separator):
        feature_names = []
        for x in X:
            for f, v in six.iteritems(x):
                if isinstance(v, six.string_types):
                    f = "%s%s%s" % (f, self.separator, v)
                feature_names.append(f)
        accum.add(set(feature_names))

    X.foreach(mapper)

    feature_names = list(accum.value)
    if self.sort:
        feature_names.sort()

    vocab = dict((f, i) for i, f in enumerate(feature_names))
    self.feature_names_ = feature_names
    self.vocabulary_ = vocab

    return self

