def find_ledger_file(ledgerrcpath=None):
    """
    Finds the path to the ledger file.

    Args:
        ledgerrcpath (str, optional): Path to the .ledgerrc file. If None, defaults to the user's home directory.

    Returns:
        str or None: The absolute path to the ledger file if found, otherwise None.
    """
    if ledgerrcpath is None:
        ledgerrcpath = os.path.abspath(os.path.expanduser("~/.ledgerrc"))

    if "LEDGER_FILE" in os.environ:
        return os.path.abspath(os.path.expanduser(os.environ["LEDGER_FILE"]))

    if os.path.exists(ledgerrcpath):
        with open(ledgerrcpath) as ledgerrc:
            for line in ledgerrc:
                md = re.match(r"--file\s+([^\s]+).*", line)
                if md is not None:
                    return os.path.abspath(os.path.expanduser(md.group(1)))
    return None

