def get_studies(self, features=None, expression=None, mask=None, peaks=None, frequency_threshold=0.001, activation_threshold=0.0, func=np.sum, return_type='ids', r=6):
    results = []

    # Feature-based selection
    if features is not None:
        if return_type == 'weights':
            if expression is not None or mask is not None or peaks is not None:
                raise ValueError("return_type cannot be 'weights' when feature-based search is used in conjunction with other search modes.")
            return self.feature_table.get_ids(features, frequency_threshold, func, get_weights=True)
        else:
            results.append(self.feature_table.get_ids(features, frequency_threshold, func))

    # Logical expression-based selection
    if expression is not None:
        _ids = self.feature_table.get_ids_by_expression(expression, frequency_threshold, func)
        results.append(list(_ids))

    # Mask-based selection
    if mask is not None:
        mask = self.masker.mask(mask, in_global_mask=True).astype(bool)
        num_vox = np.sum(mask)
        prop_mask_active = self.image_table.data.T.dot(mask).astype(float)
        if isinstance(activation_threshold, float):
            prop_mask_active /= num_vox
        indices = np.where(prop_mask_active > activation_threshold)[0]
        results.append([self.image_table.ids[ind] for ind in indices])

    # Peak-based selection
    if peaks is not None:
        r = float(r)
        found = set()
        for p in peaks:
            xyz = np.array(p, dtype=float)
            x = self.activations['x']
            y = self.activations['y']
            z = self.activations['z']
            dists = np.sqrt(np.square(x - xyz[0]) + np.square(y - xyz[1]) + np.square(z - xyz[2]))
            inds = np.where((dists > 5.5) & (dists < 6.5))[0]
            tmp = dists[inds]
            found |= set(self.activations[dists <= r]['id'].unique())
        results.append(found)

    # Get intersection of all sets
    ids = list(reduce(lambda x, y: set(x) & set(y), results))

    if return_type == 'ids':
        return ids
    elif return_type == 'data':
        return self.get_image_data(ids)

