async def get_bearer_info(self):
    # Check if client_id is None and raise an exception if true
    if self.client_id is None:
        raise SpotifyException(_GET_BEARER_ERR % 'client_id')
    # Check if client_secret is None and raise an exception if true
    elif self.client_secret is None:
        raise SpotifyException(_GET_BEARER_ERR % 'client_secret')

    # Encode the client_id and client_secret with base64
    token = b64encode(':'.join((self.client_id, self.client_secret)).encode()).decode()

    # Set the request parameters
    kwargs = {
        'url': 'https://accounts.spotify.com/api/token',
        'data': {
            'grant_type': 'client_credentials'
        },
        'headers': {
            'Authorization': 'Basic ' + token
        }
    }

    # Send a POST request to the Spotify token endpoint
    async with self._session.post(**kwargs) as resp:
        # Return the JSON response
        return json.loads(await resp.text(encoding='utf-8'))

