def check_versions(cls, local, upstream):
    # Initialize status list to track version comparison
    status = [None, None, None]

    # Loop through each version part
    for index, version_number in enumerate(local):
        if int(version_number) < int(upstream[index]):
            # Local version is older
            status[index] = True
        elif int(version_number) > int(upstream[index]):
            # Local version is newer
            status[index] = False

    # Check if there is any part that is older
    if False in status:
        return False
    # Check if there is any part that is newer
    elif True in status:
        return True
    # If all parts are the same
    else:
        return None

