def mine(self):
    # Check if mining is activated
    if PyFunceble.CONFIGURATION["mining"]:
        try:
            # Get the history of the request
            history = PyFunceble.requests.get(self.to_get, timeout=PyFunceble.CONFIGURATION["seconds_before_http_timeout"], headers=self.headers).history
            # Initialize a dictionary to store mined links
            mined = {self.to_get_bare: []}

            for element in history:
                # Update the element to the URL
                element = element.url

                # Check the type of test being performed
                if PyFunceble.INTERN["to_test_type"] == "url":
                    # Test a full URL
                    to_append = Check().is_url_valid(element, return_base=False)
                elif PyFunceble.INTERN["to_test_type"] == "domain":
                    # Test a domain
                    to_append = Check().is_url_valid(element, return_base=True)
                else:
                    raise Exception("Unknown tested.")

                if to_append:
                    # Append the valid URL to the list of mined links
                    if to_append.endswith(":80"):
                        to_append = to_append[:-3]
                    if to_append != self.to_get_bare:
                        mined[self.to_get_bare].append(to_append)

            # Return the dictionary of mined links if not empty
            if mined[self.to_get_bare]:
                return mined
            else:
                return None
        except (PyFunceble.requests.ConnectionError, PyFunceble.requests.exceptions.Timeout, PyFunceble.requests.exceptions.InvalidURL, PyFunceble.socket.timeout, urllib3_exceptions.InvalidHeader, UnicodeDecodeError):
            # Return None if an exception occurs
            return None
    return None

