def _save(self, last=False):
    # Check if authorization, logging, and file_to_test are configured
    if self._authorization() and PyFunceble.CONFIGURATION["logs"] and "file_to_test" in PyFunceble.INTERN and PyFunceble.INTERN["file_to_test"]:
        # Set the file path for logging
        self.file = PyFunceble.OUTPUT_DIRECTORY + PyFunceble.OUTPUTS["parent_directory"] + PyFunceble.OUTPUTS["logs"]["directories"]["parent"] + PyFunceble.OUTPUTS["logs"]["filenames"]["execution_time"]

        # Read existing content if the file exists, otherwise create a dummy content
        if PyFunceble.path.isfile(self.file):
            content = Dict().from_json(File(self.file).read())
        else:
            content = {}

        # Handle "start" action
        if self.action == "start":
            if "final_total" in content and content["final_total"]:
                del content["final_total"]
            if "data" in content:
                content["data"].append([PyFunceble.INTERN["start"]])
            else:
                content["data"] = [[PyFunceble.INTERN["start"]]]

        # Handle "stop" action
        elif self.action == "stop":
            try:
                content["data"][-1].append(PyFunceble.INTERN["end"])
                start = content["data"][0][0]
                end = content["data"][-1][-1]
                content["current_total"] = self.format_execution_time(start, end)
                if last:
                    content["final_total"] = content["current_total"]
                    print(PyFunceble.Fore.MAGENTA + PyFunceble.Style.BRIGHT + "Global execution time: " + content["final_total"])
            except KeyError:
                pass

        # Save the content to the file
        try:
            Dict(content).to_json(self.file)
        except FileNotFoundError:
            DirectoryStructure()
            Dict(content).to_json(self.file)

