def merge(self, to_merge, strict=True):
    # Initialize the result dictionary
    result = {}

    # Loop through each element in the to_merge dictionary
    for element in to_merge:
        if element in self.main_dictionnary:
            # If the element is in both dictionaries
            if isinstance(to_merge[element], dict) and isinstance(self.main_dictionnary[element], dict):
                # Merge the dictionaries recursively
                result[element] = Dict(self.main_dictionnary[element]).merge(to_merge[element])
            elif isinstance(to_merge[element], list) and isinstance(self.main_dictionnary[element], list):
                # Merge the lists
                result[element] = List(self.main_dictionnary[element]).merge(to_merge[element], strict)
            else:
                # If not a list or dict, update the result
                result.update({element: to_merge[element]})
        else:
            # If the element is not in the main dictionary, add it to the result
            result.update({element: to_merge[element]})

    # Loop through each element in the main dictionary
    for element in self.main_dictionnary:
        if element not in result:
            # If the element is not in the result, add it to the result
            result[element] = self.main_dictionnary[element]

    # Return the merged result
    return result

