def match(self):
    # Initialize the result list
    result = []

    # Compile the regex pattern
    to_match = re.compile(self.regex)

    # Determine whether to use re.findall or re.search
    if self.rematch:
        pre_result = to_match.findall(self.data)
    else:
        pre_result = to_match.search(self.data)

    # Process the result based on return_data and pre_result
    if self.return_data and pre_result:
        if self.rematch:
            for data in pre_result:
                if isinstance(data, tuple):
                    result.extend(list(data))
                else:
                    result.append(data)
        if self.group != 0:
            return result[self.group]
        else:
            return result

    # Return True if no data is returned and pre_result is found
    if not self.return_data and pre_result:
        return True

    return False

