def _reformat_historical_formating_error(self):
    # Check if the inactive database file exists
    historical_formating_error = PyFunceble.CURRENT_DIRECTORY + "inactive-db.json"
    if PyFunceble.path.isfile(historical_formating_error):
        # Read the content of the historical file
        data = Dict().from_json(File(historical_formating_error).read())
        data_to_parse = {}

        # Iterate through the top-level keys
        for top_key in data.keys():
            data_to_parse[top_key] = {}
            # Iterate through the low-level keys
            for low_key in data[top_key].keys():
                if low_key.isdigit():
                    # Adjust the date by subtracting 30 days if the key is a digit
                    new_key = int(low_key) - (self.one_day_in_seconds * 30)
                else:
                    # Adjust the date by subtracting 30 days from the current time if the key is not a digit
                    new_key = int(PyFunceble.time()) - (self.one_day_in_seconds * 30)
                data_to_parse[top_key][new_key] = data[top_key][low_key]

        # Update the current database with the parsed data
        if "inactive_db" in PyFunceble.INTERN:
            PyFunceble.INTERN["inactive_db"].update(data_to_parse)
        else:
            PyFunceble.INTERN["inactive_db"] = data_to_parse

        # Delete the historical database file
        File(historical_formating_error).delete()

