def whois(cls, whois_server, domain=None, timeout=None):
    # Set default values for domain and timeout if not provided
    if domain is None:
        domain = PyFunceble.INTERN["to_test"]
    if timeout is None:
        timeout = PyFunceble.CONFIGURATION["seconds_before_http_timeout"]

    # If a whois server is provided, initiate a socket connection
    if whois_server:
        req = PyFunceble.socket.socket(PyFunceble.socket.AF_INET, PyFunceble.socket.SOCK_STREAM)
        if timeout % 3 == 0:
            req.settimeout(timeout)
        else:
            req.settimeout(3)

        try:
            # Connect to the whois server on port 43
            req.connect((whois_server, 43))
            # Send the domain encoded in bytes
            req.send((domain + "\r\n").encode())
            response = b""
            while True:
                try:
                    # Receive data in chunks of 4096 bytes
                    data = req.recv(4096)
                except (PyFunceble.socket.timeout, ConnectionResetError):
                    # Handle timeout or connection reset errors
                    req.close()
                    return None
                if not data:
                    # Break loop if no more data is received
                    break
                response += data
            req.close()
            try:
                # Decode and return the response
                return response.decode()
            except UnicodeDecodeError:
                # Handle decoding errors by replacing non-UTF-8 characters
                return response.decode("utf-8", "replace")
        except PyFunceble.socket.error:
            # Handle socket errors by returning None
            return None
    # Return None if no whois server is provided
    return None

