def dict_entry_has_key(line, key):
    # Check if the line contains a comment
    if '#' in line:
        return False

    # Use regular expression to match the key-value pair in the line
    result = re.match(r'\s*(.*)\s*:\s*(.*),\s*$', line)
    if not result:
        return False

    try:
        # Evaluate the key part of the match to get the candidate key
        candidate_key = ast.literal_eval(result.group(1))
    except (SyntaxError, ValueError):
        return False

    # Check if the value part of the match is a multiline statement
    if multiline_statement(result.group(2)):
        return False

    # Return True if the candidate key matches the given key, False otherwise
    return candidate_key == key

