def is_allowed(self, policy_name, session_user, session_group, object_owner, object_type, operation):
    # Retrieve the relevant policy section based on the policy name and session group
    policy_section = self.get_relevant_policy_section(policy_name, session_group)
    if policy_section is None:
        return False

    # Get the policy for the specified object type
    object_policy = policy_section.get(object_type)
    if not object_policy:
        self._logger.warning(f"The '{policy_name}' policy does not apply to {self._get_enum_string(object_type)} objects.")
        return False

    # Get the policy for the specified operation on the object type
    operation_object_policy = object_policy.get(operation)
    if not operation_object_policy:
        self._logger.warning(f"The '{policy_name}' policy does not apply to {self._get_enum_string(operation)} operations on {self._get_enum_string(object_type)} objects.")
        return False

    # Evaluate the policy and return the result
    if operation_object_policy == enums.Policy.ALLOW_ALL:
        return True
    elif operation_object_policy == enums.Policy.ALLOW_OWNER:
        return session_user == object_owner
    elif operation_object_policy == enums.Policy.DISALLOW_ALL:
        return False
    else:
        return False

