def is_attribute_deprecated(self, attribute):
    # Retrieve the rule set for the given attribute
    rule_set = self._attribute_rule_sets.get(attribute)

    # Check if the rule set indicates the attribute is deprecated
    if rule_set.version_deprecated:
        # Compare the current version with the deprecated version
        if self._version >= rule_set.version_deprecated:
            return True
        else:
            return False
    else:
        return False

