def authenticate(self, connection_certificate=None, connection_info=None, request_credentials=None):
    if self.users_url is None or self.groups_url is None:
        raise exceptions.ConfigurationError("The SLUGS URL must be specified.")

    user_id = utils.get_client_identity_from_certificate(connection_certificate)
    try:
        response = requests.get(self.users_url.format(user_id))
    except Exception:
        raise exceptions.ConfigurationError("A connection could not be established using the SLUGS URL.")

    if response.status_code == 404:
        raise exceptions.PermissionDenied("Unrecognized user ID: {}".format(user_id))

    response = requests.get(self.groups_url.format(user_id))
    if response.status_code == 404:
        raise exceptions.PermissionDenied("Group information could not be retrieved for user ID: {}".format(user_id))

    return user_id, response.json().get('groups')


