def read(self, input_buffer, kmip_version=enums.KMIPVersion.KMIP_1_0):
    super(GetAttributesResponsePayload, self).read(input_buffer, kmip_version=kmip_version)
    local_buffer = utils.BytearrayStream(input_buffer.read(self.length))

    if self.is_tag_next(enums.Tags.UNIQUE_IDENTIFIER, local_buffer):
        unique_identifier = primitives.TextString(tag=enums.Tags.UNIQUE_IDENTIFIER)
        unique_identifier.read(local_buffer, kmip_version=kmip_version)
        self.unique_identifier = unique_identifier.value
    else:
        raise exceptions.InvalidKmipEncoding("The GetAttributes response payload encoding is missing the unique identifier.")

    if kmip_version < enums.KMIPVersion.KMIP_2_0:
        self._attributes = list()
        while self.is_tag_next(enums.Tags.ATTRIBUTE, local_buffer):
            attribute = objects.Attribute()
            attribute.read(local_buffer, kmip_version=kmip_version)
            self._attributes.append(attribute)
    else:
        if self.is_tag_next(enums.Tags.ATTRIBUTES, local_buffer):
            attributes = objects.Attributes()
            attributes.read(local_buffer, kmip_version=kmip_version)
            temp_attr = objects.convert_attributes_to_template_attribute(attributes)
            self._attributes = temp_attr.attributes
        else:
            raise exceptions.InvalidKmipEncoding("The GetAttributes response payload encoding is missing the attributes structure.")

    self.is_oversized(local_buffer)

