def create_protobuf_span(span):
    # Initialize a dictionary to hold keyword arguments for the Span constructor
    pb_kwargs = {}

    # Convert trace_id, parent_id, and span_id to bytes and add to pb_kwargs
    pb_kwargs['trace_id'] = _hex_to_bytes(span.trace_id)
    if span.parent_id:
        pb_kwargs['parent_id'] = _hex_to_bytes(span.parent_id)
    pb_kwargs['id'] = _hex_to_bytes(span.span_id)

    # Convert span kind to protobuf kind and add to pb_kwargs if it exists
    pb_kind = _get_protobuf_kind(span.kind)
    if pb_kind:
        pb_kwargs['kind'] = pb_kind

    # Add span name to pb_kwargs if it exists
    if span.name:
        pb_kwargs['name'] = span.name

    # Convert timestamp and duration to microseconds and add to pb_kwargs if they exist
    if span.timestamp:
        pb_kwargs['timestamp'] = int(span.timestamp * 1000 * 1000)
    if span.duration:
        pb_kwargs['duration'] = int(span.duration * 1000 * 1000)

    # Convert local_endpoint and remote_endpoint to protobuf format and add to pb_kwargs if they exist
    if span.local_endpoint:
        pb_kwargs['local_endpoint'] = _convert_endpoint(span.local_endpoint)
    if span.remote_endpoint:
        pb_kwargs['remote_endpoint'] = _convert_endpoint(span.remote_endpoint)

    # Convert annotations to protobuf format and add to pb_kwargs if they exist
    if len(span.annotations) > 0:
        pb_kwargs['annotations'] = _convert_annotations(span.annotations)

    # Add tags to pb_kwargs if they exist
    if len(span.tags) > 0:
        pb_kwargs['tags'] = span.tags

    # Add debug and shared flags to pb_kwargs if they exist
    if span.debug:
        pb_kwargs['debug'] = span.debug
    if span.shared:
        pb_kwargs['shared'] = span.shared

    # Create and return a zipkin_pb2.Span instance using the collected keyword arguments
    return zipkin_pb2.Span(**pb_kwargs)

