def _interpret_response(self, response, payload, expected_status):
    # Extracts and decodes the raw content from the response
    raw_content = response.text
    if not raw_content:
        raise BadApiResponse('Empty {status} response from node.'.format(status=response.status_code), context={'request': payload})

    try:
        decoded = json.loads(raw_content)
    except ValueError:
        raise BadApiResponse('Non-JSON {status} response from node: {raw_content}'.format(status=response.status_code, raw_content=raw_content), context={'request': payload, 'raw_response': raw_content})

    if not isinstance(decoded, dict):
        raise BadApiResponse('Malformed {status} response from node: {decoded!r}'.format(status=response.status_code, decoded=decoded), context={'request': payload, 'response': decoded})

    # Checks if the response status code is in the expected status list
    if response.status_code in expected_status:
        return decoded

    error = None
    try:
        if response.status_code == codes['bad_request']:
            error = decoded['error']
        elif response.status_code == codes['internal_server_error']:
            error = decoded['exception']
    except KeyError:
        pass

    raise BadApiResponse('{status} response from node: {error}'.format(error=error or decoded, status=response.status_code), context={'request': payload, 'response': decoded})

