def encode(self, input, errors='strict'):
    if isinstance(input, memoryview):
        input = input.tobytes()
    if not isinstance(input, (binary_type, bytearray)):
        raise TypeError("Can't encode {type}; byte string expected.".format(type=type(input).__name__))
    if not isinstance(input, bytearray):
        input = bytearray(input)
    trytes = bytearray()
    for c in input:
        second, first = divmod(c, len(self.alphabet))
        trytes.append(self.alphabet[first])
        trytes.append(self.alphabet[second])
    return binary_type(trytes), len(input)

python
def decode(self, input, errors='strict'):
    if isinstance(input, memoryview):
        input = input.tobytes()
    if not isinstance(input, (binary_type, bytearray)):
        raise TypeError("Can't decode {type}; byte string expected.".format(type=type(input).__name__))

    if not isinstance(input, bytearray):
        input = bytearray(input)

    bytes_ = bytearray()
    for i in range(0, len(input), 2):
        try:
            first, second = input[i:i + 2]
        except ValueError:
            if errors == 'strict':
                raise TrytesDecodeError("'{name}' codec can't decode value; tryte sequence has odd length.".format(name=self.name), context={'input': input})
            elif errors == 'replace':
                bytes_ += b'?'
                continue

        try:
            bytes_.append(self.index[first] + (self.index[second] * len(self.index)))
        except ValueError:
            if errors == 'strict':
                raise TrytesDecodeError("'{name}' codec can't decode trytes {pair} at position {i}-{j}: ordinal not in range(255)".format(name=self.name, pair=chr(first) + chr(second), i=i, j=i + 1), context={'input': input})
            elif errors == 'replace':
                bytes_ += b'?'

    return binary_type(bytes_), len(input)

