def discover_commands(package, recursively=True):
    """
    Recursively discovers and registers command classes within a given package.

    Args:
        package (Union[ModuleType, Text]): The package to search for command classes. Can be a module or a package name as a string.
        recursively (bool, optional): Whether to search recursively through sub-packages. Defaults to True.

    Returns:
        Dict[Text, 'CommandMeta']: A dictionary mapping command names to their corresponding command classes.
    """
    if isinstance(package, string_types):
        package = import_module(package)

    commands = {}
    for _, name, is_package in walk_packages(package.__path__, package.__name__ + '.'):
        sub_package = import_module(name)
        for _, obj in get_members(sub_package):
            if is_class(obj) and isinstance(obj, CommandMeta):
                command_name = getattr(obj, 'command')
                if command_name:
                    commands[command_name] = obj
                if recursively and is_package:
                    commands.update(discover_commands(sub_package))
    return commands

