def _create_validator(self):
    # Group transactions by address for easier iteration.
    grouped_transactions = self.bundle.group_transactions()

    # Define expected values.
    bundle_hash = self.bundle.hash
    last_index = len(self.bundle) - 1

    # Track balance and index.
    balance = 0
    counter = 0

    # Check indices and balance.
    for group in grouped_transactions:
        for txn in group:
            balance += txn.value
            if txn.bundle_hash != bundle_hash:
                yield 'Transaction {i} has invalid bundle hash.'.format(i=counter)
            if txn.current_index != counter:
                yield ('Transaction {i} has invalid current index value ' '(expected {i}, actual {actual}).'.format(actual=txn.current_index, i=counter))
            if txn.last_index != last_index:
                yield ('Transaction {i} has invalid last index value ' '(expected {expected}, actual {actual}).'.format(actual=txn.last_index, expected=last_index, i=counter))
            counter += 1

    # Check bundle balance.
    if balance != 0:
        yield ('Bundle has invalid balance ' '(expected 0, actual {actual}).'.format(actual=balance))

    # Signature validation if no errors.
    if not self._errors:
        signature_validation_queue = []
        for group in grouped_transactions:
            if group[0].value >= 0:
                continue
            validate_group_signature = True
            for j, txn in enumerate(group):
                if (j > 0) and (txn.value != 0):
                    yield ('Transaction {i} has invalid value ' '(expected 0, actual {actual}).'.format(actual=txn.value, i=txn.current_index))
                    validate_group_signature = False
                    continue
            if validate_group_signature:
                signature_validation_queue.append(group)

        # Validate signatures.
        if signature_validation_queue:
            for error in self._get_bundle_signature_errors(signature_validation_queue):
                yield error

