def _traverse_bundle(self, txn_hash, target_bundle_hash=None):
    """
    Traverses a bundle of transactions starting from a given transaction hash.

    Args:
        txn_hash (TransactionHash): The hash of the transaction to start from.
        target_bundle_hash (Optional[BundleHash]): The hash of the target bundle. If provided, the traversal will stop when this bundle is reached.

    Returns:
        List[Transaction]: A list of transactions in the bundle.

    Raises:
        BadApiResponse: If the bundle transactions are not visible or if the traversal starts with a non-tail transaction.
    """
    trytes = GetTrytesCommand(self.adapter)(hashes=[txn_hash])['trytes']
    if not trytes:
        raise with_context(exc=BadApiResponse('Bundle transactions not visible (`exc.context` has more info).'), context={'transaction_hash': txn_hash, 'target_bundle_hash': target_bundle_hash})

    transaction = Transaction.from_tryte_string(trytes[0])

    if not target_bundle_hash and transaction.current_index:
        raise with_context(exc=BadApiResponse('`_traverse_bundle` started with a non-tail transaction (`exc.context` has more info).'), context={'transaction_object': transaction, 'target_bundle_hash': target_bundle_hash})

    if target_bundle_hash:
        if target_bundle_hash != transaction.bundle_hash:
            return []
        else:
            target_bundle_hash = transaction.bundle_hash

    if transaction.current_index == transaction.last_index == 0:
        return [transaction]

    return [transaction] + self._traverse_bundle(txn_hash=transaction.trunk_transaction_hash, target_bundle_hash=target_bundle_hash)

