def sign_input_transactions(self, bundle, start_index):
    # Check if the bundle has a hash
    if not bundle.hash:
        raise ValueError('Cannot sign inputs without a bundle hash!') from None

    # Create a SignatureFragmentGenerator for the bundle hash
    signature_fragment_generator = SignatureFragmentGenerator(self, bundle.hash)

    # Iterate over the transactions in the bundle starting from start_index
    for j in range(self.security_level):
        try:
            txn = bundle[start_index + j]
        except IndexError as e:
            raise IndexError(f'Index out of range for transaction {start_index + j}') from e

        # Only sign input transactions (transactions with value 0)
        if txn.value > 0:
            raise ValueError(f'Attempting to sign non-input transaction #{start_index + j} (value={txn.value}).')

        # Check if the transaction is already signed
        if txn.signature_message_fragment:
            raise ValueError(f'Attempting to sign input transaction #{start_index + j}, but it has a non-empty fragment.')

        # Sign the transaction
        txn.signature_message_fragment = next(signature_fragment_generator)

