def finish_read(self, timeout=2, stdin_content="", stdin=False):
    # Create a new thread to get the output
    process = Thread(target=self.get_output, args=(stdin_content, stdin))
    process.start()

    # Wait for the process to complete with a timeout
    if timeout > 0:
        process.join(timeout)
    else:
        process.join()

    # Check if the process is still alive after the timeout
    if process.is_alive():
        self.close()
        self.return_code = -signal.SIGHUP
    else:
        self.return_code = self.process.returncode

