def syncStateCall(self, method, url, params={}, **kwargs):
    try:
        states = self.syncStates[(method, url)]
    except KeyError:
        states = self.syncStates[(method, url)] = []

    if states:
        # Use the last state link to replace the URL and query string.
        url = states[-1]
        params = {}

    resp = self(method, url, params=params, **kwargs)

    try:
        json = resp.json()
    except ValueError:
        # Do nothing if not a JSON response.
        pass
    else:
        # If a state link exists in the response, store it for later.
        state = json.get("_metadata", {}).get("syncState")
        if state:
            states.append(state)

    return resp

