def _check_index(self, key: Union[slice, int]) -> (int, int):
    ss, se = self._span
    if isinstance(key, int):
        if key < 0:
            key += se - ss
        if key < 0 or key >= se - ss:
            raise IndexError('index out of range')
        start = ss + key
        return start, start + 1
    elif isinstance(key, slice):
        if key.step is not None:
            raise NotImplementedError('step is not implemented for string setter.')
        start, stop = key.start or 0, key.stop
        if start < 0:
            start += se - ss
        if start < 0:
            raise IndexError('start index out of range')
        if stop is None:
            stop = se - ss
        elif stop < 0:
            stop += se - ss
        if start > stop:
            raise IndexError('stop index out of range or start is after the stop')
        return start + ss, stop + ss

