def normal_name(self, rm_namespaces=('Template',), capital_links=False, _code=None, *, code=None, capitalize=False) -> str:
    if capital_links:
        warn("`capital_links` argument is deprecated, use `capitalize` instead", DeprecationWarning)
        capitalize = capital_links
    if _code:
        warn("`positional_code` argument is deprecated, use `code` instead", DeprecationWarning)
        code = _code

    # Remove comments
    name = COMMENT_SUB('', self.name).strip(WS)

    # Remove code if provided
    if code:
        head, sep, tail = name.partition(':')
        if not head and sep:
            name = tail.strip(' ')
        head, sep, tail = name.partition(':')
        if code.lower() == head.strip(' ').lower():
            name = tail.strip(' ')

    # Remove namespace
    head, sep, tail = name.partition(':')
    if not head and sep:
        name = tail.strip(' ')
    head, sep, tail = name.partition(':')
    if head:
        ns = head.strip(' ').lower()
        for namespace in rm_namespaces:
            if namespace.lower() == ns:
                name = tail.strip(' ')
                break

    # Replace underscores with spaces
    name = name.replace('_', ' ')

    # Capitalize the first letter if required
    if capitalize:
        n0 = name[0]
        if n0.islower():
            name = n0.upper() + name[1:]

    # Remove #anchor
    name, sep, tail = name.partition('#')

    return ' '.join(name.split())

