def rm_dup_args_safe(self, tag: str = None) -> None:
    name_to_lastarg_vals = {}  # Dictionary to store the last argument values for each name
    for arg in reversed(self.arguments):
        name = arg.name.strip(WS)
        if arg.positional:
            val = arg.value
