            else:
                lastarg, dup_vals = name_to_lastarg_vals[name]
                if val in dup_vals:
                    del arg[0:len(arg.string)]
                elif '' in dup_vals:
                    del lastarg[0:len(lastarg.string)]
                    dup_vals.pop(0)
                else:
                    dup_vals.append(val)
        if tag:
            arg.value += tag
        else:
            name_to_lastarg_vals[name] = (arg, [val])

