def from_b64(path, bcontent, format):
    # Define a dictionary of decoders for different formats
    decoders = {
        'base64': lambda path, bcontent: (bcontent.decode('ascii'), 'base64'),
        'text': _decode_text_from_base64,
        None: _decode_unknown_from_base64,
    }

    try:
        # Attempt to decode the content using the specified format
        content, real_format = decoders[format](path, bcontent)
    except HTTPError:
        # Pass through HTTP errors to be handled by the API layer
        raise
    except Exception as e:
        # Wrap other exceptions in CorruptedFile for misconfiguration
        raise CorruptedFile(e)

    # Determine the MIME type based on the path or default
    default_mimes = {
        'text': 'text/plain',
        'base64': 'application/octet-stream',
    }
    mimetype = mimetypes.guess_type(path)[0] or default_mimes[real_format]

    # Return the decoded content, real format, and MIME type
    return content, real_format, mimetype

