def ensure_python(specs):
    # Ensure specs is a list
    if not isinstance(specs, (list, tuple)):
        specs = [specs]

    # Get the current Python version
    v = sys.version_info
    part = '%s.%s' % (v.major, v.minor)

    # Check if the current Python version matches any spec
    for spec in specs:
        if part == spec:
            return

    # Evaluate the version spec
    try:
        if eval(part + spec):
            return
    except SyntaxError:
        pass

    # Raise an error if the version is unsupported
    raise ValueError('Python version %s unsupported' % part)

