def _translate_glob_part(pat):
    # Translates a glob pattern into a regular expression pattern.
    if pat == '**':
        return '.*'
    i, n = 0, len(pat)
    res = []
    while i < n:
        c = pat[i]
        i += 1
        if c == '*':
            # Match anything but path separators.
            res.append('[^%s]*' % SEPARATORS)
        elif c == '?':
            # Match any single character but a path separator.
            res.append('[^%s]?' % SEPARATORS)
        elif c == '[':
            # Handle character sets.
            j = i
            if j < n and pat[j] == '!':
                j += 1
            if j < n and pat[j] == ']':
                j += 1
            while j < n and pat[j] != ']':
                j += 1
            if j >= n:
                res.append('\\[')
            else:
                stuff = pat[i:j].replace('\\', '\\\\')
                i = j + 1
                if stuff[0] == '!':
                    stuff = '^' + stuff[1:]
                elif stuff[0] == '^':
                    stuff = '\\' + stuff
                res.append('[%s]' % stuff)
        else:
            # Escape other characters.
            res.append(re.escape(c))
    return ''.join(res)

