def _info_handler(self, data):
    """Handles information messages based on the 'code' in the data dictionary.

    If 'code' is not in the data but 'version' is, logs the API version and returns the corresponding message.
    If 'code' is in the data, logs the message associated with the code and calls the corresponding method from the 'codes' dictionary.
    If the code is not recognized, logs an error and raises a ValueError.
    """
    info_message = {
        20000: 'Invalid User given! Please make sure the given ID is correct!',
        20051: 'Stop/Restart websocket server (please try to reconnect)',
        20060: 'Refreshing data from the trading engine; please pause any activity.',
        20061: 'Done refreshing data from the trading engine. Re-subscription advised.'
    }
    codes = {
        20051: self.reconnect,
        20060: self._pause,
        20061: self._unpause
    }

    if 'version' in data:
        self.log.info("API version: %i", data['version'])
        return

    if 'code' not in data:
        raise ValueError("No 'code' in data")

    try:
        self.log.info(info_message[data['code']])
        codes[data['code']]()
    except KeyError as e:
        self.log.exception(e)
        self.log.error("Unknown Info code %s!", data['code'])
        raise ValueError("Unknown Info code")

