def validate_versatileimagefield_sizekey_list(sizes):
    """
    Validates a list of size keys for a VersatileImageField.

    Args:
        sizes (iterable): An iterable of 2-tuples representing size keys.

    Raises:
        InvalidSizeKey: If any size key is invalid.
        InvalidSizeKeySet: If the input is not an iterable of 2-tuples.

    Returns:
        list: A list of unique size keys.
    """
    try:
        for key, size_key in sizes:
            size_key_split = size_key.split('__')
            if size_key_split[-1] != 'url' and ('x' not in size_key_split[-1]):
                raise InvalidSizeKey(f"{size_key} is an invalid size. All sizes must be either 'url' or made up of at least two segments separated by double underscores. Examples: 'crop__400x400', 'filters__invert__url'")
    except ValueError:
        raise InvalidSizeKeySet(f"{str(sizes)} is an invalid size key set. Size key sets must be an iterable of 2-tuples")
    return list(set(sizes))

