def format_instruction(insn):
    text = insn.op.mnemonic
    if not insn.imm:
        return text
    else:
        return text + ' ' + ', '.join(
            getattr(insn.op.imm_struct, x.name).to_string(getattr(insn.imm, x.name))
            for x in insn.op.imm_struct._meta.fields
        )

