def load(self, query=None, search_in_source_files=False):
    if self._loaded:
        logging.debug('Loading Vdir %s with query %s', self.name, query)

    errors = 0
    for filename in self._find_vcard_files(search=query, search_in_source_files=search_in_source_files):
        try:
            card = CarddavObject.from_file(self, filename, self._private_objects, self._localize_dates)
        except (IOError, vobject.base.ParseError) as err:
            verb = "open" if isinstance(err, IOError) else "parse"
            logging.debug("Error: Could not %s file %s\n%s", verb, filename, err)
            if self._skip:
                errors += 1
            else:
                logging.error("The vcard file %s of address book %s could not be parsed\nUse --debug for more information or --skip-unparsable to proceed", filename, self.name)
                sys.exit(2)
        else:
            uid = card.get_uid()
            if not uid:
                logging.warning("Card %s from address book %s has no UID and will not be available.", card, self.name)
            elif uid in self.contacts:
                logging.warning("Card %s and %s from address book %s have the same UID. The former will not be available.", card, self.contacts[uid], self.name)
            else:
                self.contacts[uid] = card

    self._loaded = True
    if errors:
        logging.warning("%d of %d vCard files of address book %s could not be parsed.", errors, len(self.contacts) + errors, self)
    logging.debug('Loaded %s contacts from address book %s.', len(self.contacts), self.name)

