def FULL_TEXT(val):
    # Convert float to string representation
    if isinstance(val, float):
        val = repr(val)
    # Handle None or empty string
    elif val in (None, ''):
        return None
    # Convert non-string types to string
    elif not isinstance(val, six.string_types):
        if six.PY3 and isinstance(val, bytes):
            val = val.decode('latin-1')
        else:
            val = str(val)
    # Split, lower, strip punctuation, and remove duplicates
    r = sorted(set([x for x in [s.lower().strip(string.punctuation) for s in val.split()] if x]))
    # Encode to UTF-8 if not already a string
    if not isinstance(val, str):
        return [s.encode('utf-8') for s in r]
    return r

