def get_reusable_executor(max_workers=None, context=None, timeout=10, kill_workers=False, reuse="auto", job_reducers=None, result_reducers=None, initializer=None, initargs=()):
    with _executor_lock:
        global _executor, _executor_kwargs
        if max_workers is None:
            if reuse is True and _executor is not None:
                max_workers = _executor._max_workers
            else:
                max_workers = cpu_count()
        elif max_workers <= 0:
            raise ValueError("max_workers must be greater than 0, got {}.".format(max_workers))

        if isinstance(context, STRING_TYPE):
            context = get_context(context)
        if context is not None and context.get_start_method() == "fork":
            raise ValueError("Cannot use reusable executor with the 'fork' context")

        kwargs = dict(context=context, timeout=timeout, job_reducers=job_reducers, result_reducers=result_reducers, initializer=initializer, initargs=initargs)

        if _executor is None:
            mp.util.debug("Create a executor with max_workers={}.".format(max_workers))
            executor_id = _get_next_executor_id()
            _executor_kwargs = kwargs
            _executor = executor = _ReusablePoolExecutor(_executor_lock, max_workers=max_workers, executor_id=executor_id, **kwargs)
        else:
            if reuse == 'auto':
                reuse = kwargs == _executor_kwargs
            if (executor._flags.broken or executor._flags.shutdown or not reuse):
                if executor._flags.broken:
                    reason = "broken"
                elif executor._flags.shutdown:
                    reason = "shutdown"
                else:
                    reason = "arguments have changed"
                mp.util.debug("Creating a new executor with max_workers={} as the previous instance cannot be reused ({}).".format(max_workers, reason))
                executor.shutdown(wait=True, kill_workers=kill_workers)
                _executor = executor = _executor_kwargs = None
                return get_reusable_executor(max_workers=max_workers, **kwargs)
            else:
                mp.util.debug("Reusing existing executor with max_workers={}.".format(executor._max_workers))
                executor._resize(max_workers)

        return executor

