def _recursive_terminate(pid):
    if sys.platform == "win32":
        try:
            subprocess.check_output(["taskkill", "/F", "/T", "/PID", str(pid)], stderr=None)
        except subprocess.CalledProcessError as e:
            if e.returncode not in [1, 128, 255]:
                raise
            elif e.returncode == 1:
                try:
                    os.kill(pid, signal.SIGTERM)
                except OSError as e:
                    if e.errno != errno.ESRCH:
                        raise
                    else:
                        try:
                            children_pids = subprocess.check_output(["pgrep", "-P", str(pid)], stderr=None)
                        except subprocess.CalledProcessError as e:
                            if e.returncode == 1:
                                children_pids = b''
                            else:
                                raise
                        children_pids = children_pids.decode().split('\n')[:-1]
                        for cpid in children_pids:
                            cpid = int(cpid)
                            _recursive_terminate(cpid)
                        try:
                            os.kill(pid, signal.SIGTERM)
                        except OSError as e:
                            if e.errno != errno.ESRCH:
                                raise

