def main(fd, verbose=0):
    # Protect the process from signals like ^C and "killall python"
    signal.signal(signal.SIGINT, signal.SIG_IGN)
    signal.signal(signal.SIGTERM, signal.SIG_IGN)
    if _HAVE_SIGMASK:
        signal.pthread_sigmask(signal.SIG_UNBLOCK, _IGNORED_SIGNALS)

    # Close stdin and stdout if they are open
    for f in (sys.stdin, sys.stdout):
        try:
            f.close()
        except Exception:
            pass

    if verbose:
        sys.stderr.write("Main semaphore tracker is running\n")
        sys.stderr.flush()

    cache = set()

    try:
        # Read commands from the file descriptor
        with os.fdopen(fd, 'rb') as f:
            for line in f:
                try:
                    cmd, name = line.strip().split(b':')
                    if cmd == b'REGISTER':
                        name = name.decode('ascii')
                        cache.add(name)
                        if verbose:
                            sys.stderr.write("[SemaphoreTracker] register {}\n".format(name))
                            sys.stderr.flush()
                    elif cmd == b'UNREGISTER':
                        name = name.decode('ascii')
                        cache.remove(name)
                        if verbose:
                            sys.stderr.write("[SemaphoreTracker] unregister {} (cache size: {})\n".format(name, len(cache)))
                            sys.stderr.flush()
                    elif cmd == b'PROBE':
                        pass
                    else:
                        raise RuntimeError('unrecognized command %r' % cmd)
                except BaseException:
                    try:
                        sys.excepthook(*sys.exc_info())
                    except BaseException:
                        pass
    finally:
        # Cleanup any remaining semaphores
        if cache:
            warnings.warn('semaphore_tracker: There appear to be {} leaked semaphores to clean up at shutdown'.format(len(cache)))
        for name in cache:
            try:
                try:
                    sem_unlink(name)
                    if verbose:
                        sys.stderr.write("[SemaphoreTracker] unlink {}\n".format(name))
                        sys.stderr.flush()
                except Exception as e:
                    warnings.warn('semaphore_tracker: {}: {}'.format(name, e))
            finally:
                pass

        if verbose:
            sys.stderr.write("semaphore tracker shut down\n")
            sys.stderr.flush()

