def ensure_running(self):
    with self._lock:
        if self._fd is not None:
            if self._check_alive():
                return
            os.close(self._fd)
            try:
                os.waitpid(self._pid, 0)
            except OSError:
                pass
            self._fd = None
            self._pid = None
            warnings.warn('semaphore_tracker: process died unexpectedly, relaunching. Some semaphores might leak.')

        fds_to_pass = []
        try:
            fds_to_pass.append(sys.stderr.fileno())
        except Exception:
            pass
        r, w = os.pipe()
        cmd = f'from {main.__module__} import main; main({r}, {VERBOSE})'
        try:
            fds_to_pass.append(r)
            exe = spawn.get_executable()
            args = [exe] + util._args_from_interpreter_flags()
            if sys.version_info[:2] <= (3, 3):
                import re
                for i in range(1, len(args)):
                    args[i] = re.sub("-R+", "-R", args[i])
            args += ['-c', cmd]
            util.debug(f"launching Semaphore tracker: {args}")
            if _HAVE_SIGMASK:
                signal.pthread_sigmask(signal.SIG_BLOCK, _IGNORED_SIGNALS)
            pid = spawnv_passfds(exe, args, fds_to_pass)
            finally:
                if _HAVE_SIGMASK:
                    signal.pthread_sigmask(signal.SIG_UNBLOCK, _IGNORED_SIGNALS)
        except BaseException:
            os.close(w)
            raise
        else:
            self._fd = w
            self._pid = pid
        finally:
            os.close(r)

