def disassemble_bytes(orig_msg, orig_msg_nocr, code, lasti=-1, cur_line=0, start_line=-1, end_line=None, relative_pos=False, varnames=(), names=(), constants=(), cells=(), freevars=(), linestarts={}, highlight='light', start_offset=0, end_offset=None):
    statement_count = 10000 if end_line is None else end_line
    labels = findlabels(code)
    null_print = lambda x: None if start_line > cur_line else orig_msg_nocr

    for instr in get_instructions_bytes(code, opc, varnames, names, constants, cells, linestarts):
        offset = instr.offset
        if end_offset and offset > end_offset:
            break
        if instr.starts_line:
            if offset:
                msg("")
            cur_line = instr.starts_line
            if (start_line and ((start_line > cur_line) or start_offset and start_offset > offset)):
                msg_nocr = null_print
                msg = null_print
            else:
                statement_count -= 1
                msg_nocr = orig_msg_nocr
                msg = orig_msg
        if ((cur_line > end_line) or (end_offset and offset > end_offset)):
            break
        msg_nocr(format_token(Mformat.LineNumber, "%4d" % cur_line, highlight=highlight))
        if offset == lasti:
            msg_nocr(format_token(Mformat.Arrow, '-->', highlight=highlight))
        else:
            msg_nocr('   ')
        if offset in labels:
            msg_nocr(format_token(Mformat.Arrow, '>>', highlight=highlight))
        else:
            msg_nocr('  ')
        msg_nocr(repr(offset).rjust(4))
        msg_nocr(' ')
        msg_nocr(format_token(Mformat.Opcode, instr.opname.ljust(20), highlight=highlight))
        msg_nocr(repr(instr.arg).ljust(10))
        msg_nocr(' ')
        msg_nocr(format_token(Mformat.Name, instr.argrepr.ljust(20), highlight=highlight))

    return code, offset

