def open_json_or_csv_somehow(filename, date_format=None):
    """
    Determines the format of the file (JSON or CSV) and opens it accordingly.

    Args:
    filename (str): The name of the file to be opened.
    date_format (str, optional): The date format to be used for parsing dates. Defaults to None.

    Returns:
    stream: The data stream of the file, either in JSON or CSV format.
    """
    if filename.endswith('.csv'):
        fileformat = 'csv'
    elif filename.endswith('.jsons'):
        fileformat = 'jsons'
    else:
        with open(filename) as opened:
            line = opened.readline()
            if line[0] not in '{[' and not filename.endswith('.json'):
                fileformat = 'csv'
            else:
                if (line.count('{') == line.count('}') and line.count('[') == line.count(']')):
                    # This line contains a complete JSON document. This probably
                    # means it's in linewise JSON ('.jsons') format, unless the
                    # whole file is on one line.
                    char = ' '
                    while char.isspace():
                        char = opened.read()
                    if char == '':
                        fileformat = 'json'
                        break
                if fileformat is None:
                    fileformat = 'jsons'
                else:
                    fileformat = 'json'

    if fileformat == 'json':
        stream = json.load(open(filename), encoding='utf-8')
    elif fileformat == 'csv':
        stream = open_csv_somehow(filename)
    else:
        stream = stream_json_lines(filename)

    return _normalize_data(stream, date_format=date_format)

