def create_request_elements(cls, request_type, credentials, url, method='GET', params=None, headers=None, body='', secret=None, redirect_uri='', scope='', csrf='', user_state=''):
    headers = headers or {}
    params = params or {}
    consumer_key = credentials.consumer_key or ''
    consumer_secret = credentials.consumer_secret or ''
    token = credentials.token or ''
    refresh_token = credentials.refresh_token or credentials.token or ''

    url, base_params = cls._split_url(url)
    params.update(dict(base_params))

    if request_type == cls.USER_AUTHORIZATION_REQUEST_TYPE:
        if consumer_key and redirect_uri and (csrf or not cls.supports_csrf_protection):
            params['client_id'] = consumer_key
            params['redirect_uri'] = redirect_uri
            params['scope'] = scope
            if cls.supports_user_state:
                params['state'] = base64.urlsafe_b64encode(json.dumps({"csrf": csrf, "user_state": user_state}).encode('utf-8'))
            else:
                params['state'] = csrf
            params['response_type'] = 'code'
            headers.update(cls._authorization_header(credentials))
        else:
            raise OAuth2Error('Credentials with valid consumer_key and arguments redirect_uri, scope and state are required to create OAuth 2.0 user authorization request elements!')

    elif request_type == cls.ACCESS_TOKEN_REQUEST_TYPE:
        if consumer_key and consumer_secret:
            params['code'] = token
            params['client_id'] = consumer_key
            params['client_secret'] = consumer_secret
            params['redirect_uri'] = redirect_uri
            params['grant_type'] = 'authorization_code'
            headers.update(cls._authorization_header(credentials))
        else:
