def find_files(directory, pattern, recursive=True):
    """
    Recursively finds files in a directory that match a given pattern.

    Args:
        directory (str): The directory to search.
        pattern (str): The pattern to match against file names.
        recursive (bool, optional): Whether to search recursively. Defaults to True.

    Returns:
        generator: A generator that yields file paths that match the pattern.

    Raises:
        IOError: If the directory does not exist or is not a directory.
    """
    if not os.path.isdir(directory):
        if os.path.exists(directory):
            raise IOError(f"{directory} is not a directory")
        else:
            raise IOError(f"{directory} does not exist")

    if recursive:
        for root, _, files in os.walk(directory):
            for basename in files:
                if fnmatch.fnmatch(basename, pattern):
                    filename = os.path.join(root, basename)
                    yield filename
    else:
        root = directory
        for basename in os.listdir(root):
            if fnmatch.fnmatch(basename, pattern):
                filename = os.path.join(root, basename)
                if os.path.isfile(filename):
                    yield filename

