def reduceProcesses(processes):
    # Sort processes to ensure a deterministic order for merging processes with the same structure.
    processes.sort(key=lambda x: (x.name, maxStmId(x)), reverse=True)

    # Group processes by their rank and attempt to merge processes with similar structures.
    for _, procs in groupby(processes, lambda p: p.rank):
        for iA, pA in enumerate(procs):
            if pA is None:
                continue
            for iB, pB in enumerate(islice(procs, iA + 1, None)):
                if pB is None:
                    continue
                try:
                    pA = tryToMerge(pA, pB)
                except IncompatibleStructure:
                    continue
                procs[iA + 1 + iB] = None
            procs[iA] = pA

    # Yield non-None processes after merging.
    for p in procs:
        if p is not None:
            yield p

