def _merge_statements(statements: List["HdlStatement"]) -> Tuple[List["HdlStatement"], int]:
    # Initialize an order dictionary to keep track of the original index of each statement
    order = {}
    for i, stm in enumerate(statements):
        order[stm] = i

    # Initialize a list to store the new statements and a variable to track the rank decrease
    new_statements = []
    rank_decrease = 0

    # Group statements by their rank
    for rank, stms in groupby(statements, lambda s: s.rank):
        if rank == 0:
            # If the rank is 0, extend the new statements list with the current group
            new_statements.extend(stms)
        else:
            if len(stms) == 1:
                # If the group contains only one statement, extend the new statements list with it
                new_statements.extend(stms)
                continue

            # Try to merge statements if they have the same condition tree
            for iA, stmA in enumerate(stms):
                if stmA is None:
                    continue
                for iB, stmB in enumerate(islice(stms, iA + 1, None)):
                    if stmB is None:
                        continue
                    if stmA._is_mergable(stmB):
                        rank_decrease += stmB.rank
                        stmA._merge_with_other_stm(stmB)
                        stms[iA + 1 + iB] = None
                        new_statements.append(stmA)
                    else:
                        new_statements.append(stmA)
                        new_statements.append(stmB)

    # Sort the new statements list based on their original index
    new_statements.sort(key=lambda stm: order[stm])

    # Return the new statements list and the rank decrease
    return new_statements, rank_decrease

