def packIntf(intf, masterDirEqTo=DIRECTION.OUT, exclude=None):
    if not intf._interfaces:
        if intf._masterDir == masterDirEqTo:
            return intf._sig
        return None

    res = None
    for i in intf._interfaces:
        if exclude is not None and i in exclude:
            continue

        if i._interfaces:
            if i._masterDir == DIRECTION.IN:
                d = DIRECTION.opposite(masterDirEqTo)
            else:
                d = masterDirEqTo
            s = i._pack(d, exclude=exclude)
        else:
            if i._masterDir == masterDirEqTo:
                s = i._sig
            else:
                s = None

        if s is not None:
            if res is None:
                res = s
            else:
                res = res._concat(s)

    return res


**Summary:**
The function `packIntf` is designed to pack interfaces based on their direction and whether they are excluded. It checks if the interface has sub-interfaces and processes them accordingly. If the interface's direction matches `masterDirEqTo`, it returns the signal. If not, it recursively packs the sub-interfaces and concatenates the results. If an interface is excluded, it is skipped. The function returns the concatenated result of all processed interfaces.

