    for proc in self._combProcsToRun:
        cont = self._outputContainers[proc]
        proc(self, cont)
        for sigName, sig in cont._all_signals:
            newVal = getattr(cont, sigName)
            if newVal is not None:
                res = self._conflictResolveStrategy(newVal)
