def _compute_missing_rates(self, currency):
    rates = self._rates[currency]  # Retrieve the rates for the given currency
    tmp = defaultdict(lambda: [None, None])  # Initialize a dictionary to store closest rates and distances

    # Forward pass to find the closest rates and distances
    for date in sorted(rates):
        rate = rates[date]
        if rate is not None:
            closest_rate = rate
            dist = 0
        else:
            dist += 1
        tmp[date][0] = closest_rate, dist

    # Backward pass to find the closest rates and distances
    for date in sorted(rates, reverse=True):
        rate = rates[date]
        if rate is not None:
            closest_rate = rate
            dist = 0
        else:
            dist += 1
        tmp[date][1] = closest_rate, dist

    # Calculate the missing rates using the closest rates and distances
    for date in sorted(tmp):
        (r0, d0), (r1, d1) = tmp[date]
        rates[date] = (r0 * d1 + r1 * d0) / (d0 + d1)
        if self.verbose:
            print(f'{currency}: filling {date} missing rate using {r0} ({d0}d old) and {r1} ({d1}d later)')

