def comments(self):
    # Generate a range of record numbers from 2 to self.fward
    record_numbers = range(2, self.fward)

    # If there are no record numbers, return an empty string
    if not record_numbers:
        return ''

    # Read the first 1000 bytes from each record number and join them into a single byte string
    data = b''.join(self.read_record(n)[0:1000] for n in record_numbers)

    try:
        # Decode the byte string to ASCII, replace null bytes with newlines, and return the result
        return data[:data.find(b'\4')].decode('ascii').replace('\0', '\n')
    except IndexError:
        # If the EOT byte is missing, raise a ValueError
        raise ValueError('DAF file comment area is missing its EOT byte')
    except UnicodeDecodeError:
        # If the data is not ASCII text, raise a ValueError
        raise ValueError('DAF file comment area is not ASCII text')

