def stream(url, headers, stream_to=None, retry=True):
    bot.debug("GET %s" % url)
    if DISABLE_SSL_CHECK:
        bot.warning('Verify of certificates disabled! ::TESTING USE ONLY::')

    response = requests.get(url, headers=headers, verify=not DISABLE_SSL_CHECK, stream=True)

    if response.status_code in [401, 403]:
        headers = update_token(headers)
        return stream(url, headers, stream_to, retry=False)

    elif response.status_code == 200:
        content_size = None
        if 'Content-Length' in response.headers:
            content_size = int(response.headers['Content-Length'])
        bot.show_progress(progress=0, content_size=content_size, length=35)

        chunk_size = 1 << 20
        with open(stream_to, 'wb') as filey:
            for chunk in response.iter_content(chunk_size=chunk_size):
                filey.write(chunk)
                if content_size is not None:
                    progress += chunk_size
                    bot.show_progress(iteration=progress, total=content_size, length=35, carriage_return=False)

        sys.stdout.write('\n')
        return stream_to

    else:
        bot.error("Problem with stream, response %s" % (response.status_code))
        sys.exit(1)

