def find_single_recipe(filename, pattern="Singularity", manifest=None):
    """
    Finds a single recipe in a given file based on a pattern and updates a manifest if provided.

    Args:
        filename (str): The path to the file to search.
        pattern (str, optional): The pattern to match the file basename. Defaults to "Singularity".
        manifest (dict, optional): A dictionary to store or update the recipe information. Defaults to None.

    Returns:
        dict or None: The recipe information if found, otherwise None.
    """
    if pattern is None:
        pattern = "Singularity*"

    recipe = None
    file_basename = os.path.basename(filename)
    if fnmatch.fnmatch(file_basename, pattern):
        recipe = {
            'path': os.path.abspath(filename),
            'modified': os.path.getmtime(filename)
        }

    if manifest is not None and recipe is not None:
        container_uri = '/'.join(filename.split('/')[ - 2:])
        if container_uri in manifest:
            if manifest[container_uri]['modified'] < os.path.getmtime(filename):
                manifest[container_uri] = recipe
        else:
            manifest[container_uri] = recipe

    return manifest if manifest is not None else recipe

