    if value is None or not value.strip():
        tag = key
    else:
        value = BAD_TAG_CHAR_REGEXP.sub('_', value).strip()
        tag = '%s:%s' % (key, value)

    # Ensure the tag starts with a letter and is lowercase
    if tag and not tag[0].isalpha():
        tag = 'a' + tag
    tag = tag.lower()[:200]

    # Append an underscore if it's a reserved word
    if tag in ['device', 'host', 'source']:
        tag = tag + '_'

    return tag

