def project_usls_on_dictionary(usls, allowed_terms=None):
    # Initialize a dictionary to map cells to USLs and a set to store tables
    cells_to_usls = defaultdict(set)
    tables = set()

    # Iterate over each USL
    for u in usls:
        # Iterate over each term in the USL
        for t in u.objects(Term):
            # Iterate over each singular sequence in the term
            for c in t.singular_sequences:
                # If this is the first time encountering the cell, add its relations to the tables set
                if not cells_to_usls[c]:
                    tables.update(c.relations.contained)
                # Add the USL to the set of USLs for this cell
                cells_to_usls[c].add(u)

    # If allowed_terms are provided, filter the tables and cells_to_usls accordingly
    if allowed_terms:
        allowed_terms = set(allowed_terms)
        tables = tables & allowed_terms
        cells_to_usls = {c: l for c, l in cells_to_usls.items() if c in allowed_terms}

    # Create a dictionary mapping tables to USLs
    tables_to_usls = {table: list(set(u for c in table.singular_sequences for u in cells_to_usls[c])) for table in tables if not isinstance(table, TableSet)}

    return tables_to_usls

