def update_attributes(self, attr_dict):
    # List of allowed attributes to update
    valid_directives = ["pid", "ignore_type", "ignore_pid", "extra_input", "group", "input_type"]

    # Iterate through each attribute-value pair in the input dictionary
    for attribute, val in attr_dict.items():
        # If the attribute is a valid directive and exists in the object, update it
        if attribute in valid_directives and hasattr(self, attribute):
            setattr(self, attribute, val)

        # Special handling for the 'params' attribute
        elif attribute == "params":
            for name, value in val.items():
                if name in self.params:
                    self.params[name]["default"] = value
                else:
                    raise eh.ProcessError(f"The parameter name '{name}' does not exist for component '{self.template}'")

        # Update other attributes in the directives dictionary
        else:
            for p in self.directives:
                self.directives[p][attribute] = val

