        if operator == "mix":
            lst = ",".join(channel_list[1:])
            s = f"{first_status}.mix({lst})"
        elif operator == "join":
            s = first_status
            for ch in channel_list[1:]:
                s += f".join({ch})"
            s += ".map{ ot -> [ ot[0], ot[1..-1] ] }"
        logger.debug(f"Status channel string: {s}")
        self._context = {"compile_channels": s}

