def _size_coverter(s):
    """
    Converts a string representing a size with units (KB, B, MB, GB, TB) to a float value in bytes.

    Parameters:
    s (str): A string representing a size with units.

    Returns:
    float: The size in bytes.
    """
    s = s.upper()
    if s.endswith("KB"):
        return float(s.rstrip("KB")) / 1024
    elif s.endswith("B"):
        return float(s.rstrip("B")) / 1024 / 1024
    elif s.endswith("MB"):
        return float(s.rstrip("MB"))
    elif s.endswith("GB"):
        return float(s.rstrip("GB")) * 1024
    elif s.endswith("TB"):
        return float(s.rstrip("TB")) * 1024 * 1024
    else:
        return float(s)

