def _get_component_str(component, params=None, directives=None):
    """
    Generates a string representation of a component with optional parameters and directives.

    Args:
        component (str): The name of the component.
        params (dict, optional): A dictionary of parameters to be included in the component string. Defaults to None.
        directives (dict, optional): A dictionary of directives to be included in the component string. Defaults to None.

    Returns:
        str: A string representation of the component, including any provided parameters and directives.
    """
    final_directives = directives if directives else {}
    if params:
        final_directives["params"] = params
    if final_directives:
        return "{}={}".format(component, json.dumps(final_directives, separators=(",", ":")))
    else:
        return component

