def get_trim_index(biased_list):
    # Check if the entire list is unbiased
    if set(biased_list) == {False}:
        return 0

    # Check if the first 5 elements are unbiased
    if set(biased_list[:5]) == {False}:
        return 0

    # Iterate through the list to find the last biased position
    # followed by two unbiased positions
    for i, val in enumerate(biased_list):
        if val and set(biased_list[i + 1:i + 3]) == {False}:
            return i + 1

    # If no valid index is found, return the length of the list
