                    "input": p.input_type,
                    "output": p.output_type if p.output_type else "None",
                    "lane": p.lane,
                },
                "children": []
            }

            # Add directives to the tooltip
            dir_var = ""
            for k2, v2 in p.directives.items():
                dir_var += k2
                for d in v2:
                    try:
                        directive = v2[d].replace("'", "").replace('"', '') if isinstance(v2[d], str) else v2[d]
