def find_estimation(jam, boundaries_id, labels_id, params):
    # Set the namespace based on the 'hier' parameter
    namespace = "multi_segment" if params["hier"] else "segment_open"

    # Search for annotations based on the provided parameters
    ann = jam.search(namespace=namespace).search(**{"Sandbox.boundaries_id": boundaries_id}).search(**{"Sandbox.labels_id": lambda x: (isinstance(x, six.string_types) and re.match(labels_id, x) is not None) or x is None})

    # Apply additional search filters based on the parameters
    for key, val in zip(params.keys(), params.values()):
        if isinstance(val, six.string_types):
            ann = ann.search(**{"Sandbox.%s" % key: val})
        else:
            ann = ann.search(**{"Sandbox.%s" % key: lambda x: x == val})

    # Check if more than one estimation was found
    if len(ann) > 1:
        logging.warning("More than one estimation with same parameters.")

    # Return the first estimation if found, otherwise return None
    if len(ann) > 0:
        ann = ann[0]
    else:
        ann = None

    return ann

