    features = config["features"].features

    # Segment the file using the specified boundaries and labels
    if bounds_module is not None and labels_module is not None and bounds_module.__name__ == labels_module.__name__:
        S = bounds_module.Segmenter(file_struct, **config)
        est_idxs, est_labels = S.processFlat()
    else:
        # Identify segment boundaries
