def spool(iterable, maxlen=1250):
    words = 0
    text = ""
    try:
        while True:
            while words < maxlen:
                stream = yield text
                words = reduce(accumulator, stream, words)
            iterable.send(text)
            words = 0
            text = ""
    except GeneratorExit:
        iterable.send(text)
        iterable.close()

