def optimize_Tc(self):
    from scipy.optimize import minimize_scalar
    initial_Tc = self.Tc

    def cost(Tc):
        self.set_Tc(Tc)
        return -self.total_LH()

    sol = minimize_scalar(cost, bounds=[ttconf.TINY_NUMBER, 10.0])

