def _attach_sequences_to_nodes(self):
    # Initialize failed_leaves counter
    failed_leaves = 0

    # Determine the alignment dictionary based on whether the alignment is specified as a difference from the reference
    if self.is_vcf:
        dic_aln = self.aln
    else:
        dic_aln = {k.name: seq2array(k.seq, fill_overhangs=self.fill_overhangs, ambiguous_character=self.gtr.ambiguous) for k in self.aln}

    # Loop over leaves to assign multiplicities (e.g., number of identical reads)
    for l in self.tree.get_terminals():
        if l.name in self.seq_multiplicity:
            l.count = self.seq_multiplicity[l.name]
        else:
            l.count = 1.0

    # Loop over the tree to assign sequences
    for l in self.tree.find_clades():
        if l.name in dic_aln:
            l.sequence = dic_aln[l.name]
        elif l.is_terminal():
            self.logger("***WARNING: TreeAnc._attach_sequences_to_nodes: NO SEQUENCE FOR LEAF: %s" % l.name, 0, warn=True)
            failed_leaves += 1
            l.sequence = seq2array(self.gtr.ambiguous * self.seq_len, fill_overhangs=self.fill_overhangs, ambiguous_character=self.gtr.ambiguous)

    # Check if more than 30% of terminal nodes cannot be assigned a sequence
    if failed_leaves > self.tree.count_terminals() / 3:
        self.logger("ERROR: At least 30% terminal nodes cannot be assigned with a sequence!\n", 0, warn=True)
        self.logger("Are you sure the alignment belongs to the tree?", 2, warn=True)
        break

    # Log a warning if any nodes don't have a matching sequence in the alignment
    if failed_leaves:
        self.logger("***WARNING: TreeAnc: %d nodes don't have a matching sequence in the alignment. POSSIBLE ERROR." % failed_leaves, 0, warn=True)

    # Extend the profile to contain additional unknown characters
    self.extend_profile()

    # Return the reduced alignment
    return self.make_reduced_alignment()

