def _fitch_anc(self, **kwargs):
    # Set Fitch profiles for each terminal node
    for terminal in self.tree.get_terminals():
        terminal.state = [[k] for k in terminal.cseq]

    L = len(self.tree.get_terminals()[0].cseq)
    self.logger("TreeAnc._fitch_anc: Walking up the tree, creating the Fitch profiles", 2)

    # Create Fitch profiles for non-terminal nodes
    for node in self.tree.get_nonterminals(order='postorder'):
        node.state = [self._fitch_state(node, k) for k in range(L)]

    # Handle ambiguous states at the root
    ambs = [i for i in range(L) if len(self.tree.root.state[i]) > 1]
    if len(ambs) > 0:
        for amb in ambs:
            self.logger(f"Ambiguous state of the root sequence in the position {amb}: {self.tree.root.state[amb]}, choosing {self.tree.root.state[amb][0]}", 4)
            self.tree.root.cseq = np.array([k[np.random.randint(len(k)) if len(k) > 1 else 0] for k in self.tree.root.state])

    if self.is_vcf:
        self.tree.root.sequence = self.dict_sequence(self.tree.root)
    else:
        self.tree.root.sequence = self.expanded_sequence(self.tree.root)

    self.logger("TreeAnc._fitch_anc: Walking down the tree, generating sequences from the Fitch profiles.", 2)
    N_diff = 0

    # Generate sequences for non-terminal nodes
    for node in self.tree.get_nonterminals(order='preorder'):
        if node.up is not None:
            sequence = np.array([node.up.cseq[i] if node.up.cseq[i] in node.state[i] else node.state[i][0] for i in range(L)])
            if hasattr(node, 'sequence'):
                N_diff += (sequence != node.cseq).sum()
            else:
                N_diff += L
            node.cseq = sequence

        if self.is_vcf:
            node.sequence = self.dict_sequence(node)
        else:
            node.sequence = self.expanded_sequence(node)

        node.mutations = self.get_mutations(node)
        node.profile = seq2prof(node.cseq, self.gtr.profile_map)
        del node.state  # No need

