def standard(model, **kwargs):
    """
    Returns a substitution model based on the specified model name.

    Args:
        model (str): The name of the substitution model.
        **kwargs: Additional keyword arguments to pass to the model.

    Returns:
        object: The substitution model object.

    Raises:
        KeyError: If the specified model is not available.
    """
    from nuc_models import JC69, K80, F81, HKY85, T92, TN93
    from aa_models import JTT92

    model = model.lower()

    if model in ['jc', 'jc69', 'jukes-cantor', 'jukes-cantor69', 'jukescantor', 'jukescantor69']:
        return JC69(**kwargs)
    elif model in ['k80', 'kimura80', 'kimura1980']:
        return K80(**kwargs)
    elif model in ['f81', 'felsenstein81', 'felsenstein1981']:
        return F81(**kwargs)
    elif model in ['hky', 'hky85', 'hky1985']:
        return HKY85(**kwargs)
    elif model in ['t92', 'tamura92', 'tamura1992']:
        return T92(**kwargs)
    elif model in ['tn93', 'tamura_nei_93', 'tamuranei93']:
        return TN93(**kwargs)
    elif model in ['jtt', 'jtt92']:
        return JTT92(**kwargs)
    else:
        raise KeyError(f"The GTR model '{model}' is not in the list of available models.")

