def next(self):
    if not hasattr(self, '_cursor'):
        self.__iter__()
    if self._cursor == len(self):
        raise StopIteration()
    if self._buffer_idx == len(self._buffer):
        self.execute(self._page_offset + self._buffer_idx)
        self._buffer_idx = 0
        self._cursor += 1
    self._buffer_idx += 1
    return self._buffer[self._buffer_idx - 1]

