def download_vault_folder(remote_path, local_path, dry_run=False, force=False):
    """
    Downloads all files and sub-folders from a specified remote Vault path to a local directory.

    Parameters:
    remote_path (str): The full path of the remote Vault folder to download.
    local_path (str): The local directory path where the files and folders will be saved.
    dry_run (bool, optional): If True, simulates the download process without actually downloading files. Defaults to False.
    force (bool, optional): If True, forces the download of files by deleting existing local copies. Defaults to False.

    Raises:
    Exception: If write access to the local path is not available.

    Returns:
    None
    """
    local_path = os.path.normpath(os.path.expanduser(local_path))
    if not os.access(local_path, os.W_OK):
        raise Exception('Write access to local path ({}) is required'.format(local_path))

    full_path, path_dict = solvebio.Object.validate_full_path(remote_path)
    vault = solvebio.Vault.get_by_full_path(path_dict['vault'])
    print('Downloading all files from {} to {}'.format(full_path, local_path))

    if path_dict['path'] == '/':
        parent_object_id = None
    else:
        parent_object = solvebio.Object.get_by_full_path(remote_path, assert_type='folder')
        parent_object_id = parent_object.id

    print('Creating local directory structure at: {}'.format(local_path))
    if not os.path.exists(local_path):
        if not dry_run:
            os.makedirs(local_path)

    folders = vault.folders(parent_object_id=parent_object_id)
    for f in folders:
        path = os.path.normpath(local_path + f.path)
        if not os.path.exists(path):
            print('Creating folder: {}'.format(path))
            if not dry_run:
                os.makedirs(path)

    files = vault.files(parent_object_id=parent_object_id)
    for f in files:
        path = os.path.normpath(local_path + f.path)
        if os.path.exists(path):
            if force:
                print('Deleting local file (force download): {}'.format(path))
                if not dry_run:
                    os.remove(path)
            else:
                print('Skipping file (already exists): {}'.format(path))
                continue
        print('Downloading file: {}'.format(path))
        if not dry_run:
            f.download(path)

