def repeat(self, day=None):
    if day is None:
        day = self.day
    try:
        d = date(self.year, self.month, day)
    except ValueError:
        return self.count
    if self.count_first and d <= self.end_repeat:
        self.count_it(d.day)
    d += timedelta(days=self.num)
    if self.end_on is not None:
        while d.month == self.month and d <= self.end_repeat and d.day <= self.end_on:
            self.count_it(d.day)
            d += timedelta(days=self.num)
    else:
        while d.month == self.month and d <= self.end_repeat:
            self.count_it(d.day)
            d += timedelta(days=self.num)

