def get_length(alt_len, ref_len, category, pos, end, svtype=None, svlen=None):
    """
    Calculates the length of a genetic variant based on the provided parameters.

    Parameters:
    alt_len (int): Length of the alternate allele.
    ref_len (int): Length of the reference allele.
    category (str): Type of genetic variant ('snv', 'indel', 'cancer', 'sv').
    pos (int): Start position of the variant.
    end (int): End position of the variant.
    svtype (str, optional): Type of structural variant ('bnd'). Defaults to None.
    svlen (int, optional): Length of the structural variant. Defaults to None.

    Returns:
    int: Length of the genetic variant.
    """
    length = -1  # Default length if category is 'snv', 'indel', or 'cancer'

    if category in ('snv', 'indel', 'cancer'):
        if ref_len == alt_len:
            length = alt_len
        else:
            length = abs(ref_len - alt_len)
    elif category == 'sv':
        if svtype == 'bnd':
            length = int(10e10)
        else:
            if svlen:
                length = abs(int(svlen))
            elif end:
                if end != pos:
                    length = end - pos

    return length

