def get_end(pos, alt, category, snvend=None, svend=None, svlen=None):
    # Set end to the same as start position by default
    end = pos

    # Handle SNV, INDEL, and cancer categories
    if category in ('snv', 'indel', 'cancer'):
        end = snvend

    # Handle SV category
    elif category == 'sv':
        end = svend

    # Handle SVs with end set to start position
    if svend == pos:
        if svlen:
            end = pos + svlen

    # Handle BND category with ':' in alt field
    if ':' in alt:
        match = BND_ALT_PATTERN.match(alt)
        if match:
            end = int(match.group(2))

    return end

