def evaluated_variants(self, case_id):
    # Query to find all variants that have been evaluated in some way for a specific case
    query = {
        '$and': [
            {'case_id': case_id},
            {'$or': [
                {'acmg_classification': {'$exists': True}},
                {'manual_rank': {'$exists': True}},
                {'dismiss_variant': {'$exists': True}},
            ]}
        ]
    }

    # Collect the evaluated variants in a dictionary
    variants = {}
    for var in self.variant_collection.find(query):
        variants[var['variant_id']] = self.add_gene_info(var)

    # Query to find all variant comments for the case
    event_query = {
        '$and': [
            {'case': case_id},
            {'category': 'variant'},
            {'verb': 'comment'}
        ]
    }

    # Collect all variant IDs for commented variants
    comment_variants = {event['variant_id'] for event in self.event_collection.find(event_query)}

    # Get the variant objects for commented variants, if they exist
    for var_id in comment_variants:
        # Skip if the variant is already added
        if var_id in variants:
            continue

        # Get the variant with the specified variant ID
        variant_obj = self.variant(var_id, case_id=case_id)

        # Skip if the variant does not exist
        if not variant_obj:
            continue

        # Mark the variant as commented
        variant_obj['is_commented'] = True
        variants[var_id] = variant_obj

    # Return a list of the variant objects
    return variants.values()

