def get_date(date, date_format=None):
    date_obj = datetime.datetime.now()
    if date:
        if date_format:
            date_obj = datetime.datetime.strptime(date, date_format)
        else:
            if match_date(date):
                date_parts = date.split('-') if len(date.split('-')) == 3 else \
                             date.split(' ') if len(date.split(' ')) == 3 else \
                             date.split('.') if len(date.split('.')) == 3 else \
                             date.split('/')
                date_obj = datetime.datetime(*(int(number) for number in date_parts))
    else:
        raise ValueError("Date %s is invalid" % date)
    return date_obj

