def parse_frequencies(variant, transcripts):
    frequencies = {}
    keys = {
        'thousand_g': ['1000GAF'],
        'thousand_g_max': ['1000G_MAX_AF'],
        'exac': ['EXACAF'],
        'exac_max': ['ExAC_MAX_AF', 'EXAC_MAX_AF'],
        'gnomad': ['GNOMADAF', 'GNOMAD_AF'],
        'gnomad_max': ['GNOMADAF_POPMAX', 'GNOMADAF_MAX']
    }

    for category, key_list in keys.items():
        for key in key_list:
            value = parse_frequency(variant, key)
            if value:
                frequencies[category] = value
                break

    if not frequencies:
        for transcript in transcripts:
            for category, key in keys.items():
                value = transcript.get(f'{category}_maf')
                if value:
                    frequencies[category] = value

    thousand_g_left = parse_frequency(variant, 'left_1000GAF')
    if thousand_g_left:
        frequencies['thousand_g_left'] = thousand_g_left

    thousand_g_right = parse_frequency(variant, 'right_1000GAF')
    if thousand_g_right:
        frequencies['thousand_g_right'] = thousand_g_right

    return frequencies

