def coordinate_filter(self, query, mongo_query):
    """
    Adds genomic coordinates to the query.

    Args:
        query (dict): A dictionary containing the query parameters.
        mongo_query (dict): A dictionary to store the MongoDB query.

    Returns:
        dict: The updated MongoDB query with genomic coordinates.
    """
    chromosome = query.get('chrom')
    if chromosome:
        mongo_query['chromosome'] = chromosome

    start = query.get('start')
    end = query.get('end')
    if start and end:
        mongo_query['position'] = {'$lte': int(end)}
        mongo_query['end'] = {'$gte': int(start)}

    return mongo_query

