def hgnc_genes(self, hgnc_symbol, build='37', search=False):
    """
    Fetches genes based on the HGNC symbol.

    Args:
        hgnc_symbol (str): The HGNC symbol to search for.
        build (str, optional): The genome build version. Defaults to '37'.
        search (bool, optional): Whether to perform a full-text search. Defaults to False.

    Returns:
        pymongo.cursor.Cursor: A cursor containing the matching genes.
    """
    LOG.debug(f"Fetching genes with symbol {hgnc_symbol}")
    if search:
        # First search for a full match
        full_query = self.hgnc_collection.find({
            '$or': [
                {'aliases': hgnc_symbol},
                {'hgnc_id': int(hgnc_symbol) if hgnc_symbol.isdigit() else None}
            ],
            'build': build
        })
        if full_query.count() != 0:
            return full_query
        # If no full match, perform a case-insensitive regex search
        return self.hgnc_collection.find({
            'aliases': {'$regex': hgnc_symbol, '$options': 'i'},
            'build': build
        })
    # If not searching, fetch genes by exact alias
    return self.hgnc_collection.find({'build': build, 'aliases': hgnc_symbol})

