def update_variant_rank(self, case_obj, variant_type='clinical', category='snv'):
    """
    Updates the rank of variants for a given case in the database.

    Args:
        case_obj (dict): The case object containing the case_id.
        variant_type (str, optional): The type of variant to update. Defaults to 'clinical'.
        category (str, optional): The category of variant to update. Defaults to 'snv'.

    Returns:
        None

    Raises:
        BulkWriteError: If the bulk write operation fails.

    """
    # Retrieve all variants sorted by rank score
    variants = self.variant_collection.find({
        'case_id': case_obj['_id'],
        'category': category,
        'variant_type': variant_type
    }).sort('rank_score', pymongo.DESCENDING)

    LOG.info("Updating variant_rank for all variants")

    requests = []
    for index, var_obj in enumerate(variants):
        if len(requests) > 5000:
            try:
                self.variant_collection.bulk_write(requests, ordered=False)
                requests = []
            except BulkWriteError as err:
                LOG.warning("Updating variant rank failed")
                raise err

        operation = pymongo.UpdateOne({
            '_id': var_obj['_id']
        }, {
            '$set': {
                'variant_rank': index + 1,
            }
        })
        requests.append(operation)

    # Update the final batch
    try:
        self.variant_collection.bulk_write(requests, ordered=False)
    except BulkWriteError as err:
        LOG.warning("Updating variant rank failed")
        raise err

    LOG.info("Updating variant_rank done")

