def sanger_ordered(self, institute_id=None, user_id=None):
    # Initialize the query to filter events with the verb 'sanger'
    query = { '$match': { '$and': [ { 'verb': 'sanger' } ] } }

    # Add institute filter to the query if institute_id is provided
    if institute_id:
        query['$match']['$and'].append({ 'institute': institute_id })

    # Add user_id filter to the query if user_id is provided
    if user_id:
        query['$match']['$and'].append({ 'user_id': user_id })

    # Aggregate results to get all sanger ordered variants grouped by case_id
    results = self.event_collection.aggregate([
        query,
        { '$group': { '_id': "$case", 'vars': { '$addToSet': '$variant_id' } } }
    ])

    # Convert the aggregation results to a list
    sanger_ordered = [item for item in results]

    # Return the list of sanger ordered variants
    return sanger_ordered

