def parse_ensembl_line(line, header):
    # Remove trailing whitespace and split the line by tabs
    line = line.rstrip().split('\t')
    # Convert header to lowercase
    header = [head.lower() for head in header]
    # Create a dictionary mapping headers to line values
    raw_info = dict(zip(header, line))
    # Initialize an empty dictionary to store Ensembl-specific information
    ensembl_info = {}

    # Iterate over each key-value pair in the raw_info dictionary
    for word in raw_info:
        value = raw_info[word]
        if not value:
            continue

        # Process chromosome information
        if 'chromosome' in word:
            ensembl_info['chrom'] = value

        # Process gene information
        if 'gene' in word:
            if 'id' in word:
                ensembl_info['ensembl_gene_id'] = value
            elif 'start' in word:
                ensembl_info['gene_start'] = int(value)
            elif 'end' in word:
                ensembl_info['gene_end'] = int(value)

        # Process HGNC symbol and gene name
        if 'hgnc symbol' in word or "gene name" in word:
            ensembl_info['hgnc_symbol'] = value

        # Process HGNC ID
        if 'hgnc id' in word:
            ensembl_info['hgnc_id'] = int(value.split(':')[1])

        # Process transcript information
        if 'transcript' in word:
            if 'id' in word:
                ensembl_info['ensembl_transcript_id'] = value
            elif 'start' in word:
                ensembl_info['transcript_start'] = int(value)
            elif 'end' in word:
                ensembl_info['transcript_end'] = int(value)

        # Process exon information
        if 'exon' in word:
            if 'start' in word:
                ensembl_info['exon_start'] = int(value)
            elif 'end' in word:
