def unpack(data, nbit):
    """
    Unpacks an 8-bit array into a different number of bits.

    Parameters:
    data (np.ndarray): Input 8-bit array.
    nbit (int): Number of bits to unpack into (must be 1, 2, 4, or 8).

    Returns:
    np.ndarray: Unpacked array with the specified number of bits.

    Raises:
    ValueError: If nbit is greater than 8 or if nbit does not divide into 8.
    TypeError: If the data type of the input array is not 8-bit.
    """
    if nbit > 8:
        raise ValueError("unpack: nbit must be <= 8")
    if 8 % nbit != 0:
        raise ValueError("unpack: nbit must divide into 8")
    if data.dtype not in (np.uint8, np.int8):
        raise TypeError("unpack: dtype must be 8-bit")

    if nbit == 8:
        return data
    elif nbit == 4:
        return unpack_4to8(data)
    elif nbit == 2:
        return unpack_2to8(data)
    elif nbit == 1:
        return unpack_1to8(data)

