    self.results['iterations per cacheline'] = iterations_per_cacheline

    # Get loads and stores from predictor
    loads, stores = self.predictor.get_loads(), self.predictor.get_stores()

    # Iterate over memory hierarchy levels (excluding the first one)
    for cache_level, cache_info in enumerate(self.machine['memory hierarchy'][1:], start=1):
        throughput, duplexness = cache_info['non-overlap upstream throughput']

        # Handle memory transfer case
        if isinstance(throughput, str) and throughput == 'full socket memory bandwidth':
            # Calculate cycles for memory transfer
            read_streams = loads[cache_level]
            write_streams = stores[cache_level]
            threads_per_core = 1
            bw, measurement_kernel = self.machine.get_bandwidth(cache_level, read_streams, write_streams, threads_per_core)

            if duplexness == 'half-duplex':
                cycles = (loads[cache_level] + stores[cache_level]) * elements_per_cacheline * element_size * self.machine['clock'] / bw
            else:
                raise NotImplementedError("full-duplex mode is not (yet) supported for memory transfers.")

            # Add penalty cycles for read streams
            if 'penalty cycles per read stream' in cache_info:
                cycles += stores[cache_level] * cache_info['penalty cycles per read stream']

            self.results.update({
                'memory bandwidth kernel': measurement_kernel,
                'memory bandwidth': bw
            })
        else:
            # Handle cache cycles case
            throughput = throughput / self.machine['cacheline size']
            if duplexness == 'half-duplex':
                cycles = (loads[cache_level] + stores[cache_level]) / throughput
            elif duplexness == 'full-duplex':
                cycles = max(loads[cache_level] / throughput, stores[cache_level] / throughput)
            else:
                raise ValueError("Duplexness of cache throughput may only be 'half-duplex' or 'full-duplex', found {} in {}.".

