def iaca_instrumentation(input_file, output_file, block_selection='auto', pointer_increment='auto_with_manual_fallback', debug=False):
    # Read the assembly code from the input file
    assembly_orig = input_file.readlines()

    # If the input and output files are the same, overwrite the output file
    if input_file is output_file:
        output_file.seek(0)
        output_file.truncate()

    # If debug mode is enabled, set block_selection to 'manual'
    if debug:
        block_selection = 'manual'

    # Strip and uncomment the assembly code
    assembly = strip_and_uncomment(copy(assembly_orig))

    # Strip unreferenced labels from the assembly code
    assembly = strip_unreferenced_labels(assembly)

    # Find all assembly blocks
    blocks = find_asm_blocks(assembly)

    # Select the block based on the block_selection parameter
    if block_selection == 'auto':
        block_idx = select_best_block(blocks)
    elif block_selection == 'manual':
        block_idx = userselect_block(blocks, default=select_best_block(blocks), debug=debug)
    elif isinstance(block_selection, int):
        block_idx = block_selection
    else:
        raise ValueError("block_selection has to be an integer, 'auto' or 'manual'")

    # Get the selected block
    block = blocks[block_idx][1]

    # Set the pointer increment based on the pointer_increment parameter
    if pointer_increment == 'auto':
        if block['pointer_increment'] is None:
            raise RuntimeError("pointer_increment could not be detected automatically. Use --pointer-increment to set manually to byte offset of store pointer address between consecutive assembly block iterations.")
    elif pointer_increment == 'auto_with_manual_fallback':
        if block['pointer_increment'] is None:
            block['pointer_increment'] = userselect_increment(block)
    elif pointer_increment == 'manual':
        block['pointer_increment'] = userselect_increment(block)
    elif isinstance(pointer_increment, int):
        block['pointer_increment'] = pointer_increment
    else:
        raise ValueError("pointer_increment has to be an integer, 'auto', 'manual' or 'auto_with_manual_fallback'")

    # Insert markers into the assembly code for the selected block
    instrumented_asm = insert_markers(assembly_orig, block['first_line'], block['last_line'])

    # Write the instrumented assembly code to the output file
    output_file.writelines

