def parse_perfctr_event(perfctr):
    """
    Parses a performance counter event string and returns a tuple containing the event name and its parameters.

    Args:
    perfctr (str): A string representing the performance counter event, formatted as 'event_name:param1=value1:param2=value2:...'.

    Returns:
    tuple: A tuple containing the event name and a dictionary of parameters.

    Raises:
    AssertionError: If the input string does not contain at least one colon (:) separating the event name from its parameters.
    """
    split_perfctr = perfctr.split(':')
    assert len(split_perfctr) >= 2, "At least one colon (:) is required in the event name"
    event_tuple = split_perfctr[:2]
    parameters = {}
    for p in split_perfctr[2:]:
        if '=' in p:
            k, v = p.split('=')
            if v.startswith('0x'):
                parameters[k] = int(v, 16)
            else:
                parameters[k] = int(v)
        else:
            parameters[p] = None
    event_tuple.append(parameters)
    return tuple(event_tuple)

