def fix_env_variable(name, value):
    # Get the original value of the environment variable
    orig = os.environ.get(name, None)

    try:
        if value is not None:
            # Set the environment variable if the value is not None
            os.environ[name] = value
        elif name in os.environ:
            # Unset the environment variable if the value is None
            del os.environ[name]
    finally:
        # Restore the original value if it was set
        if orig is not None:
            os.environ[name] = orig
        elif name in os.environ:
            # Unset the environment variable if it was unset
            del os.environ[name]

