def get(self, key):
    lock.acquire()
    try:
        if key not in self:
            return None
        current_time = time.time()
        if self[key].expire > current_time:
            return self[key].value  # Return the value if the key has not expired
        else:
            # Clean out all expired keys
            deletes = []
            for k, val in self.items():
                if val.expire <= current_time:
                    deletes.append(k)
            for k in deletes:
                del self[k]
            return None
    finally:
        lock.release()

