def short_refs(self):
    # Initialize a dictionary to store naive short references and their corresponding refs
    naive_short_refs_d = {}

    # Iterate over external files and populate the dictionary
    for ef in self._external_files:
        if ef.naive_short_ref not in naive_short_refs_d:
            naive_short_refs_d[ef.naive_short_ref] = set()
        naive_short_refs_d[ef.naive_short_ref].add(ef.ref)

    # Initialize a dictionary to store the final short references
    short_refs = {}

    # Iterate over the items in the naive short references dictionary
    for naive_short_ref, refs in naive_short_refs_d.items():
        if len(refs) == 1:
            # If there is only one ref, use it as the key and the naive short ref as the value
            short_refs[refs.pop()] = naive_short_ref
        else:
            # If there are multiple refs, sort them and create a new key with a suffix
            base, ext = os.path.splitext(naive_short_ref)
            for i, ref in enumerate(sorted(refs)):
                short_refs[ref] = f"{base}-{i}.{ext}"

    # Return the final dictionary of short references
    return short_refs

