def cli_empty_container(context, path, until_empty=False):
    path = path.rstrip('/').decode('utf8')
    conc = Concurrency(context.concurrency)

    def check_conc():
        for (exc_type, exc_value, exc_tb, result) in six.itervalues(conc.get_results()):
            if exc_value:
                with context.io_manager.with_stderr() as fp:
                    fp.write(str(exc_value))
                    fp.write('\n')
                    fp.flush()

    marker = None
    while True:
        with context.client_manager.with_client() as client:
            status, reason, headers, contents = client.get_container(path, marker=marker, headers=context.headers, query=context.query, cdn=context.cdn)
            if status // 100 != 2:
                if status == 404 and context.ignore_404:
                    return
                raise ReturnCode('listing container %r: %s %s' % (path, status, reason))
            if not contents:
                if until_empty and marker:
                    marker = None
                    continue
                break
            for item in contents:
                newpath = '%s/%s' % (path, item['name'])
                new_context = context.copy()
                new_context.ignore_404 = True
                check_conc()
                conc.spawn(newpath, cli_delete, new_context, newpath)
                marker = item['name']
        conc.join()
        check_conc()

