def aes_encrypt(key, stdin, preamble=None, chunk_size=65536, content_length=None):
    if not AES256CBC_Support:
        raise Exception('AES256CBC not supported; likely pycrypto is not installed')

    if preamble:
        yield preamble

    key = hashlib.sha256(key).digest()
    chunk_size = max(16, chunk_size >> 4 << 4)
    iv = Crypto.Random.new().read(16)
    yield iv

    encryptor = Crypto.Cipher.AES.new(key, Crypto.Cipher.AES.MODE_CBC, iv)
    reading = True
    left = None

    if content_length is not None and content_length >= 0:
        left = content_length

    while reading:
        size = chunk_size
        if left is not None and size > left:
            size = left

        chunk = stdin.read(size)
        if not chunk:
            if left is not None and left > 0:
                raise IOError('Early EOF from input')

            yield encryptor.encrypt('\x00' * 16)
            break

        if left is not None:
            left -= len(chunk)

        if left <= 0:
            reading = False

        block = chunk
        trailing = len(block) % 16

        while trailing:
            size = 16 - trailing
            if left is not None and size > left:
                size = left

            chunk = stdin.read(size)
            if not chunk:
                if left is not None and left > 0:
                    raise IOError('Early EOF from input')

                reading = False

            if left is not None:
                left -= len(chunk)

            if left <= 0:
                reading = False

            block += chunk
            trailing = len(block) % 16

        yield encryptor.encrypt(block)

