def _change_logging_kwargs(kwargs):
    # Extract and remove logging-related parameters from kwargs
    log_levels = kwargs.pop('log_level', None)
    log_folder = kwargs.pop('log_folder', 'logs')
    logger_names = kwargs.pop('logger_names', '')
    log_multiproc = kwargs.pop('log_multiproc', True)

    # Handle cases where logger_names and log_levels are not lists
    if not isinstance(logger_names, (tuple, list)):
        logger_names = [logger_names]
    if not isinstance(log_levels, (tuple, list)):
        log_levels = [log_levels]

    # If log_levels is a single value, repeat it for each logger_name
    if len(log_levels) == 1:
        log_levels = [log_levels[0]] * len(logger_names)

    # Create a deep copy of the LOGGING_DICT
    dictionary = copy.deepcopy(LOGGING_DICT)

    # Adjust prefixes based on log_multiproc
    prefixes = [''] if not log_multiproc else [key for key in dictionary.keys() if key.startswith('multiproc_')]

    # Update handler filenames and add loggers to the dictionary
    for prefix in prefixes:
        for handler_dict in dictionary[prefix + 'handlers'].values():
            if 'filename' in handler_dict:
                filename = os.path.join(log_folder, handler_dict['filename'])
                filename = os.path.normpath(filename)
                handler_dict['filename'] = filename
        dictionary[prefix + 'loggers'] = {}
        logger_dict = dictionary[prefix + 'loggers']
        for idx, logger_name in enumerate(logger_names):
            logger_dict[logger_name] = {'level': log_levels[idx], 'handlers': list(dictionary[prefix + 'handlers'].keys())}

    # Add the updated dictionary to kwargs as 'log_config'
    kwargs['log_config'] = dictionary

