def rename_log_file(filename, trajectory=None, env_name=None, traj_name=None, set_name=None, run_name=None, process_name=None, host_name=None):
    """
    Renames a log file by replacing placeholders with actual values from the trajectory and environment.

    Parameters:
    filename (str): The original log file name containing placeholders.
    trajectory (pypet.Trajectory, optional): The trajectory object containing environment and run information.
    env_name (str, optional): The environment name to replace the placeholder.
    traj_name (str, optional): The trajectory name to replace the placeholder.
    set_name (str, optional): The set name to replace the placeholder.
    run_name (str, optional): The run name to replace the placeholder.
    process_name (str, optional): The process name to replace the placeholder.
    host_name (str, optional): The host name to replace the placeholder.

    Returns:
    str: The renamed log file name.
    """
    if pypetconstants.LOG_ENV in filename:
        if env_name is None:
            env_name = trajectory.v_environment_name
        filename = filename.replace(pypetconstants.LOG_ENV, env_name)
    if pypetconstants.LOG_TRAJ in filename:
        if traj_name is None:
            traj_name = trajectory.v_name
        filename = filename.replace(pypetconstants.LOG_TRAJ, traj_name)
    if pypetconstants.LOG_RUN in filename:
        if run_name is None:
            run_name = trajectory.f_wildcard('$')
        filename = filename.replace(pypetconstants.LOG_RUN, run_name)
    if pypetconstants.LOG_SET in filename:
        if set_name is None:
            set_name = trajectory.f_wildcard('$set')
        filename = filename.replace(pypetconstants.LOG_SET, set_name)
    if pypetconstants.LOG_PROC in filename:
        if process_name is None:
            process_name = multiprocessing.current_process().name + '-' + str(os.getpid())
        filename = filename.replace(pypetconstants.LOG_PROC, process_name)
    if pypetconstants.LOG_HOST in filename:
        if host_name is None:
            host_name = socket.getfqdn().replace('.', '-')
        filename = filename.replace(pypetconstants.LOG_HOST, host_name)
    return filename

