def results_equal(a, b):
    # Check if both inputs are parameters
    if a.v_is_parameter and b.v_is_parameter:
        raise ValueError('Both inputs are not results.')

    # Check if either input is a parameter
    if a.v_is_parameter or b.v_is_parameter:
        return False

    # Check if the full names of the inputs are different
    if a.v_full_name != b.v_full_name:
        return False

    # Check if one input has data but the other does not
    if hasattr(a, '_data') and not hasattr(b, '_data'):
        return False

    # Check if both inputs have data
    if hasattr(a, '_data'):
        akeyset = set(a._data.keys())
        bkeyset = set(b._data.keys())

        # Check if the sets of keys are different
        if akeyset != bkeyset:
            return False

        # Check if the values for each key are equal
        for key in a._data:
            val = a._data[key]
            bval = b._data[key]
            if not nested_equal(val, bval):
                return False

    # If all checks pass, the results are equal
    return True

