def parameters_equal(a, b):
    # Check if both inputs are not parameters
    if not b.v_is_parameter and not a.v_is_parameter:
        raise ValueError('Both inputs are not parameters')

    # Check if either input is not a parameter
    if not b.v_is_parameter or not a.v_is_parameter:
        return False

    # Check if full names are different
    if a.v_full_name != b.v_full_name:
        return False

    # Check if both are empty
    if a.f_is_empty() and b.f_is_empty():
        return True

    # Check if one is empty and the other is not
    if a.f_is_empty() != b.f_is_empty():
        return False

    # Check if values are of the same type
    if not a._values_of_same_type(a.f_get(), b.f_get()):
        return False

    # Check if values are equal
    if not a._equal_values(a.f_get(), b.f_get()):
        return False

    # Check if both have ranges
    if a.f_has_range() != b.f_has_range():
        return False

    # Check if both have ranges and if their lengths are different
    if a.f_has_range():
        if a.f_get_range_length() != b.f_get_range_length():
            return False

        # Check if items in ranges are of the same type and equal
        for myitem, bitem in zip(a.f_get_range(copy=False), b.f_get_range(copy=False)):
            if not a._values_of_same_type(myitem, bitem):
                return False
            if not a._equal_values(myitem, bitem):
                return False

    return True

