def kwargs_api_change(old_name, new_name=None):
    def wrapper(func):
        @functools.wraps(func)
        def new_func(*args, **kwargs):
            if old_name in kwargs:
                if new_name is None:
                    warning_string = f'Using deprecated keyword argument `{old_name}` in function `{func.__name__}`. This keyword is no longer supported, please don`t use it anymore.'
                else:
                    warning_string = f'Using deprecated keyword argument `{old_name}` in function `{func.__name__}`, please use keyword `{new_name}` instead.'
                warnings.warn(warning_string, category=DeprecationWarning)
                value = kwargs.pop(old_name)
                if new_name is not None:
                    kwargs[new_name] = value
            return func(*args, **kwargs)
        return new_func
    return wrapper

