def _tree_store_nodes_dfs(self, parent_traj_node, name, store_data, with_links, recursive, max_depth, current_depth, parent_hdf5_group):
    if max_depth is None:
        max_depth = float('inf')
    store_list = [(parent_traj_node, name, current_depth, parent_hdf5_group)]
    while store_list:
        parent_traj_node, name, current_depth, parent_hdf5_group = store_list.pop()
        if name in parent_traj_node._links:
            if with_links:
                self._tree_store_link(parent_traj_node, name, parent_hdf5_group)
            continue
        traj_node = parent_traj_node._children[name]
        if not hasattr(parent_hdf5_group, name):
            newly_created = True
            new_hdf5_group = self._hdf5file.create_group(where=parent_hdf5_group, name=name, filters=self._all_get_filters())
        else:
            newly_created = False
            new_hdf5_group = getattr(parent_hdf5_group, name)
        if traj_node.v_is_leaf:
            self._prm_store_parameter_or_result(traj_node, store_data=store_data, _hdf5_group=new_hdf5_group, _newly_created=newly_created)
        else:
            self._grp_store_group(traj_node, store_data=store_data, with_links=with_links, recursive=False, max_depth=max_depth, _hdf5_group=new_hdf5_group, _newly_created=newly_created)
        if recursive and current_depth < max_depth:
            for child in traj_node._children.keys():
                store_list.append((traj_node, child, current_depth + 1, new_hdf5_group))

