        if col == 'length':
            insert_dict['length'] = len(item)
        elif col == 'comment':
            comment = self._all_cut_string(item.v_comment.encode('utf-8'), pypetconstants.HDF5_STRCOL_MAX_COMMENT_LENGTH, self._logger)
            insert_dict['comment'] = comment
        elif col == 'location':
            insert_dict['location'] = item.v_location.encode('utf-8')
        elif col == 'name':
            name = item._name if not (item.v_is_root or item.v_is_run) else item._crun
            insert_dict['name'] = name.encode('utf-8')
        elif col == 'class_name':
            insert_dict['class_name'] = item.f_get_class_name().encode('utf-8')
        elif col == 'value':
