            insert_dict['value'] = value
        elif col == 'hexdigest':
            insert_dict['hexdigest'] = additional_info['hexdigest']
        elif col == 'idx':
            insert_dict['idx'] = item.v_idx
        elif col == 'time':
            insert_dict['time'] = item._time.encode('utf-8')
        elif col == 'timestamp':
            insert_dict['timestamp'] = item._timestamp
        elif col == 'range':
            third_length = pypetconstants.HDF5_STRCOL_MAX_RANGE_LENGTH // 3 + 10
