def _grp_store_group(self, traj_group, store_data=pypetconstants.STORE_DATA, with_links=True, recursive=False, max_depth=None, _hdf5_group=None, _newly_created=False):
    if store_data == pypetconstants.STORE_NOTHING:
        return
    elif store_data == pypetconstants.STORE_DATA_SKIPPING and traj_group._stored:
        self._logger.debug('Already found `%s` on disk I will not store it!' % traj_group.v_full_name)
    elif not recursive:
        if _hdf5_group is None:
            _hdf5_group, _newly_created = self._all_create_or_get_groups(traj_group.v_full_name)
        overwrite = store_data == pypetconstants.OVERWRITE_DATA
        if (traj_group.v_comment != '' and (HDF5StorageService.COMMENT not in _hdf5_group._v_attrs or overwrite)):
            setattr(_hdf5_group._v_attrs, HDF5StorageService.COMMENT, traj_group.v_comment)
        if (_newly_created or overwrite) and type(traj_group) not in (nn.NNGroupNode, nn.ConfigGroup, nn.ParameterGroup, nn.DerivedParameterGroup, nn.ResultGroup):
            setattr(_hdf5_group._v_attrs, HDF5StorageService.CLASS_NAME, traj_group.f_get_class_name())
        self._ann_store_annotations(traj_group, _hdf5_group, overwrite=overwrite)
        self._hdf5file.flush()
        traj_group._stored = True
        self._node_processing_timer.signal_update()
    if recursive:
        parent_traj_group = traj_group.f_get_parent()
        parent_hdf5_group = self._all_create_or_get_groups(parent_traj_group.v_full_name)[0]
        self._tree_store_nodes_dfs(parent_traj_group, traj_group.v_name, store_data=store_data, with_links=with_links, recursive=recursive, max_depth=max_depth, current_depth=0, parent_hdf5_group=parent_hdf5_group)

