def _prm_get_longest_stringsize(string_list):
    # Initialize the maximum length to 1
    maxlength = 1

    # Iterate through each item in the string_list
    for stringar in string_list:
        # Check if the item is a numpy array
        if isinstance(stringar, np.ndarray):
            # If the array has more than one dimension
            if stringar.ndim > 0:
                # Iterate through each element in the flattened array
                for string in stringar.ravel():
                    # Update the maximum length if the current string is longer
                    maxlength = max(len(string), maxlength)
            else:
                # Update the maximum length if the array is a 1D array
                maxlength = max(len(stringar.tolist()), maxlength)
        else:
            # Update the maximum length if the item is a string
            maxlength = max(len(stringar), maxlength)

    # Return the maximum length multiplied by 1.5 to allow for slightly larger strings later
    return int(maxlength * 1.5)

