def f_shrink(self, force=False):
    # Check if the trajectory is already stored and force is not True
    if self._stored and not force:
        raise TypeError('Your trajectory is already stored to disk or database, shrinking is not allowed.')

    # Unlock all explored parameters
    for param in self._explored_parameters.values():
        param.f_unlock()

    # Attempt to shrink each parameter
    for param in self._explored_parameters.values():
        try:
            param._shrink()
        except Exception as exc:
            self._logger.error(f'Could not shrink `{param.v_full_name}` because of: `{exc}`')

    # If successful, reset the explored parameters and run information
    self._explored_parameters = {}
    self._run_information = {}
    self._single_run_ids = {}
    self._add_run_info(0)
    self._test_run_addition(1)

