def _extract_subruns(self, traj, pre_run=False):
    """
    Extracts subruns from a trajectory based on their order annotations.

    Parameters:
    - traj: The trajectory object from which to extract subruns.
    - pre_run: A boolean indicating whether to extract pre-run subruns.

    Returns:
    - A list of subrun objects, sorted by their order.

    Raises:
    - RuntimeError: If a duration parameter has no order annotation or if there are duplicate orders.
    """
    if pre_run:
        durations_list = traj.f_get_all(self._pre_durations_group_name)
    else:
        durations_list = traj.f_get_all(self._durations_group_name)

    subruns = {}
    orders = []

    for durations in durations_list:
        for duration_param in durations.f_iter_leaves(with_links=False):
            if 'order' in duration_param.v_annotations:
                order = duration_param.v_annotations.order
            else:
                raise RuntimeError(f'Your duration parameter {duration_param.v_full_name} has no order. Please add an order in `v_annotations.order`.')

            if order in subruns:
                raise RuntimeError(f'Your durations must differ in their order, there are two with order {order}.')

            subruns[order] = duration_param
            orders.append(order)

    return [subruns[order] for order in sorted(orders)]

