        return

    self.authorization_code = request.json()['code']
    self.pin = request.json()['ecobeePin']
    logger.error(f'Please authorize your ecobee developer app with PIN code {self.pin}.\nGoto https://www.ecobee.com/consumerportal/index.html, click My Apps, Add application, Enter Pin and click Authorize.\nAfter authorizing, call request_tokens() method.')

