def get_status(options):
    payload = {
        "username": options.username,
        "password": options.password,
        "server": options.server,
        "port": options.port,
    }

    try:
        if options.server.startswith("/") and stat.S_ISSOCK(os.stat(options.server).st_mode):
            # Communicate with server via Unix socket
            try:
                import supervisor.xmlrpc
            except ImportError as error:
                sys.stderr.write(f"ERROR: Couldn't load module. {error}\n")
                sys.stderr.write("ERROR: Unix socket support not available! Please install nagios-check-supervisord with unix socket support: 'nagios-check-supervisord[unix-socket-support]' or install 'supervisor' separately.\n")
                sys.exit(-1)

            if all([options.username, options.password]):
                connection = xmlrpclib.ServerProxy(
                    "https://",
                    transport=supervisor.xmlrpc.SupervisorTransport(
                        options.username,
                        options.password,
                        serverurl=URI[URI_TPL_SOCKET].format(**payload)
                    )
                )
            else:
                connection = xmlrpclib.ServerProxy(
                    "https://",
                    transport=supervisor.xmlrpc.SupervisorTransport(
                        None,
                        None,
                        serverurl=URI[URI_TPL_SOCKET].format(**payload)
                    )
                )
        else:
            # Communicate with server via HTTP
            if all([options.username, options.password]):
                connection = xmlrpclib.Server(
                    URI[URI_TPL_HTTP_AUTH].format(**payload)
                )
            else:
                connection = xmlrpclib.Server(
                    URI[URI_TPL_HTTP].format(**payload)
                )

        return connection.supervisor.getAllProcessInfo()
    except Exception as error:
        if not options.quiet:
            sys.stdout.write(f"ERROR: Server communication problem. {error}\n")
        sys.exit(EXIT_CODES.get(options.network_errors_exit_code, EXIT_CODE_UNKNOWN))

