def create_output(data, options):
    # Initialize output dictionary
    output = {}

    # Determine programs to process
    programs = map(strip, options.programs.strip().split(",")) if options.programs else map(lambda x: x["name"], data)

    # Process each program
    for program in programs:
        try:
            # Find program data
            program_data = filter(lambda x: x["name"] == program, data)[0]
            # Update output with program details
            output.update({
                program: {
                    "name": program,
                    "template": STATE2TEMPLATE[program_data["statename"]],
                    "status": program_data["spawnerr"] if program_data["spawnerr"] else program_data["statename"],
                }
            })
        except IndexError:
            # Handle program not found
            output.update({
                program: {
                    "name": program,
                    "template": "unknown",
                    "status": "",
                }
            })

    # Determine main status
    statuses = [status[0] for status in sorted([(status, OUTPUT_TEMPLATES[status]["priority"]) for status in list(set([output[d]["template"] for d in output.keys()]))], key=lambda x: x[1])]
    status = statuses[0] if statuses else EXIT_CODE_OK

    # Create output text
    text = ", ".join([OUTPUT_TEMPLATES[output[program]["template"]]["text"].format(**output[program]) for program in sorted(output.keys(), key=lambda x: OUTPUT_TEMPLATES[x]["template"]["priority"])]) if statuses else "No program configured/found"

    # Determine exit code
    code = EXIT_CODES.get(status, EXIT_CODE_UNKNOWN)

    # Return full status string and exit code
    return "{status}: {output}\n".format(**{"status": status.upper(), "output": text}), code

