def get_supported_versions(self):
    """
    Returns a list of supported versions. If the `_versions` attribute is not set, it attempts to retrieve the version using the `send_apdu` method with the `INS_GET_VERSION` instruction. If the instruction is not supported (APDUError with code 0x6d00), it returns ['v0']. If any other error occurs, it returns an empty list.
    """
    if not hasattr(self, '_versions'):
        try:
            self._versions = [self.send_apdu(INS_GET_VERSION).decode()]
        except exc.APDUError as e:
            self._versions = ['v0'] if e.code == 0x6d00 else []
    return self._versions

