def register(devices, params, facet):
    # Attempt to open each device and remove any that fail to open
    devices = [device for device in devices if device.open()]

    # Prompt the user to touch the U2F device they wish to register
    sys.stderr.write('\nTouch the U2F device you wish to register...\n')

    # Continuously try to register with each device until successful or all devices are removed
    while devices:
        removed = []
        for device in devices:
            try:
                return u2f.register(device, params, facet)
            except exc.APDUError as e:
                if e.code == APDU_USE_NOT_SATISFIED:
                    pass
                else:
                    removed.append(device)
            except exc.DeviceError:
                removed.append(device)
        devices = [d for d in devices if d not in removed]
        for d in removed:
            d.close()
        time.sleep(0.25)

    # Close all remaining devices and exit with an error message
    for device in devices:
        device.close()
    sys.stderr.write('\nUnable to register with any U2F device.\n')
    sys.exit(1)

