def _get_email(self, email):
    # Check if the email is valid and contains an "@" symbol
    if not email or "@" not in email:
        return None

    # Check if the email is in the remapping dictionary
    if email in self.email_remapping.remap:
        return self.email_remapping.remap[email]

    # Split the email into prefix and domain
    prefix, domain = email.split("@", 2)

    # Check if the prefix is in the remapping dictionary
    if prefix in self.email_remapping.remap:
        return self.email_remapping.remap[prefix]

    # Check if the domain contains a "." and if VCS email domain should be ignored
    if "." not in domain or config.ignore_vcs_email_domain:
        return "%s@%s" % (prefix, config.email_domain_name)

    # Return the original email if none of the above conditions are met
    return email

