def parse_args_kwargs(parser, token):
    bits = token.contents.split(' ')
    if len(bits) <= 1:
        raise template.TemplateSyntaxError("'%s' takes at least one argument" % bits[0])

    if token.contents[13] == '"':
        end_quote = token.contents.index('"', 14) + 1
        args = [template.Variable(token.contents[13:end_quote])]
        kwargs_start = end_quote
    else:
        try:
            next_space = token.contents.index(' ', 14)
            kwargs_start = next_space + 1
        except ValueError:
            next_space = None
            kwargs_start = None
        args = [template.Variable(token.contents[13:next_space])]

    kwargs = {}
    kwargs_list = token.contents[kwargs_start:].split(',')
    for kwargs_item in kwargs_list:
        if '=' in kwargs_item:
            k, v = kwargs_item.split('=', 1)
            k = k.strip()
            kwargs[k] = template.Variable(v)

    return args, kwargs


**Summary:**
The function `parse_args_kwargs` takes a `parser` and a `token` as input. It splits the token's contents into bits and checks if there is at least one argument. If the first argument is enclosed in quotes, it extracts the quoted argument as an argument and sets the start of keyword arguments. If not, it finds the next space to determine the end of the arguments. It then parses any keyword arguments and returns a list of arguments and a dictionary of keyword arguments.

