def _assert_no_recur(node: Node) -> None:
    if node.op == NodeOp.RECUR:
        raise ParserException("recur must appear in tail position", form=node.form, lisp_ast=node)
    elif node.op in {NodeOp.FN, NodeOp.LOOP}:
        pass
    else:
