def __resolve_bare_symbol(ctx: ParserContext, form: sym.Symbol) -> Union[MaybeClass, VarRef]:
    assert form.ns is None  # Ensure the symbol has no namespace.
    v = ctx.current_ns.find(form)  # Look up the symbol in the current namespace.
    if v is not None:
        return VarRef(form=form, var=v, env=ctx.get_node_env())  # Return a VarRef if found.
    if "." in form.name:
        raise ParserException("symbol names may not contain the '.' operator", form=form)  # Raise an exception if the symbol name contains a '.'.
    munged = munge(form.name, allow_builtins=True)  # Munge the symbol name, allowing built-in names.
    if munged in vars(builtins):
        return MaybeClass(form=form, class_=munged, target=vars(builtins)[munged], env=ctx.get_node_env())  # Return a MaybeClass if the munged name is a built-in.
    assert munged not in vars(ctx.current_ns.module)  # Ensure the munged name is not a module variable.
    raise ParserException(f"unable to resolve symbol '{form}' in this context", form=form)  # Raise an exception if the symbol cannot be resolved.

