def _load_attr(name: str, ctx: ast.AST = ast.Load()) -> ast.Attribute:
    # Split the attribute name by dots to handle nested attributes
    attrs = name.split(".")

    def attr_node(node, idx):
        # If the index is out of bounds, set the context and return the node
        if idx >= len(attrs):
            node.ctx = ctx
            return node
        # Recursively create an attribute node for each part of the attribute
        return attr_node(
            ast.Attribute(
                value=node,
                attr=attrs[idx],
                ctx=ast.Load()
            ),
            idx + 1
        )

    # Start with the first part of the attribute and recursively build the full attribute node
    return attr_node(ast.Name(id=attrs[0], ctx=ast.Load()), 1)

