def parse_str_to_expression(fiql_str):
    # Initialize variables to keep track of the current state of the expression
    nesting_lvl = 0
    last_element = None
    expression = Expression()

    # Iterate over the parsed components of the FIQL string
    for (preamble, selector, comparison, argument) in iter_parse(fiql_str):
        if preamble:
            for char in preamble:
                if char == '(':
                    # Handle opening parenthesis
                    if isinstance(last_element, BaseExpression):
                        raise FiqlFormatException("%s can not be followed by %s" % (last_element.__class__, Expression))
                    expression = expression.create_nested_expression()
                    nesting_lvl += 1
                elif char == ')':
                    # Handle closing parenthesis
                    expression = expression.get_parent()
                    last_element = expression
                    nesting_lvl -= 1
                else:
                    # Handle operators
                    if not expression.has_constraint():
                        raise FiqlFormatException("%s proceeding initial %s" % (Operator, Constraint))
                    if isinstance(last_element, Operator):
                        raise FiqlFormatException("%s can not be followed by %s" % (Operator, Operator))
                    last_element = Operator(char)
                    expression = expression.add_operator(last_element)
        if selector:
            # Handle constraints
            if isinstance(last_element, BaseExpression):
                raise FiqlFormatException("%s can not be followed by %s" % (last_element.__class__, Constraint))
            last_element = Constraint(selector, comparison, argument)
            expression.add_element(last_element)

    # Validate the final state of the expression
    if nesting_lvl != 0:
        raise FiqlFormatException("At least one nested expression was not correctly closed")
    if not expression.has_constraint():
        raise FiqlFormatException("Parsed string '%s' contained no constraint" % fiql_str)

    return expression

