def robust_topological_sort(graph: Graph) -> list:
    # Asserts that the input graph has the correct argument types.
    assert check_argument_types()

    # Finds all strongly connected components in the graph.
    components = strongly_connected_components(graph)

    # Creates a dictionary to map each node to its strongly connected component.
    node_component = {}
    for component in components:
        for node in component:
            node_component[node] = component

    # Creates a dictionary to represent the graph in terms of its strongly connected components.
    component_graph = {}
    for component in components:
        component_graph[component] = []

    # Populates the component graph with edges between components.
    for node in graph:
        node_c = node_component[node]
        for successor in graph[node]:
            successor_c = node_component[successor]
            if node_c != successor_c:
                component_graph[node_c].append(successor_c)

    # Returns a topological sort of the component graph.
    return topological_sort(component_graph)

