def ops_to_words(item):
    # Define unsupported and supported operators
    unsupp_ops = ["~=", "==="]
    supp_ops = [">=", ">", "==", "<=", "<", "!="]

    # Split the input string by commas and sort in reverse order
    tokens = sorted(item.split(","), reverse=True)
    actual_tokens = []

    # Process each token to determine the operator
    for req in tokens:
        for op in unsupp_ops:
            if req.startswith(op):
                raise RuntimeError(f"Unsupported version specification: {op}")
        for op in supp_ops:
            if req.startswith(op):
                actual_tokens.append(op)
                break
        else:
            raise RuntimeError(f"Illegal comparison operator: {op}")

    # Check for multiple operators of the same type
    if len(list(set(actual_tokens))) != len(actual_tokens):
        raise RuntimeError("Multiple comparison operators of the same type")

    # Convert tokens to words based on the operator
    if "!=" in actual_tokens:
        return " and ".join([op_to_words(token) for token in tokens[:-1]]) + " " + op_to_words(tokens[-1])
    return " and ".join([op_to_words(token) for token in tokens])

