def _pair_delims(expr, ldelim="(", rdelim=")"):
    # Find the indices of left and right delimiters
    lindex = list(reversed([num for num, item in enumerate(expr) if item == ldelim]))
    rindex = [num for num, item in enumerate(expr) if item == rdelim]

    # Pair remaining delimiters
    return [(_next_rdelim(rindex, lpos), lpos) for lpos in lindex][::-1]

def _next_rdelim(rindex, lpos):
