def to_scientific_tuple(number):
    # Convert input to Decimal for precise calculations
    if not isinstance(number, str):
        number = str(number)

    # Handle zero and empty strings
    if number == "0" or not number.strip("0").strip("."):
        return ("0", 0)

    # Convert number to Decimal and extract components
    sign, digits, exp = Decimal(number).as_tuple()

    # Format the mantissa
    mant = "{sign}{itg}{frac}".format(
        sign="-" if sign else "",
        itg=digits[0],
        frac=".{frac}".format(frac="".join(str(num) for num in digits[1:])) if len(digits) > 1 else ""
    ).rstrip("0").rstrip(".")

    # Adjust exponent
    exp += len(digits) - 1

    # Return the mantissa and exponent as a tuple
    return (mant, exp)

