def _join_paragraphs(cls, lines, use_indent=False, leading_blanks=False, trailing_blanks=False):
    """
    Joins lines into paragraphs based on certain conditions.

    Parameters:
    cls (class): The class containing the method.
    lines (list): A list of lines to be joined into paragraphs.
    use_indent (bool): Whether to use indentation to determine paragraph boundaries.
    leading_blanks (bool): Whether to include leading blanks in the paragraphs.
    trailing_blanks (bool): Whether to include trailing blanks in the paragraphs.

    Returns:
    list: A list of paragraphs.
    """
    curr_para = []
    paragraphs = []

    for line in lines:
        if use_indent:
            if line.startswith(' '):
                curr_para.append(line.lstrip())
                continue
            elif line == '':
                continue
            else:
                if len(curr_para) > 0:
                    paragraphs.append(cls._join_paragraph(curr_para, leading_blanks, trailing_blanks))
                    curr_para = [line.lstrip()]
        else:
            if len(line) != 0:
                curr_para.append(line)
            else:
                paragraphs.append(cls._join_paragraph(curr_para, leading_blanks, trailing_blanks))
                curr_para = []

    # Finish the last paragraph if there is one
    if len(curr_para) > 0:
        paragraphs.append(cls._join_paragraph(curr_para, leading_blanks, trailing_blanks))

    return paragraphs

