                elif key == wx.WXK_UP:
                    y = (y - GRID_SIZE[1]) / GRID_SIZE[1] * GRID_SIZE[1]
                elif key == wx.WXK_DOWN:
                    y = (y + GRID_SIZE[1]) / GRID_SIZE[1] * GRID_SIZE[1]
            else:
                if key == wx.WXK_LEFT:
                    x = x - 1
                elif key == wx.WXK_RIGHT:
                    x = x + 1
                elif key == wx.WXK_UP:
                    y = y - 1
                elif key == wx.WXK_DOWN:
                    y = y + 1
            obj.pos = (x, y)
    elif key == wx.WXK_DELETE:
        self.delete(event)
    elif key == wx.WXK_INSERT:
        self.duplicate(event)
    else:
