def get_browser(browser_name, capabilities=None, **options):
    """
    Returns a WebDriver instance for the specified browser.

    Args:
        browser_name (str): The name of the browser to use.
        capabilities (dict, optional): A dictionary of desired capabilities.
        **options: Additional keyword arguments to pass to the WebDriver constructor.

    Returns:
        WebDriver: A WebDriver instance for the specified browser.

    Raises:
        ValueError: If the specified browser is not supported.
