    if browser_name == "chrome":
        return webdriver.Chrome(desired_capabilities=capabilities, **options)
    elif browser_name == "edge":
        return webdriver.Edge(desired_capabilities=capabilities, **options)
    elif browser_name in ["ff", "firefox"]:
        return webdriver.Firefox(desired_capabilities=capabilities, **options)
    elif browser_name in ["ie", "internet_explorer"]:
        return webdriver.Ie(desired_capabilities=capabilities, **options)
    elif browser_name == "phantomjs":
        return webdriver.PhantomJS(desired_capabilities=capabilities, **options)
    elif browser_name == "remote":
        return webdriver.Remote(desired_capabilities=capabilities, **options)
    elif browser_name == "safari":
