def synchronize(self, func=None, wait=None, errors=()):
    def decorator(func):
        @wraps(func)
        def outer(*args, **kwargs):
            seconds = wait if wait is not None else capybara.default_max_wait_time
            def inner():
                return func(*args, **kwargs)
            if self.session.synchronized:
                return inner()
            else:
                timer = Timer(seconds)
                self.session.synchronized = True
                try:
                    while True:
                        try:
                            return inner()
                        except Exception as e:
                            self.session.raise_server_error()
                            if not self._should_catch_error(e, errors):
                                raise
                            if timer.expired:
                                raise
                            if timer.stalled:
                                raise FrozenInTime("time appears to be frozen, Capybara does not work with libraries which freeze time, consider using time traveling instead")
                            if capybara.automatic_reload:
                                self.reload()
                finally:
                    self.session.synchronized = False
            return outer
    if func:
        return decorator(func)
    else:
        return decorator

