def build_url(base, additional_params=None):
    # Parse the base URL to extract its components
    url = urlparse.urlparse(base)
    query_params = {}
    # Update query parameters from the base URL
    query_params.update(urlparse.parse_qsl(url.query, True))

    # If additional parameters are provided, update the query parameters
    if additional_params is not None:
        query_params.update(additional_params)

    # Remove parameters with None values
    for k, v in additional_params.iteritems():
        if v is None:
            query_params.pop(k)

    # Reconstruct the URL with the updated query parameters
    return urlparse.urlunparse((url.scheme, url.netloc, url.path, url.params, urllib.urlencode(query_params), url.fragment))

