def resolve_neutral_types(storage, debug):
    # Iterate through each run in the storage
    for run in storage['runs']:
        start, length = run['start'], run['length']
        # Create a list of characters with start-of-run (sor) and end-of-run (eor) markers
        chars = [{'type': run['sor']}] + storage['chars'][start:start + length] + [{'type': run['eor']}]
        total_chars = len(chars)
        seq_start = None

        for idx in range(total_chars):
            _ch = chars[idx]
            if _ch['type'] in ('B', 'S', 'WS', 'ON'):
                # N1. Determine the direction of neutral characters based on surrounding strong text
                if seq_start is None:
                    seq_start = idx
                prev_bidi_type = chars[idx - 1]['type']
                next_bidi_type = chars[idx]['type']

                if prev_bidi_type in ('AN', 'EN'):
                    prev_bidi_type = 'R'
                if next_bidi_type in ('AN', 'EN'):
                    next_bidi_type = 'R'

                for seq_idx in range(seq_start, idx):
                    if prev_bidi_type == next_bidi_type:
                        chars[seq_idx]['type'] = prev_bidi_type
                    else:
                        # N2. Assign embedding direction based on the character's level
                        chars[seq_idx]['type'] = _embedding_direction(chars[seq_idx]['level'])
                seq_start = None

        if debug:
            debug_storage(storage)

