def _discover_gui():
    # Iterate over registered GUIs in reverse order
    for gui in reversed(pyblish.api.registered_guis()):
        try:
            # Attempt to import and show the GUI
            gui = __import__(gui).show
        except (ImportError, AttributeError):
            # Skip to the next GUI if import or attribute error occurs
            continue
        else:
            # Return the successfully imported and shown GUI
            return gui

