def delete(self, request, *args, **kwargs):
    # Extracts the authorization header from the request
    auth = get_authorization_header(request).split()

    # Checks if the authorization header is valid
    if not auth or auth[0].lower() != b'token':
        return response.Response(status=status.HTTP_400_BAD_REQUEST)

    # Validates the length of the authorization header
    if len(auth) == 1:
        msg = 'Invalid token header. No credentials provided.'
        return response.Response(msg, status=status.HTTP_400_BAD_REQUEST)
    elif len(auth) > 2:
        msg = 'Invalid token header. Token string should not contain spaces.'
        return response.Response(msg, status=status.HTTP_400_BAD_REQUEST)

    # Tries to retrieve the token from the database
    try:
        token = self.model.objects.get(key=auth[1])
    except self.model.DoesNotExist:
        pass
    else:
        # Deletes the token if it exists
        token.delete()
        # Sends a signal indicating that the user has logged out
        signals.user_logged_out.send(type(self), user=token.user, request=request)
        return response.Response(status=status.HTTP_204_NO_CONTENT)

