def _execute_get_url(self, request_url, append_sid=True):
    # Log the request URL
    self._debuglog(f"Requesting URL: '{request_url}'")

    # Append access token to the URL if required
    if append_sid:
        self._debuglog(f"Appending access_token (SID: {self.access_token}) to URL")
        request_url = f"{request_url}&_sid={self.access_token}"

    # Execute the GET request
    try:
        resp = self._session.get(request_url)
        self._debuglog(f"Request executed: {resp.status_code}")

        # Check the response status code
        if resp.status_code == 200:
            # Parse JSON data
            json_data = json.loads(resp.text)
            if json_data["success"]:
                self._debuglog("Successful returning data")
                self._debuglog(str(json_data))
                return json_data
            else:
                # Handle session errors
                if json_data["error"]["code"] in {105, 106, 107, 119}:
                    self._debuglog(f"Session error: {json_data['error']['code']}")
                    self._session_error = True
                else:
                    self._debuglog(f"Failed: {resp.text}")
        else:
            # Return None for 404 or 401 status codes
            return None
    except:
        return None

