def read_input_file(self, fn):
    # Construct the full path to the input file
    fnfull = os.path.realpath(os.path.join(self.tex_input_directory, fn))

    # Check if strict input mode is enabled
    if self.strict_input:
        # Ensure the file is within the mandated directory
        dirfull = os.path.realpath(self.tex_input_directory)
        if not fnfull.startswith(dirfull):
            logger.warning("Can't access path '%s' leading outside of mandated directory [strict input mode]", fn)
            return ''

    # Check if the file exists and append '.tex' or '.latex' extension if necessary
    if not os.path.exists(fnfull) and os.path.exists(fnfull + '.tex'):
        fnfull = fnfull + '.tex'
    elif not os.path.exists(fnfull) and os.path.exists(fnfull + '.latex'):
        fnfull = fnfull + '.latex'

    # Check if the file is a regular file
    if not os.path.isfile(fnfull):
        logger.warning(u"Error, file doesn't exist: '%s'", fn)
        return ''

    # Log the file being read
    logger.debug("Reading input file %r", fnfull)

    # Read and return the content of the file
    try:
        with open(fnfull) as f:
            return f.read()
    except IOError as e:
        logger.warning(u"Error, can't access '%s': %s", fn, e)
        return ''

