def utf8tolatex(s, non_ascii_only=False, brackets=True, substitute_bad_chars=False, fail_bad_chars=False):
    s = unicode(s)  # Ensure s is unicode
    s = unicodedata.normalize('NFC', s)
    if not s:
        return ""
    result = u""
    for ch in s:
        if non_ascii_only and ord(ch) < 127:
            result += ch
        else:
            lch = utf82latex.get(ord(ch), None)
            if lch is not None:
                result += ('{' + lch + '}' if brackets and lch[0:1] == '\\' else lch)
            elif (ord(ch) >= 32 and ord(ch) <= 127) or (ch in "\n\r\t"):
                result += ch
            else:
                msg = u"Character cannot be encoded into LaTeX: U+%04X - `%s'" % (ord(ch), ch)
                if fail_bad_chars:
                    raise ValueError(msg)
                log.warning(msg)
                if substitute_bad_chars:
                    result += r'{\bfseries ?}'
                else:
                    result += ch
    return result


**Summary:**
The function `utf8tolatex` converts a UTF-8 encoded string to a LaTeX string. It handles non-ASCII characters by converting them to their LaTeX equivalents, with options to include brackets around macros, substitute bad characters, or fail on bad characters. The function ensures that the input string is normalized to NFC form and processes each character accordingly.

