def _unascii(s):
    # Check if the string contains any escape sequences
    m = _U_ESCAPE.search(s)
    if not m:
        return s if PY2 else s.encode('utf-8')

    # Initialize chunks to accumulate processed parts of the string
    chunks = []
    pos = 0

    while m:
        start = m.start()
        end = m.end()
        g = m.group(1)

        if g is None:
            # Escaped backslash: pass it through
            chunks.append(s[pos:end])
        else:
            # Handle \uNNNN escape sequences
            c = int(g, 16)
            if c < 0x20:
                # Leave as a \uNNNN escape
                chunks.append(s[pos:end])
            else:
                if PY3:
                    # Handle surrogate pairs in Python 3
                    if c & 0xfc00 == 0xd800 and s[end:end + 2] == '\\u':
                        esc2 = s[end + 2:end + 6]
                        c2 = int(esc2, 16)
                        if c2 & 0xfc00 == 0xdc00:
                            c = 0x10000 + (((c - 0xd800) << 10) | (c2 - 0xdc00))
                        end += 6
                chunks.append(s[pos:start])
                chunks.append(unichr(c))

        pos = end
        m = _U_ESCAPE.search(s, pos)

    # Append any remaining part of the string
    chunks.append(s[pos:])

    # Join chunks and encode to UTF-8
    return (''.join(chunks)).encode("utf-8")

