def collate_data(in_dir, extension='.csv', out_dir=None):
    """
    This function collates files with a specified extension from a given directory into a new directory.

    Parameters:
    - in_dir (str): The input directory from which files will be copied.
    - extension (str): The file extension to filter files by (default is '.csv').
    - out_dir (str): The output directory where files will be copied. If not provided, it defaults to a directory named after the extension in the current working directory.

