def gen_keywords(*args: Union[ANSIColors, ANSIStyles], **kwargs: Union[ANSIColors, ANSIStyles]) -> tuple:
    fields = tuple()
    values = tuple()
    for tpl in args:
        fields += tpl._fields
        values += tpl
