def fuzzmatch(self, fuzzkey, multi=False):
    # Calculate the ratio of fuzzkey to each key in self.components
    keys, ratios = np.array([(f, seqm(None, fuzzkey, f).ratio()) for f in self.components.keys()]).T

    # Find the maximum ratio
    mratio = max(ratios)

    if multi:
        # Return all keys with the maximum ratio if multi is True
        return keys[ratios == mratio]
    else:
        # If there is only one key with the maximum ratio, return that key
        if sum(ratios == mratio) == 1:
            return keys[ratios == mratio][0]
        else:
            # Raise an error if multiple keys have the same maximum ratio
            raise ValueError(f"The filter key provided ('{fuzzkey}') matches two or more filter names equally well:\n{', '.join(keys[ratios == mratio])}\nPlease be more specific!")

