def split_header(s, get_header=True):
    # Splits the input string into header and description based on the presence of '#' or '=' characters.
    s = s.lstrip().rstrip()
    parts = s.splitlines()

    if parts[0].startswith('#'):
        if get_header:
            header = re.sub('#+\s*', '', parts.pop(0))
        if not parts:
            return header, ''
        else:
            header = ''
            rest = '\n'.join(parts).lstrip().split('\n\n')
            desc = rest[0].replace('\n', ' ')
            return header, desc
    else:
        if get_header:
            if parts[0].startswith(('=', '-')):
                parts = parts[1:]
                header = parts.pop(0)
                if parts and parts[0].startswith(('=', '-')):
                    parts.pop(0)
                if not parts:
                    return header, ''
