def tail(self, lines=10):
    self.file.seek(0, SEEK_END)
    for _ in range(lines):
        if self.seek_previous_line() == -1:
            break
    data = self.file.read()
    for t in self.LINE_TERMINATORS:
        if data.endswith(t):
            data = data[:-len(t)]
            break
    if data:
        return self.splitlines(data)
    else:
        return []

