def update_status(self):
    old_status = self.invoice.status
    total_paid = self.invoice.total_payments()
    num_payments = commerce.PaymentBase.objects.filter(invoice=self.invoice).count()
    remainder = self.invoice.value - total_paid

    if old_status == commerce.Invoice.STATUS_UNPAID:
        if remainder <= 0:
            self._mark_paid()
    elif total_paid == 0 and num_payments > 0:
        self._mark_void()
    elif old_status == commerce.Invoice.STATUS_PAID:
        if remainder > 0:
            self._mark_refunded()
    elif old_status == commerce.Invoice.STATUS_REFUNDED or old_status == commerce.Invoice.STATUS_VOID:
        pass

    residual = 0
    if self.invoice.is_paid:
        if remainder < 0:
            residual = 0 - remainder
    elif self.invoice.is_void or self.invoice.is_refunded:
        residual = total_paid

    if residual != 0:
        CreditNoteController.generate_from_invoice(self.invoice, residual)

    self.email_on_invoice_change(self.invoice, old_status, self.invoice.status)

