def apply(self, key, value, prompt=None, on_load=lambda a: a, on_save=lambda a: a):
    # Reset value if flag exists without value
    if value == '':
        value = None

    # If key exists and value is explicitly set from args
    if key and self.data.has_key(key):
        del self.data[key]

    if value is not None:
        value = on_load(value)

    if key:
        self.data[key] = on_save(value)
        return value

    # If key does not exist or value is None
    if not key or not self.has_key(key):
        if callable(prompt):
            value = prompt()
        elif prompt is not None:
            value = raw_input(prompt + ": ")

        if value is None:
            if self.data.has_key(key):
                del self.data[key]
            return None

        self.data[key] = on_save(value)
        return value

    return on_load(self.data[key])

