def transport_task(func):
    def wrapped_func(*args, **kwargs):
        tries = 0
        while True:
            try:
                return func(*args, **kwargs)
            except (asana_errors.InvalidRequestError, asana_errors.NotFoundError) as exc:
                logging.warn("warning: invalid request: %r", exc)
            except asana_errors.ForbiddenError as exc:
                logging.warn("forbidden error: %r", exc)
            except asana_errors.NotFoundError as exc:
                logging.warn("not found error: %r", exc)
            return None
            except asana_errors.RetryableAsanaError as retry_exc:
                tries += 1
                logging.warn("retry exception %r on try %d", retry_exc, tries)
                if tries >= 3:
                    raise
            except Exception as exc:
                logging.exception("Exception in transport.")
                return
    return wrapped_func

