def get_version(self) -> str:
    try:
        with open(self.file_path, 'r') as f:
            lines = f.readlines()
    except Exception as e:
        return str(e)

    result = ''
    for line in lines:
        if self.magic_line in line:
            start = len(self.magic_line)
            end = len(line) - self.strip_end_chars
            result = line[start:end]
            break

