def message_loop(self, t_q, r_q):
    t_msg = {}
    while t_msg.get("state", "") != "__DIE__":
        try:
            t_msg = t_q.get(True, self.cycle_sleep)  # Poll blocking
            self.task = t_msg.get("task", "")
            if self.task != "":
                self.task.task_start = time.time()  # Start the timer
                self.r_q_send({"w_id": self.w_id, "task": self.task, "state": "__ACK__"})  # Send ACK
                self.cycle_sleep = self.task.worker_loop_delay  # Update sleep time
                self.task.result = self.task.run()  # Run the task
                self.task.task_stop = time.time()  # End the timer
                self.r_q_send({"w_id": self.w_id, "task": self.task, "state": "__FINISHED__"})  # Ack work finished
                self.task = None
        except Empty:
            pass
        except Full:
            time.sleep(0.1)
        except:
            if self.task is not None:
                self.task.task_stop = time.time()  # End the timer
            tb_str = "".join(tb.format_exception(*sys.exc_info()))  # Handle all other errors
            self.r_q_send({"w_id": self.w_id, "task": self.task, "error": tb_str, "state": "__ERROR__"})
    return

