def include_(parser, token):
    bits = token.split_contents()
    dynamic = False
    if len(bits) >= 2:
        dynamic = '{{' in bits[1]
    if dynamic:
        fallback = None
        bits_new = []
        for bit in bits:
            if fallback is True:
                fallback = bit
                continue
            if bit == 'fallback':
                fallback = True
            else:
                bits_new.append(bit)
        if fallback:
            fallback = parser.compile_filter(construct_relative_path_(parser, fallback))
        token.contents = ' '.join(bits_new)
        token.contents = token.contents.replace('include_', 'include')
        include_node = do_include(parser, token)
        if dynamic:
            include_node = DynamicIncludeNode(include_node.template, extra_context=include_node.extra_context, isolated_context=include_node.isolated_context, fallback=fallback or None)
    return include_node

