def sync(self):
    logging.debug("Logger: Syncing...")
    failed = False
    try:
        cdb = self.connectordb
        cdb.ping()
        with self.synclock:
            c = self.database.cursor()
            for stream in self.streams:
                s = cdb[stream]
                c.execute("SELECT * FROM cache WHERE stream=? ORDER BY timestamp ASC;", (stream,))
                datapointArray = []
                for dp in c.fetchall():
                    datapointArray.append({"t": dp[1], "d": json.loads(dp[2])})

                if len(s) > 0:
                    newtime = s[-1]["t"]
                    while len(datapointArray) > 0 and datapointArray[0]["t"] < newtime:
                        logging.debug("Datapoint exists with older timestamp. Removing the datapoint.")
                        datapointArray = datapointArray[1:]

                if len(datapointArray) > 0:
                    logging.debug("%s: syncing %i datapoints" % (stream, len(datapointArray)))

                while len(datapointArray) > DATAPOINT_INSERT_LIMIT:
                    s.insert_array(datapointArray[:DATAPOINT_INSERT_LIMIT])
                    datapointArray = datapointArray[DATAPOINT_INSERT_LIMIT:]

                if len(datapointArray) > 0:
                    c.execute("DELETE FROM cache WHERE stream=? AND timestamp <?", (stream, datapointArray[0]["t"]))
                    s.insert_array(datapointArray)
                    c.execute("DELETE FROM cache WHERE stream=? AND timestamp <=?", (stream, datapointArray[-1]["t"]))

                self.lastsynctime = time.time()
                if self.onsync is not None:
                    self.onsync()
    except Exception as e:
        failed = True
        reraise = self.syncraise
        if self.onsyncfail is not None:
            reraise = self.onsyncfail(e)
        if reraise:
            raise

