def __on_message(self, ws, msg):
    msg = json.loads(msg)
    logging.debug("ConnectorDB:WS: Msg '%s'", msg["stream"])
    stream_key = msg["stream"] + ":" if "transform" in msg else stream_key
    self.subscription_lock.acquire()
    if stream_key in self.subscriptions:
        subscription_function = self.subscriptions[stream_key]
        self.subscription_lock.release()
        fresult = subscription_function(msg["stream"], msg["data"])
        if fresult is True:
            fresult = msg["data"]
        if fresult is not False and fresult is not None and msg["stream"].endswith("/downlink") and msg["stream"].count("/") == 3:
            self.insert(msg["stream"][:-9], fresult)
        else:
            self.subscription_lock.release()
    else:
        logging.warn("ConnectorDB:WS: Msg '%s' not subscribed! Subscriptions: %s", msg["stream"], list(self.subscriptions.keys()))

