def get_annotated_lines(self):
    # Create a list of Line objects with line numbers and code
    lines = [Line(idx + 1, x) for idx, x in enumerate(self.sourcelines)]

    # Find the function definition line
    if hasattr(self.code, 'co_firstlineno'):
        lineno = self.code.co_firstlineno - 1
        while lineno > 0:
            if _funcdef_re.match(lines[lineno].code):
                break
            lineno -= 1

    # Determine the offset of the function body
    try:
        offset = len(inspect.getblock([x.code + '\n' for x in lines[lineno:]]))
    except TokenError:
        offset = 0

    # Mark lines within the function body as in the frame
    for line in lines[lineno:lineno + offset]:
        line.in_frame = True

    # Mark the current line
    try:
        lines[self.lineno - 1].current = True
    except IndexError:
        pass

    return lines

