def configure_handler(self, config):
    # Extract and validate formatter
    formatter = config.pop('formatter', None)
    if formatter:
        try:
            formatter = self.config['formatters'][formatter]
        except StandardError as e:
            raise ValueError(f'Unable to set formatter {formatter}: {e}')

    # Extract and validate level
    level = config.pop('level', None)

    # Extract and validate filters
    filters = config.pop('filters', None)

    # Handle callable configuration
    if '()' in config:
        c = config.pop('()')
        if not callable(c):
            if hasattr(types, 'ClassType') and type(c) != types.ClassType:
                c = self.resolve(c)
        factory = c
    else:
        klass = self.resolve(config.pop('class'))

    # Handle special cases for handler classes
    if issubclass(klass, logging.handlers.MemoryHandler) and 'target' in config:
        try:
            config['target'] = self.config['handlers'][config['target']]
        except StandardError as e:
            raise ValueError(f'Unable to set target handler {config["target"]}: {e}')
    elif issubclass(klass, logging.handlers.SMTPHandler) and 'mailhost' in config:
        config['mailhost'] = self.as_tuple(config['mailhost'])
    elif issubclass(klass, logging.handlers.SysLogHandler) and 'address' in config:
        config['address'] = self.as_tuple(config['address'])

    # Create handler instance
    factory = klass
    kwargs = {k: config[k] for k in config if valid_ident(k)}
    try:
        result = factory(**kwargs)
    except TypeError as te:
        if "'stream'" not in str(te):
            raise
        kwargs['strm'] = kwargs.pop('stream')
        result = factory(**kwargs)

    # Set formatter, level, and filters
    if formatter:
        result.setFormatter(formatter)
    if level is not None:
        result.setLevel(_checkLevel(level))
    if filters:
        self.add_filters(result, filters)

    return result

