def handle_http_exception(self, e):
    # Retrieve error handlers for the current blueprint
    handlers = self.error_handler_spec.get(request.blueprint)

    # If the exception does not have an error code, return it unchanged
    if e.code is None:
        return e

    # Check if there are handlers for the specific error code
    if handlers and e.code in handlers:
        handler = handlers[e.code]
    else:
        # If no specific handler, use the default handler
        handler = self.error_handler_spec[None].get(e.code)

    # If no handler is found, return the original exception
    if handler is None:
        return e

    # Call the handler with the exception and return the result
    return handler(e)

