def get_wsgi_headers(self, environ):
    headers = Headers(self.headers)
    location = None
    content_location = None
    content_length = None
    status = self.status_code

    # Iterate over headers to find specific values
    for key, value in headers:
        ikey = key.lower()
        if ikey == u'location':
            location = value
        elif ikey == u'content-location':
            content_location = value
        elif ikey == u'content-length':
            content_length = value

    # Ensure location header is an absolute URL
    if location is not None:
        old_location = location
        if isinstance(location, text_type):
            location = iri_to_uri(location, safe_conversion=True)
        if self.autocorrect_location_header:
            current_url = get_current_url(environ, root_only=True)
            if isinstance(current_url, text_type):
                current_url = iri_to_uri(current_url)
            location = url_join(current_url, location)
        if location != old_location:
            headers['Location'] = location

    # Ensure content location is a URL
    if content_location is not None and isinstance(content_location, text_type):
        headers['Content-Location'] = iri_to_uri(content_location)

    # Remove entity headers and set content length to zero if needed
    if 100 <= status < 200 or status == 204:
        headers['Content-Length'] = content_length = u'0'
    elif status == 304:
        remove_entity_headers(headers)

    # Automatically set content length if possible
    if self.automatically_set_content_length and self.is_sequence and content_length is None and status != 304:
        try:
            content_length = sum(len(to_bytes(x, 'ascii')) for x in self.response)
        except UnicodeError:
            pass
    else:
        headers['Content-Length'] = str(content_length)

    return headers

