    var_names = []
    discarded_names = []
    for name in node.names:
        if isinstance(name, tuple):
            name, alias = name
        else:
            alias = name
        self.writeline('l_%s = getattr(included_template, %r, missing)' % (alias, name))
        self.writeline('if l_%s is missing:' % alias)
