        self.outdent()
        if frame.toplevel:
            var_names.append(alias)
        if not alias.startswith('_'):
            discarded_names.append(alias)
        frame.assigned_names.add(alias)
    if var_names:
        if len(var_names) == 1:
            name = var_names[0]
            self.writeline('context.vars[%r] = l_%s' % (name, name))
        else:
            self.writeline('context.vars.update({%s})' % ', '.join('%r: l_%s' % (name, name) for name in var_names))
    if discarded_names:
        if len(discarded_names) == 1:
            self.writeline('context.exported_vars.discard(%r)' % discarded_names[0])
        else:
            self.writeline('context.exported_vars.difference_update((%s))' % ', '.join(imap(repr, discarded_names)))

