def make_wheelfile_inner(base_name, base_dir='.'):
    zip_filename = base_name + ".whl"
    log.info("creating '%s' and adding '%s' to it", zip_filename, base_dir)
    zip = zipfile.ZipFile(open(zip_filename, "wb+"), "w", compression=zipfile.ZIP_DEFLATED)
    score = {'WHEEL': 1, 'METADATA': 2, 'RECORD': 3}
    deferred = []

    def writefile(path):
        zip.write(path, path)
        log.info("adding '%s'" % path)

    for dirpath, dirnames, filenames in os.walk(base_dir):
        for name in filenames:
            path = os.path.normpath(os.path.join(dirpath, name))
            if os.path.isfile(path):
                if dirpath.endswith('.dist-info'):
                    deferred.append((score.get(name, 0), path))
                else:
                    writefile(path)

    deferred.sort()
    for score, path in deferred:
        writefile(path)

    zip.close()
    return zip_filename


**Summary:**
The function `make_wheelfile_inner` creates a wheel file (`.whl`) from a specified directory. It initializes a zip file with the given base name and walks through the directory to add files to the zip. Files in directories ending with `.dist-info` are deferred and added later to ensure they are placed correctly in the wheel file structure. The function logs the creation and addition of files, and finally closes the zip file, returning the name of the created wheel file.

