def lookup(self, ResponseGroup="Large", **kwargs):
    # Calls the ItemLookup API with the specified ResponseGroup and additional keyword arguments.
    response = self.api.ItemLookup(ResponseGroup=ResponseGroup, **kwargs)

    # Parses the XML response into an objectified tree.
    root = objectify.fromstring(response)

    # Checks if the request was valid. If not, raises a LookupException with the error code and message.
    if root.Items.Request.IsValid == 'False':
        code = root.Items.Request.Errors.Error.Code
        msg = root.Items.Request.Errors.Error.Message
        raise LookupException(f"Amazon Product Lookup Error: '{code}', '{msg}'")

    # Checks if any items were found. If not, raises an AsinNotFound exception with the XML response.
    if not hasattr(root.Items, 'Item'):
        raise AsinNotFound(f"ASIN(s) not found: '{etree.tostring(root, pretty_print=True)}'")

    # If multiple items are found, returns a list of AmazonProduct objects.
    if len(root.Items.Item) > 1:
        return [AmazonProduct(item, self.aws_associate_tag, self, region=self.region) for item in root.Items.Item]
    else:
        # If only one item is found, returns a single AmazonProduct object.
        return AmazonProduct(root.Items.Item, self.aws_associate_tag, self, region=self.region)

