def do_sort(environment, value, reverse=False, case_sensitive=False, attribute=None):
    """
    Sorts the given value based on the specified attributes and options.

    Parameters:
    - environment: The environment in which the sorting is performed.
    - value: The list or iterable to be sorted.
    - reverse: If True, the list is sorted in descending order. Default is False.
    - case_sensitive: If False, the sorting is case-insensitive. Default is False.
    - attribute: The attribute to sort by. If None, the items themselves are sorted.

    Returns:
    - A new list containing the sorted items.
    """
    if not case_sensitive:
        def sort_func(item):
            if isinstance(item, str):
                return item.lower()
            return item
    else:
        sort_func = None

    if attribute is not None:
        getter = make_attrgetter(environment, attribute)
        def sort_func(item, processor=sort_func or (lambda x: x)):
            return processor(getter(item))

    return sorted(value, key=sort_func, reverse=reverse)

