def constant_time_compare(val1, val2):
    # Check if a built-in constant-time comparison function is available
    if _builtin_constant_time_compare is not None:
        return _builtin_constant_time_compare(val1, val2)

    # Compare lengths of the two values
    len_eq = len(val1) == len(val2)

    # Initialize result based on length comparison
    if len_eq:
        result = 0
        left = val1
    else:
        result = 1
        left = val2

    # Perform constant-time comparison of bytes
    for x, y in zip(bytearray(left), bytearray(val2)):
        result |= x ^ y

    # Return True if the comparison is equal, False otherwise
    return result == 0

