def select_content_type(requested, available):
    """
    Selects the most appropriate content type from the available options based on the requested content types.

    Parameters:
    requested (list): A list of requested content types.
    available (list): A list of available content types.

    Returns:
    tuple: The most appropriate content type and its corresponding pattern.

    Raises:
    errors.NoMatch: If no matching content type is found.
    """
    class Match(object):
        """
        A class to represent a match between a candidate and a pattern.

        Attributes:
        candidate (object): The candidate content type.
        pattern (object): The pattern content type.
        match_type (int): The type of match (WILDCARD, PARTIAL, FULL_TYPE).
        parameter_distance (int): The distance between the candidate and pattern parameters.
        """
        WILDCARD, PARTIAL, FULL_TYPE = 2, 1, 0

        def __init__(self, candidate, pattern):
            self.candidate = candidate
            self.pattern = pattern
            if pattern.content_type == pattern.content_subtype == '*':
                self.match_type = self.WILDCARD
            elif pattern.content_subtype == '*':
                self.match_type = self.PARTIAL
            else:
                self.match_type = self.FULL_TYPE
            self.parameter_distance = len(candidate.parameters)
            for key, value in candidate.parameters.items():
                if key in pattern.parameters:
                    if pattern.parameters[key] == value:
                        self.parameter_distance -= 1
                    else:
                        self.parameter_distance += 1

    def extract_quality(obj):
        return getattr(obj, 'quality', 1.0)

    matches = []
    for pattern in sorted(requested, key=extract_quality, reverse=True):
        for candidate in sorted(available):
            if _content_type_matches(candidate, pattern):
                if candidate == pattern:
                    # exact match!!!
                    if extract_quality(pattern) == 0.0:
                        raise errors.NoMatch  # quality of 0 means NO
                    return candidate, pattern
                matches.append(Match(candidate, pattern))

    if not matches:
        raise errors.NoMatch

    matches = sorted(matches, key=attrgetter('match_type', 'parameter_distance'))
    return matches[0].candidate, matches[0].pattern

