def split_line(line, min_line_length=30, max_line_length=100):
    # If the line is within the max length, no need to split
    if len(line) <= max_line_length:
        return [line]

    # Determine the indentation of the line
    indent = 0
    while line[indent] == ' ' and indent < len(line):
        indent += 1

    # Try to find a split point starting from max_line_length and moving backwards
    i = max_line_length
    split_point = None
    while i > min_line_length:
        if line[i] == ' ':
            split_point = i
            break
        i -= 1

    # If no split point is found, search beyond the end of the line
    if split_point is None:
        i = max_line_length + 1
        while i < len(line):
            if line[i] == ' ':
                split_point = i
                break
            i += 1

    # If no split point is found, return the original line
    if split_point is None:
        return [line]

    # Split the line and recursively process the second part
    line1 = line[:split_point]
    line2 = ' ' * indent + line[split_point + 1:]
    return [line1] + split_line(line2, min_line_length, max_line_length)

