def consistency(self, desired_version=None, include_package=False, strictness=None):
    # Determine the keys to check
    keys_to_check = list(self.versions.keys())
    if not include_package and 'package' in keys_to_check:
        keys_to_check.remove('package')

    # Determine the desired version
    if desired_version is None:
        try:
            desired_version = self.versions['setup.py']
        except KeyError:
            desired_version = self.versions[keys_to_check[0]]

    # Determine the strictness level
    if strictness is None:
        strictness = self.strictness

    # Get the desired version object
    desired = self._version(desired_version, strictness)

    # Check each key's version against the desired version
    error_keys = []
    for key in keys_to_check:
        test = self._version(self.versions[key], strictness)
        if test != desired:
            error_keys.append(key)

    # Create the error message
    msg = ""
    for key in error_keys:
        msg += "Error: desired {d} != {v} ({k})\n".format(d=str(desired), v=str(self.versions[key]), k=str(key))

    return msg

