def add_months_to_date(months, date):
    month = date.month
    new_month = month + months
    years = 0

    # Adjust new_month and years if it goes below 1 or above 12
    while new_month < 1:
        new_month += 12
        years -= 1
    while new_month > 12:
        new_month -= 12
        years += 1

    # Calculate the new year
    year = date.year + years

    try:
        # Try to return the date with the new month and original day
        return datetime.date(year, new_month, date.day)
    except ValueError:
        # If the day is invalid (e.g., 30th March + 1 month = 30th February), adjust accordingly
        if months > 0:
            # Adding months, use the first day of the next month
            new_month += 1
            if new_month > 12:
                new_month -= 12
                year += 1
            return datetime.datetime(year, new_month, 1)
        else:
            # Subtracting months, use the last day of the same month
            new_day = calendar.monthrange(year, new_month)[1]
            return datetime.datetime(year, new_month, new_day)

