def _parse_parameter_list(parameter_list, normalized_parameter_values=_DEF_PARAM_VALUE, normalize_parameter_names=False, normalize_parameter_values=True):
    if normalized_parameter_values is not _DEF_PARAM_VALUE:
        warnings.warn('normalized_parameter_values keyword to _parse_parameter_list is deprecated, use normalize_parameter_values instead', DeprecationWarning)
        normalize_parameter_values = normalized_parameter_values

    parameters = []
    for param in parameter_list:
