def get_value(self, key, default={}, nested=True, decrypt=True):
    # Strip leading whitespace from the key
    key = key.lstrip()
    # Remove trailing dot if present
    if key.endswith("."):
        key = key[:-1]
    # If nested is True, split the key by dots and traverse the settings dictionary
    if nested:
        path = key.split(".")
        curr = self.settings
        for p in path[:-1]:
            curr = curr.get(p, {})
        try:
            value = curr[path[-1]]
        except KeyError:
            return default
        # Decrypt the value if decrypt is True
        if decrypt:
            value = self.decrypt(value, path)
        return value
    # If nested is False, directly get the value from the settings dictionary
    else:
        return self.settings.get(key, default)

