def run(query, params=None, config=None, conn=None, **kwargs):
    # Set default parameters if not provided
    if params is None:
        params = {}
    if conn is None:
        conn = Connection.get(DEFAULT_CONFIGURABLE["uri"])
    elif isinstance(conn, string_types):
