def zip_with_index(rdd):
    # Determine the number of partitions in the RDD
    if rdd.getNumPartitions() > 1:
        # Calculate the number of elements in each partition
        nums = rdd.mapPartitions(lambda it: [sum(1 for _ in it)]).collect()
        count = sum(nums)
        # Calculate the starting index for each partition
        starts = [0]
        for i in range(len(nums) - 1):
            starts.append(starts[-1] + nums[i])
    else:
        count = rdd.count()
        starts = [0]

    # Define a function to map each element with its index
    def func(k, it):
        for i, v in enumerate(it, starts[k]):
            yield v, i

    # Apply the function to each partition with its index
    return count, rdd.mapPartitionsWithIndex(func)

