def init(dist='dist', minver=None, maxver=None, use_markdown_readme=True, use_stdeb=False, use_distribute=False):
    # Check Python version range
    if minver is not None and maxver is not None:
        import sys
        if not minver <= sys.version < (maxver or 'Any'):
            sys.stderr.write(f'{sys.argv[0]}: requires python version in <{minver or "any"}, {maxver or "any"}), not {sys.version.split()[0]}\n')
            sys.exit(1)

    # Use distribute if specified
    if use_distribute:
        from distribute_setup import use_setuptools
        use_setuptools(to_dir=dist)
        from setuptools import setup
    else:
        try:
            from setuptools import setup
        except ImportError:
            from distutils.core import setup

    # Add README.md to sdist if specified
    if use_markdown_readme:
        try:
            import setuptools.command.sdist
            setuptools.command.sdist.READMES = tuple(list(getattr(setuptools.command.sdist, 'READMES', ())) + ['README.md'])
        except ImportError:
            pass

    # Import stdeb if specified and on a Debian system
    if use_stdeb:
        import platform
        if 'debian' in platform.dist():
            try:
                import stdeb
            except ImportError:
                pass

    return setup

