def ddp_frames_from_message(self, message):
    # Attempt to parse the message as EJSON
    try:
        msgs = ejson.loads(message)
    except ValueError:
        self.reply('error', error=400, reason='Data is not valid EJSON')
        raise StopIteration

    # Check if the parsed message is a list
    if not isinstance(msgs, list):
        self.reply('error', error=400, reason='Invalid EJSON messages')
        raise StopIteration

    # Process individual messages
    while msgs:
        # Pop a raw message from the list
        raw = msgs.pop(0)

        # Attempt to parse the message payload as EJSON
        try:
            data = ejson.loads(raw)
        except (TypeError, ValueError):
            data = None

        # Check if the parsed data is a dictionary
        if not isinstance(data, dict):
            self.reply('error', error=400, reason='Invalid SockJS DDP payload', offendingMessage=raw)
            yield data

        # Yield to other greenlets before processing the next message
        if msgs:
            gevent.sleep()

