def dispose(json_str):
    result_str = list(json_str)
    escaped = False
    normal = True
    sl_comment = False
    ml_comment = False
    quoted = False
    a_step_from_comment = False
    a_step_from_comment_away = False
    former_index = None

    for index, char in enumerate(json_str):
        if escaped:
            escaped = False
            continue
        if a_step_from_comment:
            if char != '/' and char != '*':
                a_step_from_comment = False
                normal = True
                continue
        if a_step_from_comment_away:
            if char != '/':
                a_step_from_comment_away = False
            if char == '"':
                if normal and not escaped:
                    quoted = True
                    normal = False
                elif quoted and not escaped:
                    quoted = False
                    normal = True
                elif char == '\\':
                    escaped = True
                elif char == '/':
                    if a_step_from_comment:
                        a_step_from_comment = False
                        sl_comment = True
                        normal = False
                        former_index = index - 1
                    elif a_step_from_comment_away:
                        a_step_from_comment_away = False
                        normal = True
                        ml_comment = False
                        for i in range(former_index, index + 1):
                            result_str[i] = ""
                elif normal:
