def determine_molecule_numbers(total, molecules, absolute, relative):
    # Calculate the total weight of relative numbers
    weight = sum(relative)

    # If there are no absolute numbers, calculate the numbers based on relative proportions
    if not any(absolute):
        numbers = [int(total * i / weight) for i in relative]
    # If there are both absolute and relative numbers, calculate the remaining numbers based on relative proportions
    elif any(relative):
        rest = total - sum(absolute)
        numbers = [int(rest * i / weight) if i else j for i, j in zip(relative, absolute)]
    # If there are only absolute numbers, return the absolute numbers
    else:
        numbers = absolute

    # Return a list of tuples containing molecule names and their corresponding numbers
    return list(zip(molecules, numbers))

