def RegisterTXXXKey(cls, key, desc):
    frameid = "TXXX:" + desc

    def getter(id3, key):
        return list(id3[frameid])

    def setter(id3, key, value):
        try:
            frame = id3[frameid]
        except KeyError:
            enc = 0  # Store 8859-1 if we can, per MusicBrainz spec.
            try:
                for v in value:
                    v.encode('latin_1')
            except UnicodeError:
                enc = 3
            id3.add(mutagen.id3.TXXX(encoding=enc, text=value, desc=desc))
        else:
            frame.text = value

    def deleter(id3, key):
        del (id3[frameid])

    cls.RegisterKey(key, getter, setter, deleter)

