def get_generator(self, path, *args, **kwargs):
    q = self.get_queue(path, *args, **kwargs)
    try:
        # This generator implements a standard access pattern for the direct access queue.
        for guard in q.iter():
            with guard as batch:
                batch_copy = batch.copy()
                for row in batch_copy:
                    yield row
        last_batch = self.get_remainder(path, q.block_size)
        for row in last_batch:
            yield row
    finally:
        q.close()

