def until_condition(self, condition, condition_description):
    end_time = time.time() + self._timeout
    count = 1
    while True:
        try:
            if not callable(condition):
                raise TypeError("condition is not callable")
            value = condition()
            if isinstance(value, bool) and value is not False:
                return value
            elif value is not None:
                return value
            else:
                logger.debug("#" + str(count) + " - wait until " + condition_description)
        except self._ignored_exceptions as ex:
            logger.debug("Captured {0} : {1}".format(str(ex.__class__).replace("<type '", "").replace("'>", ""), str(ex)))
        time.sleep(self._poll)
        count += 1
        if time.time() > end_time:
            break
    raise TimeoutException(msg="condition <" + condition_description + "> was not true after " + str(self._timeout) + " seconds.")

