    end_time = time.time() + self._timeout
    count = 1
    missing_traits_descriptions = None
    while True:
        missing_traits_descriptions = []
        try:
            missing_traits_descriptions = element_with_traits.evaluate_traits()
            if len(missing_traits_descriptions) == 0:
                return True
            else:
                logger.debug(f"#{count} - wait until all traits are present: <{'> <'.join(missing_traits_descriptions)}>")

        except self._ignored_exceptions as ex:
            logger.debug(f"Captured {ex.__class__.__name__}: {ex}")
            pass

        time.sleep(self._poll)
        count += 1
        if time.time() > end_time:
            break

    raise TimeoutException(f"conditions <{'> <'.join(missing_traits_descriptions)}> not true after {self._timeout} seconds.")

