def to_openmath(self, obj):
    # Iterate over conversion functions in reverse order
    for cl, conv in reversed(self._conv_to_om):
        # Check if the class is None or if the object is an instance of the class
        if cl is None or isinstance(obj, cl):
            try:
                # Attempt to convert the object using the conversion function
                return conv(obj)
            except CannotConvertError:
                # Continue to the next conversion function if conversion fails
                continue
    # Check if the object has a __openmath__ method
    if hasattr(obj, '__openmath__'):
        # Call the __openmath__ method and return the result
        return obj.__openmath__()
    # Raise a ValueError if no conversion function can convert the object
    raise ValueError('Cannot convert %r to OpenMath.' % obj)

