def cls_build(inst, state):
    # Retrieve the __setstate__ method from the instance if it exists
    setstate = getattr(inst, "__setstate__", None)
    if setstate:
        setstate(state)
        return inst

    # Initialize slotstate to None if state is a tuple of length 2
    slotstate = None
    if isinstance(state, tuple) and len(state) == 2:
        state, slotstate = state

    # If state is not empty, update the instance's __dict__ or set attributes directly
    if state:
        try:
            d = inst.__dict__
            try:
                for k, v in six.iteritems(state):
                    d[six.moves.intern(k)] = v  # Ensure keys are interned
            except TypeError:
                d.update(state)
        except RuntimeError:
            # Fallback method for restricted execution environments
            for k, v in state.items():
                setattr(inst, k, v)

    # If slotstate is not empty, set attributes from slotstate
    if slotstate:
        for k, v in slotstate.items():
            setattr(inst, k, v)

    return inst

