def encode(data):
    if len(data) == 0:
        return data
    if len(data) == 1:
        return b'\x00' + data

    data = bytearray(data)
    result = bytearray()
    buf = bytearray()
    pos = 0
    repeat_count = 0
    MAX_LENGTH = 127
    state = 'RAW'

    def finish_raw():
        if len(buf) == 0:
            return
        result.append(len(buf) - 1)
        result.extend(buf)
        buf[:] = bytearray()

    def finish_rle():
        result.append(256 - (repeat_count - 1))
        result.append(data[pos])
        while pos < len(data) - 1:
            current_byte = data[pos]
            if data[pos] == data[pos + 1]:
                if state == 'RAW':
                    finish_raw()
                    state = 'RLE'
                    repeat_count = 1
                elif state == 'RLE':
                    if repeat_count == MAX_LENGTH:
                        finish_rle()
                        repeat_count = 0
                    repeat_count += 1
            else:
                if state == 'RLE':
                    repeat_count += 1
                    finish_rle()
                    state = 'RAW'
                    repeat_count = 0
                elif state == 'RAW':
                    if len(buf) == MAX_LENGTH:
                        finish_raw()
                    buf.append(current_byte)
                    pos += 1
                    if state == 'RAW':
                        buf.append(data[pos])
                        finish_raw()
                    else:
                        repeat_count += 1
                        finish_rle()

    return bytes(result)

