def convert(in_file, out_file, in_fmt="", out_fmt=""):
    # Expand user paths for input and output files
    in_file = os.path.expanduser(in_file)
    out_file = os.path.expanduser(out_file)

    # Check if input file exists
    if not os.path.exists(in_file):
        raise IOError(f"Input file {in_file} does not exist, stopping...")

    # Determine input and output formats, either explicitly or by guessing
    in_fmt = in_fmt.lower() or _guess_format_from_extension(in_file.split('.')[-1].lower())
    out_fmt = out_fmt.lower() or _guess_format_from_extension(out_file.split('.')[-1].lower())

    # Raise error if formats cannot be determined
    if not in_fmt or not out_fmt:
        raise ValueError("Cannot determine conversion formats.")

    # If input and output formats are the same, copy the file
    if in_fmt == out_fmt:
        shutil.copyfileobj(in_file, out_file)
        return False

    # Load data based on input format
    if in_fmt == 'hdf5':
        from import hdf5
        data = hdf5.load(in_file)
    elif in_fmt == 'tiff':
        from import tiff
        data = tiff.load(in_file)
    elif in_fmt == 'png':
        from import png
        data = png.load(in_file)
    else:
        return _fail_pair_conversion(in_fmt, out_fmt)

    # Save data based on output format
    if out_fmt == 'hdf5':
        from import hdf5
        return hdf5.save(out_file, data)
    elif out_fmt == 'tiff':
        from import tiff
        return tiff.save(out_file, data)
    elif out_fmt == 'png':
        from import png
        return png.export_png(out_file, data)
    else:
        return _fail_pair_conversion(in_fmt, out_fmt)

    # Return failure if no valid conversion is found
    return _fail_pair_conversion(in_fmt, out_fmt)

