def checktypes(func):
    sig = inspect.signature(func)
    types = {}
    for param in sig.parameters.values():
        param_type = param.annotation
        if param_type is param.empty or not inspect.isclass(param_type):
            continue
        types[param.name] = param_type
        if param.default is not param.empty and not isinstance(param.default, param_type):
            raise ValueError(f"{func.__qualname__}: wrong type of a default value for {param.name!r}")

def check_type(sig, arg_name, arg_type, arg_value):
    if not isinstance(arg_value, arg_type):
        raise ValueError(f"{func.__qualname__}: wrong type of {arg_name!r} argument, {arg_type.__name__!r} expected, got {type(arg_value).__name__!r}")

@functools.wraps(func)
def wrapper(*args, **kwargs):
    ba = sig.bind(*args, **kwargs)
    for arg_name, arg in ba.arguments.items():
        try:
            type_ = types[arg_name]
        except KeyError:
            continue
        param = sig.parameters[arg_name]
        if param.kind == param.VAR_POSITIONAL:
            for value in arg:
                check_type(sig, arg_name, type_, value)
        elif param.kind == param.VAR_KEYWORD:
            for subname, value in arg.items():
                check_type(sig, arg_name + ':' + subname, type_, value)
        else:
            check_type(sig, arg_name, type_, arg)
    result = func(*ba.args, **ba.kwargs)
    return_type = sig.return_annotation
    if return_type is not sig.empty and isinstance(return_type, type) and not isinstance(result, return_type):
        raise ValueError(f"{func.__qualname__}: wrong return type, {return_type.__name__!r} expected, got {type(result).__name__!r}")
    return result

