def visit_RepOptional(self, node: parsing.RepOptional) -> Union[List[ast.stmt], ast.expr]:
    cl_ast = self.visit(node.pt)
    if isinstance(cl_ast, ast.expr):
        return ast.BoolOp(ast.Or(), [cl_ast, ast.Name('True', ast.Load())])
    self.in_optional += 1
    cl_ast = self.visit(node.pt)
    self.in_optional -= 1
    return cl_ast

