def populate_from_sequence(seq: list, r: ref(Edge), sr: state.StateRegister):
    base_state = r  # Set the base state to the current state
    idxlast = len(seq) - 1  # Get the index of the last element in the sequence
    idx = 0  # Initialize the index to 0

    for m in seq:
        if isinstance(m, list):
            # Recursively connect all states of each alternative sequence
            for item in m:
                populate_from_sequence(item, r, sr)
        elif isinstance(m, MatchExpr):
            # Check if there is an existing edge for the current event
            eX = r().get_next_edge(m)
            if eX is None:
                sX = None
                if idx != idxlast:
                    sX = state.State(sr)  # Create a new state if not the last element
                sX.matchDefault(base_state().s)  # Match the default state
            else:
                # Last state of sequence, return to the base state
                sX = base_state().s
                eX = Edge(sX)
                r().next_edge[id(sX)] = eX
            m.attach(r().s, sX, sr)  # Attach the edge to the current state
            r = ref(eX)  # Update the reference to the new state
            idx += 1

