def draw(self):
    # Set OpenGL state for 2D drawing
    self.window.set2d()

    # Draw the background based on its type
    if isinstance(self.bg, Layer):
        self.bg._draw()
    elif hasattr(self.bg, "draw") and callable(self.bg.draw):
        self.bg.draw()
    elif isinstance(self.bg, (list, tuple)):
