    elif isinstance(self.bg, Background):
        if not self.bg.initialized:
            self.bg.init_bg()
        self.bg.redraw_bg()
        self.bg.initialized = True
    elif self.bg == "blank":
        pass
    else:
        raise TypeError("Unknown background type")

    # Reset OpenGL state for 2D drawing
    self.window.set2d()

    # Redraw widgets that need it
    for widget in self.widgets.values():
        if widget.do_redraw:
            widget.on_redraw()
            widget.do_redraw = False

    # Draw the content of the batch
