def _draw(self, mode, vertex_list=None):
    # Push client attributes for vertex array
    glPushClientAttrib(GL_CLIENT_VERTEX_ARRAY_BIT)

    # Bind and enable buffer attributes
    for buffer, attributes in self.buffer_attributes:
        buffer.bind()
        for attribute in attributes:
            attribute.enable()
            attribute.set_pointer(attribute.buffer.ptr)

    # Handle VBO finish workaround
    if vertexbuffer._workaround_vbo_finish:
        glFinish()

    # Draw using vertex list or allocated regions
    if vertex_list is not None:
        glDrawArrays(mode, vertex_list.start, vertex_list.count)
    else:
        starts, sizes = self.allocator.get_allocated_regions()
        primcount = len(starts)
        if primcount == 0:
            pass
        elif primcount == 1:
            glDrawArrays(mode, starts[0], int(sizes[0]))
        elif gl_info.have_version(1, 4):
            starts = (GLint * primcount)(* starts)
            sizes = (GLsizei * primcount)(* sizes)
            glMultiDrawArrays(mode, starts, sizes, primcount)
        else:
            for start, size in zip(starts, sizes):
                glDrawArrays(mode, start, size)

    # Unbind buffers and pop client attributes
    for buffer, _ in self.buffer_attributes:
        buffer.unbind()
    glPopClientAttrib()

