def _make_content_item(node, mime_type=None, alternate_data=None):
    """
    Processes a node to extract and decode its data, handling zlib compression and setting the MIME type.

    Args:
        node (Node): The node containing the data to be processed.
        mime_type (str, optional): The MIME type of the content. If not provided, it defaults to the node's MIME type.
        alternate_data (bytes, optional): Alternate data to decompress if the node's data is compressed.

    Returns:
        ContentItem: A ContentItem object containing the processed raw data and MIME type.

    Raises:
        Exception: If decompression fails and no alternate data is provided.
    """
    if getattr(node, 'encoding', None) == 'zlib':
        try:
            raw = zlib.decompress(node.data)
        except Exception as exc:
            if alternate_data is not None:
                try:
                    raw = zlib.decompress(alternate_data)
                except Exception:
                    raise exc  # the original exception
            else:
                raise
    else:
        raw = node.data

    if mime_type is None:
        mime_type = node.mime_type

    raw = raw.decode('utf8').encode('utf8')
    return streamcorpus.ContentItem(raw=raw, media_type=mime_type)

