def make_chains_with_names(sentences):
    # Initialize a default dictionary to store entity chains
    equiv_ids = collections.defaultdict(lambda: (set(), set()))
    fake_equiv_ids = -2  # Initialize a counter for fake equivalence IDs

    # Iterate over each tagger ID and its corresponding sentences
    for tagger_id, sents in sentences.items():
        for sent in sents:
            for tok in sent.tokens:
                if tok.entity_type is not None:
                    # Assign an appropriate equivalence ID
                    if tok.equiv_id == -1:
                        eqid = fake_equiv_ids
                        fake_equiv_ids -= 1
                    else:
                        eqid = tok.equiv_id

                    # Store the token's name part and the token object
                    equiv_ids[eqid][0].add(cleanse(tok.token.decode('utf8')))
                    equiv_ids[eqid][1].add(tok)

    return equiv_ids

