def multi_token_match(stream_item, aligner_data):
    # Extract the tagger ID from the stream item and aligner data
    tagger_id = _get_tagger_id(stream_item, aligner_data)
    # Retrieve sentences associated with the tagger ID
    sentences = stream_item.body.sentences.get(tagger_id)
    if not sentences:
        return

    # Construct a list of tuples where each tuple contains a tuple of cleansed strings and the corresponding Token object
    tokens = map(lambda tok: (cleanse(tok.token.decode('utf8')).split(' '), tok), itertools.chain(*[sent.tokens for sent in sentences]))

    # Get the required annotator ID from aligner data
    required_annotator_id = aligner_data['annotator_id']

    # Iterate over ratings from the stream item
    for annotator_id, ratings in stream_item.ratings.items():
        if (required_annotator_id is None) or (annotator_id == required_annotator_id):
            for rating in ratings:
                label = Label(annotator=rating.annotator, target=rating.target)
                num_tokens_matched = 0

