def html_entities_to_unicode(text, space_padding=False, safe_only=False):
    """
    Converts HTML entities in the given text to their corresponding Unicode characters.

    Args:
    text (str): The input text containing HTML entities.
    space_padding (bool, optional): If True, pads the converted entities with spaces to maintain the original length. Defaults to False.
    safe_only (bool, optional): If True, only converts entities that are considered safe to convert. Defaults to False.

    Returns:
    str: The text with HTML entities converted to Unicode characters.
    """
    def convert_entities(match):
        """
        Converts a single HTML entity to its corresponding Unicode character.

        Args:
        match (re.Match): The match object containing the HTML entity.

        Returns:
        str: The Unicode character corresponding to the HTML entity.
        """
        x = match.group(1)
        if safe_only and x not in ENTITIES_THAT_ARE_SAFE_TO_STRING_PAD:
            return u'&%s;' % x
        if x in name2codepoint:
            return unichr(name2codepoint[x])
        elif x in XML_ENTITIES_TO_SPECIAL_CHARS:
            return XML_ENTITIES_TO_SPECIAL_CHARS[x]
        elif len(x) > 0 and x[0] == '#':
            if len(x) > 1 and x[1] == 'x':
                return unichr(int(x[2:], 16))
            else:
                return unichr(int(x[1:]))
        else:
            return u'&%s;' % x

    def convert_to_padded_entities(match):
        """
        Converts a single HTML entity to its corresponding Unicode character and pads it with spaces if required.

        Args:
        match (re.Match): The match object containing the HTML entity.

        Returns:
        str: The Unicode character corresponding to the HTML entity, padded with spaces if required.
        """
        converted_string = convert_entities(match)
        num_spaces_needed = len(match.group(0)) - len(converted_string)
        assert num_spaces_needed >= 0, 'len(%r) !<= len(%r)' % (converted_string, match.group(0))
        num_left = int(num_spaces_needed / 2)
        num_right = num_spaces_needed - num_left
        return (' ' * num_left) + converted_string + (' ' * num_right)

    if space_padding:
        return tags.sub(convert_to_padded_entities

