def make_clean_visible(_html, tag_replacement_char=' '):
    def non_tag_chars(html):
        n = 0
        while n < len(html):
            angle = html.find('<', n)
            if angle == -1:
                yield html[n:]
                n = len(html)
                break
            yield html[n:angle]
            n = angle
            while n < len(html):
                nl = html.find('\n', n)
                angle = html.find('>', n)
                if angle == -1:
                    yield ' ' * (len(html) - n)
                    n = len(html)
                    break
                elif nl == -1 or angle < nl:
                    yield ' ' * (angle + 1 - n)
                    n = angle + 1
                    break
                else:
                    yield ' ' * (nl - n) + '\n'
                    n = nl + 1

    if not isinstance(_html, unicode):
        _html = unicode(_html, 'utf-8')
    _html = fix_emails(_html)
    non_tag = ''.join(non_tag_chars(_html))
    return non_tag.encode('utf-8')


**Summary:**
The function `make_clean_visible` takes an HTML string `_html` and an optional `tag_replacement_char` (default is a space). It processes the HTML to remove tags and replace them with spaces, while preserving newlines. The function first ensures the input is a Unicode string. It then uses a nested generator function `non_tag_chars` to iterate through the HTML, yielding non-tag characters and spaces as needed. Finally, it encodes the resulting string in UTF-8 and returns it.

