def parse_config(options):
    """
    Parses a configuration file and returns a dictionary containing the configuration data.

    Args:
    options (object): An object containing the configuration file path and quiet mode flag.

    Returns:
    dict: A dictionary containing the configuration data if successful, otherwise None.

    Raises:
    SystemExit: If the configuration file does not exist or contains missing options.
    """
    if os.path.exists(options.config):
        config = ConfigParser.ConfigParser()
        try:
            config.read(options.config)
        except Exception as err:
            if not options.quiet:
                sys.stderr.write(f"ERROR: Config file read {options.config} error. {err}")
            sys.exit(-1)

        try:
            configdata = {
                "secrets": config.get("GOOGLE", "secrets"),
                "credentials": config.get("nagios-notification-google-calendar", "credentials"),
                "start": config.get("nagios-notification-google-calendar", "start"),
                "end": config.get("nagios-notification-google-calendar", "end"),
                "message": config.get("nagios-notification-google-calendar", "message"),
            }
        except ConfigParser.NoOptionError as err:
            if not options.quiet:
                sys.stderr.write(f"ERROR: Config file missing option error. {err}\n")
            sys.exit(-1)

        mandatories = ["secrets", "credentials", "start", "end", "message"]
        if not all(configdata[mandatory] for mandatory in mandatories):
            if not options.quiet:
                sys.stdout.write("Mandatory config option missing\n")
            sys.exit(0)

        return configdata
    else:
        if not options.quiet:
            sys.stderr.write(f"ERROR: Config file {options.config} does not exist\n")
        sys.exit(0)

