def to_boolean(obj):
    # Check if the object has an iterator attribute
    if hasattr(obj, '__iter__'):
        # If the object is an instance of LiteralWrapper, get the value inside
        if isinstance(obj, LiteralWrapper):
            val = obj.obj
        # If the object is an iterable (but not a string), get the first element
        elif isinstance(obj, Iterable) and not isinstance(obj, str):
            val = next(obj, None)
        else:
            val = obj
    else:
        val = obj

    # Convert the value to a boolean
    if val is None:
        yield False
    elif isinstance(val, bool):
        yield val
    elif isinstance(val, str):
        yield bool(val)
    elif isinstance(val, node):
        yield True
    elif isinstance(val, (float, int)):
        yield bool(val)
    else:
        raise RuntimeError('Unknown type for boolean conversion: {}'.format(val))

