def open(path, mode=gdalconst.GA_ReadOnly):
    """
    Open a raster file or a file-like object.

    Parameters:
    path (str or file-like object): The path to the raster file or a file-like object providing read() method.
    mode (int, optional): The access mode for opening the raster file. Default is GA_ReadOnly.

    Returns:
    Raster: A Raster object representing the opened raster file.

    Raises:
    TypeError: If the provided path is not a file-like object providing read() method.
    ValueError: If the raster file cannot be opened from the provided path.
    """
    path = getattr(path, 'name', path)
    try:
        return Raster(vsiprefix(path), mode)
    except AttributeError:
        try:
            imgdata = path.read()
        except AttributeError:
            raise TypeError('Not a file-like object providing read()')
        else:
            imgio = MemFileIO(delete=False)
            gdal.FileFromMemBuffer(imgio.name, imgdata)
            return Raster(imgio, mode)
    raise ValueError('Failed to open raster from "%r"' % path)

