def raster(self, path, size, bandtype=gdal.GDT_Byte):
    # Ensure the path is a string
    path = getattr(path, 'name', path)

    try:
        # Determine if the size is for a multiband raster
        is_multiband = len(size) > 2
        nx, ny, nbands = size if is_multiband else size + (1,)
    except (TypeError, ValueError) as exc:
        exc.args = ('Size must be 2 or 3-item sequence',)
        raise

    # Validate the raster size
    if nx < 1 or ny < 1:
        raise ValueError(f'Invalid raster size {size}')

    # Check if the file already exists
    if not self._is_empty(path):
        raise IOError(f'{path} already exists, open with Raster()')

    # Create the raster dataset
    ds = self.Create(path, nx, ny, nbands, bandtype)
    if not ds:
        raise ValueError(f'Could not create {path} using {self}')

    # Return the created Raster object
    return Raster(ds)

