def _match_regex(regex, obj):
    """
    Checks if the given regex matches any part of the input object.

    Args:
        regex (str): The regular expression to match.
        obj (any): The input object to be checked.

    Returns:
        bool: True if the regex matches any part of the input object, False otherwise.
    """
    if isinstance(obj, six.string_types):
        return len(regex.findall(obj)) > 0
    elif isinstance(obj, dict):
        return _match_regex(regex, obj.values())
    elif hasattr(obj, '__iter__'):
        return any(_match_regex(regex, s) for s in obj if isinstance(s, six.string_types))
    else:
        return False

