def render_entries(cls, entries, additional_columns=None, only_show=None, numbers=False):
    # Set default columns or use provided additional columns
    additional_columns = additional_columns or []
    if only_show is not None:
        columns = _uniquify(only_show)
    else:
        columns = _uniquify(cls.DEFAULT_COLUMNS + additional_columns)

    # Create the top row with pretty names of columns
    top_row = [cls.prettyname(col) for col in columns]
    table = [top_row]

    # Add rows for each entry, including row numbers if specified
    for i, entry in enumerate(entries):
        row = [entry._get_attrib(c, convert_to_str=True) for c in columns]
        table.append(row if not numbers else [i] + row)

    # Get current terminal width and color settings
    cur_width = get_current_terminal_width()
    colors = [get_color_hash(c, MIN_COLOR_BRIGHT, MAX_COLOR_BRIGHT) for c in columns]

    # Render table if it fits the terminal width, otherwise render rows individually
    if cur_width >= get_table_width(table):
        return render_table(table, column_colors=colors if not numbers else [green] + colors)
    else:
        result = []
        first_index = 1 if numbers else 0
        for row in table[1:]:
            rep = [green('%s:' % row[0]) if numbers else '-----']
            for i, val in enumerate(row[first_index:]):
                color = colors[i - 1 if numbers else i]
                name = columns[i]
                rep.append('  %s: %s' % (name, color(val)))
            result.append('\n'.join(rep))
        return '\n'.join(result)

