def build(self, secret_key):
    # Create a JWK key using the provided secret key
    key = jwk.JWK(kty='oct', k=base64url_encode(uuid.UUID(secret_key).bytes))

    # Define the header for the JWT
    header = {
        'alg': 'dir',
        'enc': 'A128GCM',
        'zip': 'DEF',
        'cty': 'JWT',
        'kid': self._access_key,
    }

    # Get the current time in seconds since the epoch
    now = int(time.time())

    # Create the payload for the JWT
    payload = {
        'iat': now,
        'nbf': now,
    }

    # Add expiration time to the payload if it is provided
    if self._expiration is not None:
        payload['exp'] = int(calendar.timegm(self._expiration.utctimetuple()))

    # Add view identifiers to the payload if they are provided
    if len(self._view_identifiers) > 0:
        payload[VIEW_IDENTIFIERS_CLAIM_NAME] = self._view_identifiers

    # Add parameters to the payload if they are provided
    if len(self._parameters) > 0:
        parameters = []
        for parameter in self._parameters:
            serialized = {
                'field': parameter.field,
                'op': parameter.op,
            }
            if hasattr(parameter, '__iter__'):
                serialized['any'] = list(parameter.value)
            else:
                serialized['value'] = parameter.value
            parameters.append(serialized)
        payload[PARAMETERS_CLAIM_NAME] = parameters

    # Add attributes to the payload if they are provided
    if len(self._attributes) > 0:
        payload[ATTRIBUTES_CLAIM_NAME] = self._attributes

    # Create a JWE token with the payload and header
    tok = jwe.JWE(json_encode(payload), protected=header)

    # Add the recipient key to the JWE token
    tok.add_recipient(key)

    # Serialize the JWE token in compact format and return it
    return tok.serialize(compact=True)

