def _make_ff_params_dict(self):
    """
    Creates a dictionary of force field parameters.

    Returns:
        dict: A dictionary where keys are residue names and values are dictionaries of atom parameters.

    Raises:
        ForceFieldParameterError: If the force field parameters are badly formatted.
    """
    ff_params_struct_dict = {}
    for res in self.keys():
        if res == 'KEY':
            continue
        if res not in ff_params_struct_dict:
            ff_params_struct_dict[res] = {}
        for atom, params in self[res].items():
            ff_params_struct_dict[res][atom] = PyAtomData(atom.encode(), params[0].encode(), *params[1:])
    return ff_params_struct_dict

