def evaluate_metadata_statement(self, metadata, keyjar=None):
    # Filter out ignored keys from the metadata
    res = {k: v for k, v in metadata.items() if k not in IgnoreKeys}
    les = []

    # Check if there are metadata statements in the metadata
    if 'metadata_statements' in metadata:
        for fo, ms in metadata['metadata_statements'].items():
            if isinstance(ms, str):
                ms = json.loads(ms)
            for _le in self.evaluate_metadata_statement(ms):
                if isinstance(ms, Message):
                    le = LessOrEqual(sup=_le, **ms.to_dict())
                else:
                    le = LessOrEqual(sup=_le, **ms)
                if le.is_expired():
                    logger.error('This metadata statement has expired: {}'.format(ms))
                    logger.info('My time: {}'.format(utc_time_sans_frac()))
                    continue
                le.eval(res)
                les.append(le)
        return les
    else:
        # Handle the innermost metadata statement
        try:
            _iss = metadata['iss']
        except:
            le = LessOrEqual()
            le.eval(res)
        else:
            le = LessOrEqual(iss=_iss, exp=metadata['exp'])
            le.eval(res)
            les.append(le)
        return les

