def unpad(padded_data, block_size, style='pkcs7'):
    """
    Removes padding from the given padded data based on the specified block size and padding style.

    Args:
    padded_data (bytes): The padded data to be unpadded.
    block_size (int): The block size used for padding.
    style (str, optional): The padding style to be used. Defaults to 'pkcs7'. Supported styles are 'pkcs7', 'x923', and 'iso7816'.

    Returns:
    bytes: The unpadded data.

    Raises:
    ValueError: If the input data is not padded, the padding is incorrect, or an unknown padding style is provided.
    """
    pdata_len = len(padded_data)
    if pdata_len % block_size:
        raise ValueError("Input data is not padded")

    if style in ('pkcs7', 'x923'):
        padding_len = ord(padded_data[-1])
        if padding_len < 1 or padding_len > min(block_size, pdata_len):
            raise ValueError("Padding is incorrect.")
        if style == 'pkcs7':
            if padded_data[-padding_len:] != bytes([padding_len]) * padding_len:
                raise ValueError("PKCS#7 padding is incorrect.")
        else:
            if padded_data[-padding_len:-1] != bytes([0]) * (padding_len - 1):
                raise ValueError("ANSI X.923 padding is incorrect.")
    elif style == 'iso7816':
        padding_len = pdata_len - padded_data.rfind(b'\x80')
        if padding_len < 1 or padding_len > min(block_size, pdata_len):
            raise ValueError("Padding is incorrect.")
        if padding_len > 1 and padded_data[-padding_len:-1] != bytes([0]) * (padding_len - 1):
            raise ValueError("ISO 7816-4 padding is incorrect.")
    else:
        raise ValueError("Unknown padding style")

    return padded_data[:-padding_len]

