def word_score(word, input_letters, questions=0):
    score = 0
    bingo = 0
    filled_by_blanks = []
    rack = list(input_letters)  # Make a copy to speed up find_anagrams()

    for letter in word:
        if letter in rack:
            bingo += 1
            score += letter_score(letter)
            rack.remove(letter)
        else:
            filled_by_blanks.append(letter_score(letter))

    # Handle blanks ('?' and '_') by applying the highest scoring letters first
    for blank_score in sorted(filled_by_blanks, reverse=True):
        if questions > 0:
            score += blank_score
            questions -= 1

    # Bonus points for using all tiles in the rack
    if bingo > 6:
        score += 50

    return score

