def deserialize_value(ty, value):
    uty = ty.upper()
    if uty == 'BOOLEAN':
        if value.isdigit():
            return bool(int(value))
        elif value.upper() == 'FALSE':
            return False
        elif value.upper() == 'TRUE':
            return True
        else:
            return None
    elif uty == 'INTEGER':
        if '"' in value:
            return uuid.UUID(value[1:-1]).int
        else:
            return int(value)
    elif uty == 'REAL':
