    }
    transfer_fn = {
        'BOOLEAN': lambda v: '%d' % int(v),
        'INTEGER': lambda v: '%d' % v,
        'REAL': lambda v: '%f' % v,
        'STRING': lambda v: "'%s'" % v.replace("'", "''"),
        'UNIQUE_ID': lambda v: '"%s"' % uuid.UUID(int=v)
    }
    if value is None:
        value = null_value[ty]
    return transfer_fn[ty](value)


