def _find_match(self, position):
    # Determine the character to search for and the direction to search in.
    document = self._text_edit.document()
    start_char = document.characterAt(position)
    search_char = self._opening_map.get(start_char)
    if search_char:
        increment = 1
    else:
        search_char = self._closing_map.get(start_char)
        if search_char:
            increment = -1
        else:
            return -1  # No matching character found.

    # Search for the character.
    char = start_char
    depth = 0
    while position >= 0 and position < document.characterCount():
        if char == start_char:
            depth += 1
        elif char == search_char:
            depth -= 1
        if depth == 0:
            break
        position += increment
        char = document.characterAt(position)

    if position == -1:
        return -1  # No matching character found.

    return position

