def remote_iterator(view, name):
    # Initialize an iterator on the remote view
    view.execute('it%s=iter(%s)' % (name, name), block=True)
    while True:
        try:
            # Apply the next method to the iterator and get the result
            result = view.apply_sync(lambda x: x.next(), Reference('it' + name))
        except RemoteError as e:
            # Handle the StopIteration exception
            if e.ename == 'StopIteration':
                raise StopIteration
            else:
                raise e
        else:
            # Yield the result if no exception is raised
            yield result

