def get_importer(path_item):
    try:
        # Try to get the importer from the cache
        importer = sys.path_importer_cache[path_item]
    except KeyError:
        # If not in cache, try each hook in sys.path_hooks
        for hook in sys.path_hooks:
            try:
                importer = hook(path_item)
            except ImportError:
                pass
            else:
                break
        else:
            # If no hook succeeds, set importer to None
            importer = None
    # Cache the result
    sys.path_importer_cache.setdefault(path_item, importer)
    # If still None, try using ImpWrapper
    if importer is None:
        try:
            importer = ImpWrapper(path_item)
        except ImportError:
            pass
    return importer

