def push_accepts_more(self):
    # If the input is not complete, unconditionally accept more.
    if not self._is_complete:
        return True

    # If the input is complete and we're flush left:
    if self.indent_spaces == 0:
        # In line mode, if there hasn't been any indentation, return False.
        if self.input_mode == 'line':
            if not self._full_dedent:
                return False
            else:
                try:
                    # Try to parse the input as Python code.
                    code_ast = ast.parse(u''.join(self._buffer))
                except Exception:
                    return False
                else:
                    # If the parsed code has more than one block, return False.
                    if len(code_ast.body) > 1:
                        return False

        # In cell mode, check the number of blocks the input compiles into.
        elif self.input_mode == 'cell':
            try:
                # Try to parse the input as Python code.
                code_ast = ast.parse(u''.join(self._buffer))
            except Exception:
                return False
            else:
                # If the parsed code has more than one block, return True.
                if len(code_ast.body) > 1:
                    return True

    # If the input is complete and there is a blank final line, return True.
    last_line = self.source.splitlines()[-1]
    return bool(last_line and not last_line.isspace())

