def _render_expression(self, check):
    """
    Renders an SQL expression based on the given check dictionary.

    Args:
        check (dict): A dictionary containing the conditions to be rendered into an SQL expression.

    Returns:
        tuple: A tuple containing the rendered SQL expression and a list of arguments to be used in the SQL query.

    Raises:
        KeyError: If there are any illegal testing keys in the check dictionary.
        ValueError: If an equality test is used with NULL values on the SQLite backend.

    """
    expressions = []
    args = []
    skeys = set(check.keys())
    skeys.difference_update(set(self._keys))
    skeys.difference_update(set(['buffers', 'result_buffers']))
    if skeys:
        raise KeyError("Illegal testing key(s): %s" % skeys)

    for name, sub_check in check.items():
        if isinstance(sub_check, dict):
            for test, value in sub_check.items():
                try:
                    op = operators[test]
                except KeyError:
                    raise KeyError("Unsupported operator: %r" % test)

                if isinstance(op, tuple):
                    op, join = op

                if value is None and op in null_operators:
                    expr = "%s %s" % (name, null_operators[op])
                else:
                    expr = "%s %s ?" % (name, op)

                if isinstance(value, (tuple, list)):
                    if op in null_operators and any([v is None for v in value]):
                        raise ValueError("Cannot use %r test with NULL values on SQLite backend" % test)
                    expr = '( %s )' % (join.join([expr] * len(value)))
                    args.extend(value)
                else:
                    args.append(value)

                expressions.append(expr)
        else:
            # it's an equality check
            if sub_check is None:
                expressions.append("%s IS NULL" % name)
            else:
                expressions.append("%s = ?" % name)
            args.append(sub_check)

    expr = " AND ".join(expressions)
    return expr, args

