def split_user_input(line, pattern=None):
    # Ensure the input line is in unicode
    encoding = get_stream_enc(sys.stdin, 'utf-8')
    line = py3compat.cast_unicode(line, encoding)

    # If no pattern is provided, use a default pattern
    if pattern is None:
        pattern = line_split

    # Try to match the line with the provided pattern
    match = pattern.match(line)

    # If no match is found, handle the line manually
    if not match:
        try:
            ifun, the_rest = line.split(None, 1)
        except ValueError:
            ifun, the_rest = line, u''

        pre = re.match('^(\s*)(.*)', line).groups()[0]
        esc = ""
    else:
        pre, esc, ifun, the_rest = match.groups()

    # Return the pre, esc, ifun, and the_rest
    return pre, esc or '', ifun.strip(), the_rest.lstrip()

