def json_clean(obj):
    # Define types that are atomic and okay in JSON as-is
    atomic_ok = (unicode, int, types.NoneType)
    # Define containers that need to be converted into lists
    container_to_list = (tuple, set, types.GeneratorType)

    # Handle float types
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            return repr(obj)
        return obj

    # Handle atomic types
    if isinstance(obj, atomic_ok):
        return obj

    # Handle bytes
    if isinstance(obj, bytes):
        return obj.decode(DEFAULT_ENCODING, 'replace')

    # Handle containers that need to be converted to lists
    if isinstance(obj, container_to_list) or (hasattr(obj, '__iter__') and hasattr(obj, next_attr_name)):
        obj = list(obj)

    # Handle lists
    if isinstance(obj, list):
        return [json_clean(x) for x in obj]

    # Handle dictionaries
    if isinstance(obj, dict):
        # Validate that the dictionary won't lose data due to key collisions
        nkeys = len(obj)
        nkeys_collapsed = len(set(map(str, obj)))
        if nkeys != nkeys_collapsed:
            raise ValueError('dict can not be safely converted to JSON: key collision would lead to dropped values')
        # Create a new dictionary that will be JSON-safe
        out = {}
        for k, v in obj.iteritems():
            out[str(k)] = json_clean(v)
        return out

    # Handle other objects by returning their repr
    return repr(obj)

