def flatten_flags(self):
    # Build a tree of classes inheriting from a particular parent class
    mro_tree = defaultdict(list)
    for cls in self.classes:
        clsname = cls.__name__
        for parent in cls.mro()[1:-3]:  # Exclude cls itself and Configurable, HasTraits, object
            mro_tree[parent.__name__].append(clsname)

    # Flatten aliases, which have the form: { 'alias': 'Class.trait' }
    aliases = {}
    for alias, cls_trait in self.aliases.items():
        cls, trait = cls_trait.split('.', 1)
        children = mro_tree[cls]
        if len(children) == 1:  # Exactly one descendent, promote alias
            cls = children[0]
            aliases[alias] = '.'.join([cls, trait])

    # Flatten flags, which are of the form: { 'key': ({'Cls': {'trait': value}}, 'help') }
    flags = {}
    for key, (flagdict, help) in self.flags.items():
        newflag = {}
        for cls, subdict in flagdict.items():
            children = mro_tree[cls]
            if len(children) == 1:  # Exactly one descendent, promote flag section
                cls = children[0]
                newflag[cls] = subdict
        flags[key] = (newflag, help)

    return flags, aliases

