def class_get_trait_help(cls, trait, inst=None):
    """
    Generates help text for a trait of a class.

    Parameters:
    cls (type): The class containing the trait.
    trait (Trait): The trait for which help is requested.
    inst (object, optional): An instance of the class. If provided, the current value of the trait is included in the help text.

    Returns:
    str: A string containing the help text for the trait.
    """
    lines = []
    header = "--%s.%s=<%s>" % (cls.__name__, trait.name, trait.__class__.__name__)
    lines.append(header)

    if inst is not None:
        lines.append(indent('Current: %r' % getattr(inst, trait.name), 4))
    else:
        try:
            dvr = repr(trait.get_default_value())
        except Exception:
            dvr = None  # ignore defaults we can't construct

        if dvr is not None:
            if len(dvr) > 64:
                dvr = dvr[:61] + '...'
            lines.append(indent('Default: %s' % dvr, 4))

        if 'Enum' in trait.__class__.__name__:
            lines.append(indent('Choices: %r' % (trait.values,)))

        help_text = trait.get_metadata('help')
        if help_text is not None:
            help_text = '\n'.join(wrap_paragraphs(help_text, 76))
            lines.append(indent(help_text, 4))

    return '\n'.join(lines)

