def base_launch_kernel(code, fname, stdin=None, stdout=None, stderr=None, executable=None, independent=False, extra_arguments=[], cwd=None):
    # Build the kernel launch command.
    if executable is None:
        executable = sys.executable
    arguments = [executable, '-c', code, '-f', fname]
    arguments.extend(extra_arguments)

    # Redirect stdin, stdout, and stderr if necessary.
    redirect_in = True if stdin is None else False
    redirect_out = True if sys.executable.endswith('pythonw.exe') else False

    if redirect_out:
        _stdout = PIPE if stdout is None else stdout
        _stderr = PIPE if stderr is None else stderr
    else:
        _stdout, _stderr = stdout, stderr

    # Spawn a kernel.
    if sys.platform == 'win32':
        interrupt_event = ParentPollerWindows.create_interrupt_event()
        arguments += ['--interrupt=%i' % interrupt_event]
        if executable.endswith('pythonw.exe'):
            if stdout is None:
                arguments.append('--no-stdout')
            if stderr is None:
                arguments.append('--no-stderr')
        if independent:
            proc = Popen(arguments, creationflags=512, stdin=_stdin, stdout=_stdout, stderr=_stderr)
        else:
            pid = GetCurrentProcess()
            handle = DuplicateHandle(pid, pid, pid, 0, True, DUPLICATE_SAME_ACCESS)
            proc = Popen(arguments + ['--parent=%i' % int(handle)], stdin=_stdin, stdout=_stdout, stderr=_stderr)
            proc.win32_interrupt_event = interrupt_event
    else:
        if independent:
            proc = Popen(arguments, preexec_fn=lambda: os.setsid(), stdin=_stdin, stdout=_stdout, stderr=_stderr, cwd=cwd)
        else:
            proc = Popen(arguments + ['--parent=1'], stdin=_stdin, stdout=_stdout, stderr=_stderr, cwd=cwd)

    # Clean up pipes created to work around Popen bug.
    if redirect_in:
        if stdin is None:
            proc.stdin.close()
    if redirect_out:
        if stdout is None:
            proc.stdout.close()
        if stderr is None:
            proc.stderr.close()

    return proc

