def hdict(self, hashroot):
    # Retrieve and sort files in the specified directory
    hfiles = self.keys(hashroot + "/*")
    hfiles.sort()

    # Determine the last file and handle special case if it ends with 'xx'
    last = len(hfiles) and hfiles[-1] or ''
    if last.endswith('xx'):
        hfiles = [last] + hfiles[:-1]

    # Initialize a dictionary to store all data
    all_data = {}

    # Iterate over each file, update the dictionary, and handle exceptions
    for f in hfiles:
        try:
            all_data.update(self[f])
        except KeyError:
            print(f"Corrupt {f}, deleted - hset is not threadsafe!")
            del self[f]
            self.uncache(f)

    return all_data

