def hcompress(self, hashroot):
    # Retrieve all files in the specified directory
    hfiles = self.keys(hashroot + "/*")
    all_data = {}

    # Iterate over each file, update the dictionary with its data, and uncache the file
    for f in hfiles:
        all_data.update(self[f])
        self.uncache(f)

    # Store the combined data in a new file
    self[hashroot + '/xx'] = all_data

