def _select_index(self, row, col):
    nr, nc = self._size
    nr -= 1
    nc -= 1

    # Case 1: Move to the top-left corner if out of bounds in both directions
    if (row > nr and col >= nc) or (row >= nr and col > nc):
        self._select_index(0, 0)

    # Case 2: Move to the bottom-right corner if out of bounds in both directions
    elif (row <= 0 and col < 0) or (row < 0 and col <= 0):
        self._select_index(nr, nc)

    # Case 3: Move to the top row if out of bounds in the row direction
    elif row > nr:
        self._select_index(0, col + 1)

    # Case 4: Move to the bottom row if out of bounds in the row direction
    elif row < 0:
        self._select_index(nr, col - 1)

    # Case 5: Move to the leftmost column if out of bounds in the column direction
    elif col > nc:
        self._select_index(row + 1, 0)

    # Case 6: Move to the rightmost column if out of bounds in the column direction
    elif col < 0:
        self._select_index(row - 1, nc)

    # Case 7: Set the index if within bounds
    elif 0 <= row and row <= nr and 0 <= col and col <= nc:
        self._index = (row, col)

    # Case 8: Raise an error if out of bounds and no completion has been reached
    else:
        raise NotImplementedError("You're trying to go where no completion has gone before: %d:%d (%d:%d)" % (row, col, nr, nc))

