def attr_matches(self, text):
    # Match attribute access pattern in the input text
    m = re.match(r"(\S+(\.\w+)*)\.(\w*)$", text)
    if m:
        expr, attr = m.group(1, 3)
    elif self.greedy:
        m2 = re.match(r"(.+)\.(\w*)$", self.line_buffer)
        if not m2:
            return []
        expr, attr = m2.group(1, 2)
    else:
        return []

    # Evaluate the expression in the current namespace
    try:
        obj = eval(expr, self.namespace)
    except:
        try:
            obj = eval(expr, self.global_namespace)
        except:
            return []

    # Get the list of attributes based on the object
    if self.limit_to__all__ and hasattr(obj, '__all__'):
        words = get__all__entries(obj)
    else:
        words = dir2(obj)

    # Complete the object attributes
    try:
        words = generics.complete_object(obj, words)
    except TryNext:
        pass
    except Exception:
        pass

    # Build the list of matching attributes
    n = len(attr)
    res = [f"{expr}.{w}" for w in words if w[:n] == attr]
    return res

