def file_matches(self, text):
    # Handle leading '!' if present
    if text.startswith('!'):
        text = text[1:]
        text_prefix = '!'
    else:
        text_prefix = ''

    # Get the text until the cursor
    text_until_cursor = self.text_until_cursor

    # Track strings with open quotes
    open_quotes = has_open_quotes(text_until_cursor)

    # Split the text based on parentheses or brackets
    if '(' in text_until_cursor or '[' in text_until_cursor:
        lsplit = text
    else:
        try:
            # Use a custom split function to handle unicode bugs
            lsplit = arg_split(text_until_cursor)[-1]
        except ValueError:
            # Handle unmatched quotes or backslashes without escaped characters
            if open_quotes:
                lsplit = text_until_cursor.split(open_quotes)[-1]
            else:
                return []
        except IndexError:
            # Handle tab press on empty line
            lsplit = ""

    # Check for protectable characters and handle accordingly
    if not open_quotes and lsplit != protect_filename(lsplit):
        has_protectables = True
        text0, text = text, lsplit
    else:
        has_protectables = False
        text = os.path.expanduser(text)

    # If text is empty, return all files
    if text == "":
        return [text_prefix + protect_filename(f) for f in self.glob("*")]

    # Compute matches from the filesystem
    m0 = self.clean_glob(text.replace('\\', ''))

    # Handle protectable characters if present
    if has_protectables:
        len_lsplit = len(lsplit)
        matches = [text_prefix + text0 + protect_filename(f[len_lsplit:]) for f in m0]
    else:
        if open_quotes:
            # If there's an open quote, don't protect filenames
            matches = m0
        else:
            matches = [text_prefix + protect_filename(f) for f in m0]

    # Mark directories by appending '/'
    matches = [x + '/' if os.path.isdir(x) else x for x in matches]

    return matches

