def complete(self, text=None, line_buffer=None, cursor_pos=None):
    # Set default cursor position if not provided
    if cursor_pos is None:
        cursor_pos = len(line_buffer) if text is None else len(text)

    # If text is None or empty, use the line buffer
    if not text:
        text = self.splitter.split_line(line_buffer, cursor_pos)

    # If no line buffer is provided, assume the input text is the entire buffer
    if line_buffer is None:
        line_buffer = text

    # Initialize line_buffer and text_until_cursor
    self.line_buffer = line_buffer
    self.text_until_cursor = self.line_buffer[:cursor_pos]

    # Clear previous completions
    self.matches = []

    # Dispatch custom completers
    custom_res = self.dispatch_custom_completer(text)
    if custom_res is not None:
        self.matches = custom_res
    else:
        # Extend matches with results from each matcher
        if self.merge_completions:
            self.matches = []
        for matcher in self.matchers:
            try:
                self.matches.extend(matcher(text))
            except:
                sys.excepthook(*sys.exc_info())

        # Break if matches are found
        if self.matches:
            break

    # Sort and remove duplicates
    self.matches = sorted(set(self.matches))

    # Return text and matches
    return text, self.matches

