    # Define markers for zip and egg files
    markers = ['.zip' + os.sep, '.egg' + os_sep]

    # Check if the filename contains a zip or egg marker
    for marker in markers:
        if marker in filename:
            # Split the filename into parts based on the marker
            parts = filename.split(marker)

            try:
                # Create a zipimporter object
                zi = zipimport.zipimporter(parts[0] + marker[:-1])
            except zipimport.ZipImportError:
                continue

            try:
                # Get the data from the zip file
                data = zi.get_data(parts[1])
            except IOError:
                continue

            # Convert the data to a string and return it
            return to_string(data)

    # Return None if no data is found
    return None

