def parse_step(cls, ctxt, step_addr, step_conf):
    """
    Parses a step configuration and returns a Step object.

    Args:
        cls: The class to instantiate the Step object.
        ctxt: The context for the step.
        step_addr: The address of the step.
        step_conf: The configuration for the step, which can be a string or a dictionary.

    Returns:
        A Step object or a list of Step objects.

    Raises:
        ConfigError: If the step configuration is invalid.
    """
    if isinstance(step_conf, six.string_types):
        step_conf = {step_conf: None}
    elif not isinstance(step_conf, collections.Mapping):
        raise ConfigError('Unable to parse step configuration: expecting string or dictionary, not "%s"' % step_conf.__class__.__name__, step_addr)

    action_item = None
    mod_items = {}
    kwargs = {}

    for key, key_conf in step_conf.items():
        if key in cls.schemas:
            utils.schema_validate(key_conf, cls.schemas[key], ConfigError, key, step_addr=step_addr)
            kwargs[key] = key_conf
        elif key in entry.points[NAMESPACE_ACTION]:
            if action_item is not None:
                raise ConfigError('Bad step configuration: action "%s" specified, but action "%s" already processed' % (key, action_item.name), step_addr)
            action_item = StepItem(entry.points[NAMESPACE_ACTION][key], key, key_conf)
        elif key in entry.points[NAMESPACE_MODIFIER]:
            mod_class = entry.points[NAMESPACE_MODIFIER][key]
            mod_items.setdefault(mod_class.priority, []).append(StepItem(mod_class, key, key_conf))
        else:
            raise ConfigError('Bad step configuration: unable to resolve action "%s"' % key, step_addr)

    if action_item is None:
        raise ConfigError('Bad step configuration: no action specified', step_addr)

    action_type = Modifier.STEP if action_item.cls.step_action else Modifier.NORMAL
    modifiers = []

    for mod_item in utils.iter_prio_dict(mod_items):
        if mod_item.cls.restriction & action_type == 0:
            raise ConfigError('Bad step configuration: modifier "%s" is incompatible with the action "%s"' % (mod_item.name, action_item.name), step_addr)
        modifier = mod_item.init(ctxt, step_addr)
        modifiers.append(modifier)
        action_item.conf = modifier.action_conf(ctxt,

