        # Attempt to get the profile directory location from configuration
        location = self.config.ProfileDir.location
    except AttributeError:
        # If location is not specified, find it by profile name
        try:
            p = ProfileDir.find_profile_dir_by_name(self.ipython_dir, self.profile, self.config)
        except ProfileDirError:
            # If not found, create it (always create default profile)
