                    self.log.fatal(f"Could not create profile: {self.profile}")
                    self.exit(1)
                else:
                    self.log.info(f"Created profile dir: {p.location}")
            else:
                self.log.fatal(f"Profile {self.profile} not found.")
                self.exit(1)
        else:
            self.log.info(f"Using existing profile dir: {p.location}")
    else:
        # If location is fully specified
        try:
            p = ProfileDir.find_profile_dir(location, self.config)
        except ProfileDirError:
            # If not found, create it
            if self.auto_create:
                try:
                    p = ProfileDir.create_profile_dir(location, self.config)
