        # Pause the heartbeat channel if it exists.
        if self._hb_channel is not None:
            self._hb_channel.pause()

        # Attempt to kill the kernel.
        try:
            self.kernel.kill()
        except OSError as e:
            # Handle specific errors on Windows and Unix.
            if sys.platform == 'win32':
                if e.winerror != 5:
                    raise
            else:
                from errno import ESRCH
                if e.errno != ESRCH:
                    raise

        # Reset the kernel reference.
        self.kernel = None
    else:
        raise RuntimeError("Cannot kill kernel. No kernel is running!")

