def import_item(name):
    # Split the name into package and object
    package = '.'.join(name.split('.')[0:-1])
    obj = name.split('.')[-1]

    # If there is a package, import the module and get the object
    if package:
        module = __import__(package, fromlist=[obj])
        try:
            pak = module.__dict__[obj]
        except KeyError:
            raise ImportError('No module named %s' % obj)
        return pak
    else:
        # If no package, directly import the object
        return __import__(obj)

