def _flush_control(self, sock):
    if self._ignored_control_replies <= 0:
        return
    idents, msg = self.session.recv(sock, mode=zmq.NOBLOCK)
    while msg is not None:
        self._ignored_control_replies -= 1
        if self.debug:
            pprint(msg)
        idents, msg = self.session.recv(sock, mode=zmq.NOBLOCK)

