def _flush_iopub(self, sock):
    while True:
        idents, msg = self.session.recv(sock, mode=zmq.NOBLOCK)
        if msg is None:
            break
        if self.debug:
            pprint(msg)
        parent = msg['parent_header']
        if not parent:
            continue
        msg_id = parent['msg_id']
        content = msg['content']
        header = msg['header']
        msg_type = header['msg_type']
        md = self.metadata[msg_id]
        if msg_type == 'stream':
            name = content['name']
            s = md.get(name, '')
            md[name] = s + content['data']
        elif msg_type == 'pyerr':
            md.update({'pyerr': self._unwrap_exception(content)})
        elif msg_type == 'pyin':
            md.update({'pyin': content['code']})
        elif msg_type == 'display_data':
            md['outputs'].append(content)
        elif msg_type == 'pyout':
            md['pyout'] = content
        elif msg_type == 'status':
            if content['execution_state'] == 'idle':
                md['outputs_ready'] = True
        self.metadata[msg_id] = md

