def _raw_parse(self):
    # Initialize excluded lines if an exclusion pattern is provided
    if self.exclude:
        self.excluded = self.lines_matching(self.exclude)

    # Tokenize the text to find excluded suites, docstrings, and multi-line statements
    indent = 0
    exclude_indent = 0
    excluding = False
    prev_toktype = token.INDENT
    first_line = None
    empty = True
    tokgen = generate_tokens(self.text)

    for toktype, ttext, (slineno, _), (elineno, _), ltext in tokgen:
        if self.show_tokens:
            print("%10s %5s %-20r %r" % (tokenize.tok_name.get(toktype, toktype), nice_pair((slineno, elineno)), ttext, ltext))

        if toktype == token.INDENT:
            indent += 1
        elif toktype == token.DEDENT:
            indent -= 1
        elif toktype == token.NAME and ttext == 'class':
            self.classdefs.add(slineno)
        elif toktype == token.OP and ttext == ':':
            if not excluding and elineno in self.excluded:
                exclude_indent = indent
                excluding = True
        elif toktype == token.STRING and prev_toktype == token.INDENT:
            self.docstrings.update(range(slineno, elineno + 1))
        elif toktype == token.NEWLINE:
            if first_line is not None and elineno != first_line:
                rng = (first_line, elineno)
                for l in range(first_line, elineno + 1):
                    self.multiline[l] = rng
                first_line = None
            if ttext.strip() and toktype != tokenize.COMMENT:
                empty = False
                if first_line is None:
                    first_line = slineno
            if excluding and indent <= exclude_indent:
                excluding = False
                if excluding:
                    self.excluded.add(elineno)
            prev_toktype = toktype

        # Find the starts of executable statements
        if not empty:
            self.statement_starts.update(self.byte_parser._find_statements())

