def first_lines(self, lines, *ignores):
    ignore = set()
    for ign in ignores:
        ignore.update(ign)
    lset = set()
    for l in lines:
        if l in ignore:
            continue
        new_l = self.first_line(l)
        if new_l not in ignore:
            lset.add(new_l)
    return lset


