def _split_into_chunks(self):
    # Initialize variables
    chunks = []
    chunk = None
    bytes_lines_map = dict(self._bytes_lines())
    block_stack = []
    ignore_branch = 0
    ult = penult = None
    jump_to = set()
    bytecodes = list(ByteCodes(self.code.co_code))

    # Collect all jump-to points
    for bc in bytecodes:
        if bc.jump_to >= 0:
            jump_to.add(bc.jump_to)

    chunk_lineno = 0

    # Walk through bytecodes to build chunks
    for bc in bytecodes:
        start_new_chunk = False
        first_chunk = False

        if bc.offset in bytes_lines_map:
            start_new_chunk = True
            chunk_lineno = bytes_lines_map[bc.offset]
            first_chunk = True
        elif bc.offset in jump_to:
            start_new_chunk = True
        elif bc.op in OPS_CHUNK_BEGIN:
            start_new_chunk = True

        if not chunk or start_new_chunk:
            if chunk:
                chunk.exits.add(bc.offset)
            chunk = Chunk(bc.offset, chunk_lineno, first_chunk)
            chunks.append(chunk)

        # Handle opcode
        if bc.jump_to >= 0 and bc.op not in OPS_NO_JUMP:
            if ignore_branch:
                ignore_branch -= 1
            else:
                chunk.exits.add(bc.jump_to)
        if bc.op in OPS_CODE_END:
            chunk.exits.add(-self.code.co_firstlineno)
        if bc.op in OPS_PUSH_BLOCK:
            block_stack.append((bc.op, bc.jump_to))
        if bc.op in OPS_POP_BLOCK:
            block_stack.pop()
        if bc.op in OPS_CHUNK_END:
            if bc.op == OP_BREAK_LOOP:
                chunk.exits.add(block_stack[-1][1])
                chunk = None
            elif bc.op == OP_END_FINALLY:
                for block in reversed(block_stack):
                    if block[0] in OPS_EXCEPT_BLOCKS:
                        chunk.exits.add(block[1])
                        break
