def init_connector(self):
    """Initialize the connector by setting up SSH connection parameters."""
    self.using_ssh = bool(self.sshkey or self.sshserver)
    if self.sshkey and not self.sshserver:
        self.sshserver = self.url.split('://')[1].split(':')[0]
    if self.using_ssh:
        if tunnel.try_passwordless_ssh(self.sshserver, self.sshkey, self.paramiko):
            password = False
        else:
            password = getpass("SSH Password for %s: " % self.sshserver)
    else:
        password = False

def connect(self, url):
    """Establish a connection to the specified URL, optionally using SSH tunneling."""
    url = disambiguate_url(url, self.location)
    if self.using_ssh:
        self.log.debug("Tunneling connection to %s via %s" % (url, self.sshserver))
        return tunnel.tunnel_connection(self, url, self.sshserver, keyfile=self.sshkey, paramiko=self.paramiko, password=password)
    else:
        return self.s.connect(url)

def maybe_tunnel(self, url):
    """Establish a tunnel to the specified URL, optionally using SSH tunneling, without completing the connection."""
    url = disambiguate_url(url, self.location)
    if self.using_ssh:
        self.log.debug("Tunneling connection to %s via %s" % (url, self.sshserver))
        url, tunnelobj = tunnel.open_tunnel(url, self.sshserver, keyfile=self.sshkey, paramiko=self.paramiko, password=password)
        return url
    return connect, maybe_tunnel

