def restart_kernel(self, message, now=False):
    # Check if a custom restart is configured
    if self.custom_restart:
        self.custom_restart_requested.emit()
    # Check if a kernel is currently managed
    elif self.kernel_manager.has_kernel:
        # Pause the heartbeat channel to prevent further warnings
        self.kernel_manager.hb_channel.pause()
        # Prompt the user to restart the kernel
        if self.confirm_restart:
            buttons = QtGui.QMessageBox.Yes | QtGui.QMessageBox.No
            result = QtGui.QMessageBox.question(self, 'Restart kernel?', message, buttons)
            do_restart = result == QtGui.QMessageBox.Yes
        else:
            # If confirmation is not required, proceed with the restart
            do_restart = True
        # Restart the kernel if the user confirms or if confirmation is not required
        if do_restart:
            try:
                self.kernel_manager.restart_kernel(now=now)
            except RuntimeError:
                self._append_plain_text('Kernel started externally. Cannot restart.\n', before_prompt=True)
            else:
                self.reset()
        else:
            # Unpause the heartbeat if the user declines
            self.kernel_manager.hb_channel.unpause()
    else:
        # Inform the user that the kernel process is either remote or unspecified
        self._append_plain_text('Kernel process is either remote or unspecified. Cannot restart.\n', before_prompt=True)

