def as_dict(self, attrs=None, ad_value=None):
    """
    Converts the object's attributes to a dictionary, excluding certain methods and attributes.

    Parameters:
    - attrs (list): A list of attribute names to include in the dictionary. If None, all attributes are included.
    - ad_value (any): The value to use for attributes that raise an AccessDenied exception.

    Returns:
    - dict: A dictionary containing the object's attributes and their values.

    Notes:
    - Excludes methods and attributes starting with 'send_signal', 'suspend', 'resume', 'terminate', 'kill', 'wait', 'is_running', 'as_dict', 'parent', 'get_children', and 'nice'.
    - If an attribute is callable, it is called to get its value. Special handling for 'get_cpu_percent'.
    - If an attribute raises an AccessDenied exception, the specified ad_value is used.
    - If an attribute is not implemented, it is skipped unless explicitly requested.
    - Special handling for attributes starting with 'get' and 'getcwd'.
    """
    excluded_names = {'send_signal', 'suspend', 'resume', 'terminate', 'kill', 'wait', 'is_running', 'as_dict', 'parent', 'get_children', 'nice'}
    ret_dict = {}

    for name in set(attrs or dir(self)):
        if name.startswith('_') or name.startswith('set_') or name in excluded_names:
            continue

        try:
            attr = getattr(self, name)
            if callable(attr):
                if name == 'get_cpu_percent':
                    ret = attr(interval=0)
                else:
                    ret = attr()
            else:
                ret = attr
        except AccessDenied:
            ret = ad_value
        except NotImplementedError:
            if attrs:
                raise
            continue

        if name.startswith('get'):
            if name[3] == '_':
                name = name[4:]
            elif name == 'getcwd':
                name = 'cwd'

        ret_dict[name] = ret

    return ret_dict

