def get_process_name(self):
    # Retrieve the process name using the platform implementation
    name = self._platform_impl.get_process_name()

    # Check if the operating system is POSIX (Unix-like)
    if os.name == 'posix':
        try:
            # Attempt to get the command line of the process
            cmdline = self.cmdline
        except AccessDenied:
            pass
        else:
            if cmdline:
                # Extract the base name of the command line
                extended_name = os.path.basename(cmdline[0])
                # Check if the extended name starts with the original name
                if extended_name.startswith(name):
                    name = extended_name

    # Store the final process name in the platform implementation
    self._platform_impl._process_name = name
    return name

