def exe(self):
    def guess_it(fallback):
        # Try to guess the executable from the command line
        cmdline = self.cmdline
        if cmdline and hasattr(os, 'access') and hasattr(os, 'X_OK'):
            exe = cmdline[0]
            rexe = os.path.realpath(exe)
            if os.path.isabs(rexe) and os.path.isfile(rexe) and os.access(rexe, os.X_OK):
                return exe
        if isinstance(fallback, AccessDenied):
            raise fallback
        return fallback

    try:
        exe = self._platform_impl.get_process_exe()
    except AccessDenied:
        err = sys.exc_info()[1]
        return guess_it(fallback=err)
    else:
        if not exe:
            try:
                exe = guess_it(fallback=exe)
            except AccessDenied:
                pass
        return exe

