def suspend(self):
    # Safety measure to ensure the current process is still running
    if not self.is_running():
        name = self._platform_impl._process_name
        raise NoSuchProcess(self.pid, name)  # Raise an exception if the process is not running

    # Suspend the process based on the platform
    if hasattr(self._platform_impl, "suspend_process"):
        self._platform_impl.suspend_process()  # Use platform-specific method to suspend the process
    else:
        self.send_signal(signal.SIGSTOP)  # Use generic signal to suspend the process on POSIX systems

