def _event_filter_page_keypress(self, event):
    key = event.key()
    ctrl_down = self._control_key_down(event.modifiers())
    alt_down = event.modifiers() & QtCore.Qt.AltModifier

    if ctrl_down:
        if key == QtCore.Qt.Key_O:
