            intercept = True
    elif alt_down:
        if key == QtCore.Qt.Key_Greater:
            self._page_control.moveCursor(QtGui.QTextCursor.End)
            intercepted = True
        elif key == QtCore.Qt.Key_Less:
            self._page_control.moveCursor(QtGui.QTextCursor.Start)
