def Walk(root='.', recurse=True, pattern='*'):
    """
    Walks through the directory tree rooted at 'root' and yields the paths of files that match the 'pattern'.
    If 'recurse' is False, it only walks through the current directory.
    """
    for path, subdirs, files in os.walk(root):
        for name in files:
            if fnmatch.fnmatch(name, pattern):
                yield os.path.join(path, name)
        if not recurse:
            break

