def timeUnit(elapsed, avg, est_end):
    minute = 60
    hr = 3600
    day = 86400

    # Determine the unit for elapsed time
    if elapsed <= 3 * minute:
        unit_elapsed = (elapsed, "secs")
    elif elapsed > 3 * minute and elapsed <= 3 * hr:
        unit_elapsed = (elapsed / 60, "mins")
    else:
        unit_elapsed = (elapsed / 3600, "hr")

    # Determine the unit for average time
    if avg <= 3 * minute:
        unit_avg = (avg, "secs")
    elif avg > 3 * minute and avg <= 3 * hr:
        unit_avg = (avg / 60, "mins")
    else:
        unit_avg = (avg / 3600, "hr")

    # Determine the unit for estimated end time
    if est_end <= 3 * minute:
        unit_estEnd = (est_end, "secs")
    elif est_end > 3 * minute and est_end <= 3 * hr:
        unit_estEnd = (est_end / 60, "mins")
    else:
        unit_estEnd = (est_end / 3600, "hr")

    return [unit_elapsed, unit_avg, unit_estEnd]

