        needquote = True
        result.append('"')

    # Process each character in the argument
    for c in arg:
        if c == '\\':
            nb += 1
        elif c == '"':
            # Double preceding backslashes and add a "
            result.append('\\' * (nb * 2) + '\\"')
            nb = 0
        else:
            if nb:
                result.append('\\' * nb)
                nb = 0
            result.append(c)

    # Handle trailing backslashes
    if nb:
        result.append('\\' * nb)

    # Close the quote if needed
    if needquote:
        result.append('\\' * nb)
        result.append('"')

    return ''.join(result)

