def mutable(obj):
    base_cls = type(obj)
    class Proxy(base_cls):
        def __getattribute__(self, name):
            try:
                return super().__getattribute__(name)
            except AttributeError:
                return getattr(obj, name)
    update_wrapper(Proxy, base_cls, updated=())
    return Proxy()

