def readonly(obj, *, error_on_set=False):
    """
    Creates a read-only proxy for the given object.

    Args:
        obj: The object to be made read-only.
        error_on_set: If True, raises an AttributeError when trying to set an attribute.

    Returns:
        A proxy object that provides read-only access to the original object.
    """
    base_cls = type(obj)
    class ReadonlyProxy(base_cls):
        def __getattribute__(self, name):
            return getattr(obj, name)

        def __setattr__(self, name, value):
            if error_on_set:
                raise AttributeError('cannot set readonly object.')

    return update_wrapper(ReadonlyProxy, base_cls, updated=())

