def filefind(filename, path_dirs=None):
    # Remove surrounding quotes from the filename
    filename = filename.strip('"').strip("'")

    # Check if the filename is an absolute path and exists
    if os.path.isabs(filename) and os.path.isfile(filename):
        return filename

    # If path_dirs is None, set it to an empty tuple
    if path_dirs is None:
        path_dirs = ("",)
    # If path_dirs is a string, convert it to a tuple containing that string
    elif isinstance(path_dirs, basestring):
        path_dirs = (path_dirs,)

    # Iterate through each path in path_dirs
    for path in path_dirs:
        # Replace '.' with the current working directory
        if path == '.':
            path = os.getcwdu()

        # Construct the full path by joining the current path and filename
        testname = expand_path(os.path.join(path, filename))

        # Check if the constructed path exists and is a file
        if os.path.isfile(testname):
            return os.path.abspath(testname)

    # Raise an IOError if the file does not exist in any of the search paths
