def _get_num_cpus():
    """
    Determines the number of CPUs on the system by trying different approaches:
    1. Uses `os.sysconf("SC_NPROCESSORS_ONLN")` which is considered safer and used by the multiprocessing module.
    2. If the first approach fails, it reads `/proc/cpuinfo` to count the number of processors.
    3. As a last resort, it reads `/proc/stat` to count the number of CPU entries.
    If none of these methods succeed, it raises a `RuntimeError`.
    """
    try:
        return os.sysconf("SC_NPROCESSORS_ONLN")
    except ValueError:
        num = 0
        with open('/proc/cpuinfo', 'r') as f:
            lines = f.readlines()
        for line in lines:
            if line.lower().startswith('processor'):
                num += 1
        if num == 0:
            with open('/proc/stat', 'r') as f:
                lines = f.readlines()
            search = re.compile('cpu\d')
            for line in lines:
                line = line.split(' ')[0]
                if search.match(line):
                    num += 1
        if num == 0:
            raise RuntimeError("can't determine number of CPUs")
        return num

