def timed(limit):
    def decorate(func):
        def newfunc(*args, **kwargs):
            start = time.time()
            func(*args, **kwargs)
            end = time.time()
            if end - start > limit:
                raise TimeExpired("Time limit (%s) exceeded" % limit)
