def generic(func):
    """Decorator to dispatch function calls based on the type or object of the first argument."""
    _sentinel = object()

    def _by_class(*args, **kwargs):
        cls = args[0].__class__
        for t in type(cls.__name__, (cls, object), { }).__mro__:
            f = _gbt(t, _sentinel)
            if f is not _sentinel:
                return f(*args, **kwargs)
        else:
            return func(*args, **kwargs)

    _by_type = {object: func}
    try:
        _by_type[InstanceType] = _by_class
    except NameError:
        # Python 3
        pass

    _gbt = _by_type.get

    def when_type(*types):
        """Decorator to add a method that will be called for the given types."""
        for t in types:
            if not isinstance(t, classtypes):
                raise TypeError("%r is not a type or class" % (t,))
        def decorate(f):
            for t in types:
                if _by_type.setdefault(t, f) is not f:
                    raise TypeError("%r already has method for type %r" % (func, t))
            return f
        return decorate

    _by_object = { }

    _gbo = _by_object.get

    def when_object(*obs):
        """Decorator to add a method to be called for the given object(s)."""
        def decorate(f):
            for o in obs:
                if _by_object.setdefault(id(o), (o, f))[1] is not f:
                    raise TypeError("%r already has method for object %r" % (func, o))
            return f
        return decorate

    def dispatch(*args, **kwargs):
        f = _gbo(id(args[0]), _sentinel)
        if f is _sentinel:
            for t in type(args[0]).__mro__:
                f = _gbt(t, _sentinel)
                if f is not _sentinel:
                    return f(*args, **kwargs)
            else:
                return func(*args, **kwargs)
        else:
            return f[1](*args, **kwargs)

    dispatch.__name__ = func.__name__
    dispatch.__dict__ = func.__dict__.copy()
    dispatch.__doc__ = func.__doc__
    dispatch.__module__

