def validateAttrib(self, method, cls=None):
    # Iterate through each attribute group in self.attribs
    for group in self.attribs:
        match = True
        for key, value in group:
            attr = get_method_attr(method, cls, key)
            if callable(value):
                if not value(key, method, cls):
                    match = False
                    break
            elif value is True:
                if not bool(attr):
                    match = False
                    break
            elif value is False:
                if bool(attr):
                    match = False
                    break
            elif type(attr) in (list, tuple):
                if str(value).lower() not in [str(x).lower() for x in attr]:
                    match = False
                    break
            else:
                if value != attr and str(value).lower() != str(attr).lower():
                    match = False
                    break
        any = any or match
    if any:
        return None
    return False

