def thread(function, sequence, cores=None, runSeries=False, quiet=False):
    # Create a ThreadPool with the specified number of cores or use all available cores if not specified
    if cores is None:
        pool = ThreadPool()
    else:
        pool = ThreadPool(cores)

    # Measure the time taken to process the sequence
    tic = time.time()

    # If runSeries is False, use the ThreadPool to process the sequence in parallel
    if runSeries is False:
        try:
            results = pool.map(function, sequence)
            pool.close()
            pool.join()
        except:
            print('thread Failed... running in series :-(')
            results = series(sequence, function)
    else:
        results = series(sequence, function)

    toc = time.time()
    elapsed = toc - tic

    # Print the elapsed time if quiet is False
    if quiet is False:
        if cores is None:
            print("Elapsed time: %s  :-)\n" % str(elapsed))
        else:
            print("Elapsed time: %s  on %s threads :-)\n" % (str(elapsed), str(cores)))

    return results

