def prop(func=None, *, field=_UNSET, get: bool = True, set: bool = True, del_: bool = False, default=_UNSET, types: tuple = _UNSET):
    def wrap(func):
        if not callable(func):
            raise TypeError
        prop_name = func.__name__
        key = field if key is _UNSET else '_' + prop_name
        fget, fset, fdel = None, None, None
        if get:
            def fget(self):
                try:
                    return self.__dict__[key]
                except KeyError:
                    if default is not _UNSET:
                        return default
                    raise AttributeError(f"'{type(self).__name__}' object has no attribute '{key}'")
        if set:
            def fset(self, val):
                if types is not _UNSET and not isinstance(val, types):
                    if isinstance(types, tuple):
                        types_name = tuple(x.__name__ for x in types)
                    else:
                        types_name = types.__name__
                    raise TypeError(f'type of {type(self).__name__}.{prop_name} must be {types_name}; got {type(val).__name__} instead')
                self.__dict__[key] = val
        if del_:
            def fdel(self):
                del self.__dict__[key]
        return property(fget, fset, fdel, func.__doc__)
    return wrap(func) if func else wrap

