def check(self, completed, failed=None):
    if len(self) == 0:
        return True
    against = set()
    if self.success:
        against = completed
    if failed is not None and self.failure:
        against = against.union(failed)
    if self.all:
        return self.issubset(against)
    else:
        return not self.isdisjoint(against)


