            records = {rec['msg_id']: rec for rec in matches}
        except Exception:
            content = error.wrap_exception()
        self.session.send(self.query, "result_reply", content=content, parent=msg, ident=client_id)
        return

    records = {}
    for msg_id in msg_ids:
        if msg_id in self.pending:
            pending.append(msg_id)
        elif msg_id in self.all_completed:
            completed.append(msg_id)
        if not statusonly:
