def recv(self, socket, mode=zmq.NOBLOCK, content=True, copy=True):
    """
    Receives a message from a ZeroMQ socket.

    Parameters:
    - socket: The ZeroMQ socket or a ZMQStream object.
    - mode: The receive mode (default is zmq.NOBLOCK).
    - content: Whether to deserialize the message content (default is True).
    - copy: Whether to copy the message data (default is True).

    Returns:
    - A tuple containing the identity list and the deserialized message content.

    Raises:
    - zmq.ZMQError: If an error occurs during the receive operation.
    - Exception: If an error occurs during deserialization.
    """
    if isinstance(socket, ZMQStream):
        socket = socket.socket

    try:
        msg_list = socket.recv_multipart(mode, copy=copy)
    except zmq.ZMQError as e:
        if e.errno == zmq.EAGAIN:
            return None, None
        else:
            raise

    idents, msg_list = self.feed_identities(msg_list, copy)
    try:
        return idents, self.unserialize(msg_list, content=content, copy=copy)
    except Exception as e:
        raise e

