def stop(self):
    # Set the stopped flag if called from a different thread than the one that started it
    if self.thread != threading.currentThread():
        return

    # Check if the trace function has changed and warn if it has
    if hasattr(sys, "gettrace") and self.warn:
        if sys.gettrace() != self._trace:
            msg = "Trace function changed, measurement is likely wrong: %r"
            self.warn(msg % (sys.gettrace(),))

    # Set the trace function to None to stop tracing
    sys.settrace(None)

