def _installation_trace(self, frame_unused, event_unused, arg_unused):
    # Remove the current trace function from the sys.settrace
    sys.settrace(None)
    # Install the real tracer function
    fn = self._start_tracer()
    # Invoke the real trace function with the current event
    if fn:
        fn = fn(frame_unused, event_unused, arg_unused)
    # Return the new trace function to continue tracing in the current scope
    return fn

